INSERT INTO "RSK_ISUP_INDICATOR_PARA_DTL"("PARA_CODE", "PARA_GRANULARITY", "PARA_DISPLAY_TYPE", "CONTENT", "REDIS_FIELD", "IS_FRESH_CAN_TRD", "CREATE_USER", "CREATE_DEPT", "CREATE_TIME", "UPDATE_USER", "UPDATE_TIME") VALUES ('CPZZC', '03', 'SQL', 'select PORTFOLIO_ID as RKEY,nvl(sum(TDY_ASSET_VALUE),0) as RVALUE from PTL_PORTFOLIO_VALUATION	
where   CDATE=date''${valDate}''-1 group by PORTFOLIO_ID	
	
union all	
   select m.PTL_BAG_ID as RKEY,	
   ( select NVL(SUM(TDY_ASSET_VALUE),0) AS RVALUE	
  from PTL_PORTFOLIO_VALUATION where CDATE = date''${valDate}''-1 AND PORTFOLIO_ID in (select t1.PORTFOLIO_ID from RSK_PORTFOLIO_PACKAGE_DTL t1 	
  inner join PTL_PORTFOLIO t2 on t1.PORTFOLIO_ID=t2.PORTFOLIO_ID and t2.MDATE>date''${valDate}'' where t1.PTL_BAG_ID=m.PTL_BAG_ID)	
   )	
   from RSK_PORTFOLIO_PACKAGE m', 'portfolioCode', 'N', 'whmcp', '2222222', sysdate, 'whmcp', sysdate);
INSERT INTO "RSK_ISUP_INDICATOR_PARA_DTL"("PARA_CODE", "PARA_GRANULARITY", "PARA_DISPLAY_TYPE", "CONTENT", "REDIS_FIELD", "IS_FRESH_CAN_TRD", "CREATE_USER", "CREATE_DEPT", "CREATE_TIME", "UPDATE_USER", "UPDATE_TIME") VALUES ('CPZZC', '01', 'SQL', 'select PORTFOLIO_ID as RKEY,nvl(sum(TDY_ASSET_VALUE),0) as RVALUE from PTL_PORTFOLIO_VALUATION	
where   CDATE=date''${valDate}''-1 group by PORTFOLIO_ID	
	
union all	
   select m.PTL_BAG_ID as RKEY,	
   ( select NVL(SUM(TDY_ASSET_VALUE),0) AS RVALUE	
  from PTL_PORTFOLIO_VALUATION where CDATE = date''${valDate}''-1 AND PORTFOLIO_ID in (select t1.PORTFOLIO_ID from RSK_PORTFOLIO_PACKAGE_DTL t1 	
  inner join PTL_PORTFOLIO t2 on t1.PORTFOLIO_ID=t2.PORTFOLIO_ID and t2.MDATE>date''${valDate}'' where t1.PTL_BAG_ID=m.PTL_BAG_ID)	
   )	
   from RSK_PORTFOLIO_PACKAGE m', 'portfolioCode', 'N', 'whmcp', '2222222', sysdate, 'whmcp', sysdate);
INSERT INTO "RSK_ISUP_INDICATOR_PARA_DTL"("PARA_CODE", "PARA_GRANULARITY", "PARA_DISPLAY_TYPE", "CONTENT", "REDIS_FIELD", "IS_FRESH_CAN_TRD", "CREATE_USER", "CREATE_DEPT", "CREATE_TIME", "UPDATE_USER", "UPDATE_TIME") VALUES ('CPZZC', '04', 'SQL', 'select sum(amount) as tradeAmt from				
(				
select nvl(sum(TDY_ASSET_VALUE),0) as amount from PTL_PORTFOLIO_VALUATION				
where PORTFOLIO_ID in ${portfolioCode}  and CDATE=date''${valDate}''-1 
				
union ALL				
    select nvl(sum(decode(n.PS,''T06'',n.TRADE_AMT)), 0)				
    + nvl(sum(decode(n.PS,''T16'',n.TRADE_AMT)), 0)				
    - nvl(sum(decode(n.PS,''T08'',n.TRADE_AMT)), 0)				
    - nvl(sum(decode(n.PS,''T18'',n.TRADE_AMT)), 0) as amount				
    from TRD_PRODUCT_DEAL n  
    LEFT JOIN TRD_PRODUCT_DEAL_ADD n1 ON n.TRADE_ID =n1.TRADE_ID 
    where  n1.PORTFOLIO_ID in ${portfolioCode} and n.FINPROD_TYPE in (''F02'',''F08'',''F25'',''F04'') and n.TRADE_DATE=date''${valDate}'' and n.PS in (''T06'',''T16'',''T12'')				
)', 'portfolioCode', 'N', 'whmcp', '2222222', sysdate, 'whmcp', sysdate);
INSERT INTO "RSK_ISUP_INDICATOR_PARA_DTL"("PARA_CODE", "PARA_GRANULARITY", "PARA_DISPLAY_TYPE", "CONTENT", "REDIS_FIELD", "IS_FRESH_CAN_TRD", "CREATE_USER", "CREATE_DEPT", "CREATE_TIME", "UPDATE_USER", "UPDATE_TIME") VALUES ('CPZZC', '05', 'SQL', 'SELECT NVL(SUM(TDY_ASSET_VALUE),0) AS amount
FROM PTL_PORTFOLIO_VALUATION
WHERE PORTFOLIO_ID IN ${portfolioCode} AND CDATE = date''${valDate}''', 'portfolioCode', 'N', 'whmcp', '2222222', sysdate, 'whmcp', sysdate);
INSERT INTO "RSK_ISUP_INDICATOR_PARA_DTL"("PARA_CODE", "PARA_GRANULARITY", "PARA_DISPLAY_TYPE", "CONTENT", "REDIS_FIELD", "IS_FRESH_CAN_TRD", "CREATE_USER", "CREATE_DEPT", "CREATE_TIME", "UPDATE_USER", "UPDATE_TIME") VALUES ('CPZCLZCGM', '02', 'SQL', 'select PORTFOLIO_ID RKEY,sum(TRADE_AMT) as RVALUE from																							
 (																							
select m.PORTFOLIO_ID,nvl(sum(nvl(m.TDY_FLOAT_INGPL, 0) + nvl(m.DSC_COST_AMT, 0)),0) as TRADE_AMT from PTL_SEC_VALUTION m 																							
  INNER JOIN FIN_PRODUCT_ADD PFP on m.FINPROD_ID = PFP.FINPROD_ID and PFP.INVEST_NATURE =''01''																							
  LEFT JOIN FIN_PRODUCT_TYPE FPT ON m.FINPROD_ID=FPT.FINPROD_ID AND FPT.BRANCH=''0''																							
where   m.CDATE =date''${valDate}''-1  AND m.PORTFOLIO_ID!=m.FINPROD_ID																							
AND (FPT.TYPE_8 NOT IN (''F02'') OR (FPT.TYPE_8 =''F02'' AND FPT.TYPE_7 NOT IN (''04'',''03''))) group by m.PORTFOLIO_ID 																							
																							
union all																							
select  m.PORTFOLIO_ID,																							
  sum(nvl(m.TDY_FLOAT_INGPL, 0) + nvl(m.DSC_COST_AMT, 0)) as  TRADE_AMT from PTL_SEC_VALUTION m																							
INNER JOIN FIN_TRADE_PRODUCT n on m.FINPROD_ID = n.FINPROD_ID and n.FINPROD_TYPE2 in (''F03'',''F05'',''F09'')																							
where  m.CDATE =date''${valDate}''-1  group by m.PORTFOLIO_ID 																							
) group by PORTFOLIO_ID 																							
																							
union all																							
   select t.PTL_BAG_ID as RKEY,																							
   ( SELECT NVL(SUM(nvl(M.TDY_FLOAT_INGPL, 0) + nvl(M.DSC_COST_AMT, 0)),0)  AS RVALUE 																							
	FROM PTL_SEC_VALUTION M																						
	INNER JOIN FIN_PRODUCT_ADD PFP																						
	ON M.FINPROD_ID = PFP.FINPROD_ID AND PFP.INVEST_NATURE = ''01''																						
	LEFT JOIN FIN_PRODUCT_TYPE FPT ON m.FINPROD_ID=FPT.FINPROD_ID AND FPT.BRANCH=''0''																						
	WHERE M.CDATE = date''${valDate}''-1  AND m.PORTFOLIO_ID!=m.FINPROD_ID 																						
	AND (FPT.TYPE_8 NOT IN (''F02'') OR (FPT.TYPE_8 =''F02'' AND FPT.TYPE_7 NOT IN (''04'',''03''))) AND 																						
	M.PORTFOLIO_ID in (   select t1.PORTFOLIO_ID from RSK_PORTFOLIO_PACKAGE_DTL t1  inner join PTL_PORTFOLIO t2 on t1.PORTFOLIO_ID=t2.PORTFOLIO_ID and t2.MDATE>date''${valDate}'' where t1.PTL_BAG_ID=t.PTL_BAG_ID)																						
   )																							
   from RSK_PORTFOLIO_PACKAGE t', 'portfolioCode', 'N', 'whmcp', '2222222', sysdate, 'whmcp', sysdate);
INSERT INTO "RSK_ISUP_INDICATOR_PARA_DTL"("PARA_CODE", "PARA_GRANULARITY", "PARA_DISPLAY_TYPE", "CONTENT", "REDIS_FIELD", "IS_FRESH_CAN_TRD", "CREATE_USER", "CREATE_DEPT", "CREATE_TIME", "UPDATE_USER", "UPDATE_TIME") VALUES ('CPZCLZCGM', '03', 'SQL', 'select PORTFOLIO_ID RKEY,sum(TRADE_AMT) as RVALUE from																							
 (																							
select m.PORTFOLIO_ID,nvl(sum(nvl(m.TDY_FLOAT_INGPL, 0) + nvl(m.DSC_COST_AMT, 0)),0) as TRADE_AMT from PTL_SEC_VALUTION m 																							
  INNER JOIN FIN_PRODUCT_ADD PFP on m.FINPROD_ID = PFP.FINPROD_ID and PFP.INVEST_NATURE =''01''																							
  LEFT JOIN FIN_PRODUCT_TYPE FPT ON m.FINPROD_ID=FPT.FINPROD_ID AND FPT.BRANCH=''0''																							
where   m.CDATE =date''${valDate}''-1  AND m.PORTFOLIO_ID!=m.FINPROD_ID																							
AND (FPT.TYPE_8 NOT IN (''F02'') OR (FPT.TYPE_8 =''F02'' AND FPT.TYPE_7 NOT IN (''04'',''03''))) group by m.PORTFOLIO_ID 																							
																							
union all																							
select  m.PORTFOLIO_ID,																							
  sum(nvl(m.TDY_FLOAT_INGPL, 0) + nvl(m.DSC_COST_AMT, 0)) as  TRADE_AMT from PTL_SEC_VALUTION m																							
INNER JOIN FIN_TRADE_PRODUCT n on m.FINPROD_ID = n.FINPROD_ID and n.FINPROD_TYPE2 in (''F03'',''F05'',''F09'')																							
where  m.CDATE =date''${valDate}''-1  group by m.PORTFOLIO_ID 																							
) group by PORTFOLIO_ID 																							
																							
union all																							
   select t.PTL_BAG_ID as RKEY,																							
   ( SELECT NVL(SUM(nvl(M.TDY_FLOAT_INGPL, 0) + nvl(M.DSC_COST_AMT, 0)),0)  AS RVALUE 																							
	FROM PTL_SEC_VALUTION M																						
	INNER JOIN FIN_PRODUCT_ADD PFP																						
	ON M.FINPROD_ID = PFP.FINPROD_ID AND PFP.INVEST_NATURE = ''01''																						
	LEFT JOIN FIN_PRODUCT_TYPE FPT ON m.FINPROD_ID=FPT.FINPROD_ID AND FPT.BRANCH=''0''																						
	WHERE M.CDATE = date''${valDate}''-1  AND m.PORTFOLIO_ID!=m.FINPROD_ID 																						
	AND (FPT.TYPE_8 NOT IN (''F02'') OR (FPT.TYPE_8 =''F02'' AND FPT.TYPE_7 NOT IN (''04'',''03''))) AND 																						
	M.PORTFOLIO_ID in (   select t1.PORTFOLIO_ID from RSK_PORTFOLIO_PACKAGE_DTL t1  inner join PTL_PORTFOLIO t2 on t1.PORTFOLIO_ID=t2.PORTFOLIO_ID and t2.MDATE>date''${valDate}'' where t1.PTL_BAG_ID=t.PTL_BAG_ID)																						
   )																							
   from RSK_PORTFOLIO_PACKAGE t', 'portfolioCode', 'N', 'whmcp', '2222222', sysdate, 'whmcp', sysdate);
INSERT INTO "RSK_ISUP_INDICATOR_PARA_DTL"("PARA_CODE", "PARA_GRANULARITY", "PARA_DISPLAY_TYPE", "CONTENT", "REDIS_FIELD", "IS_FRESH_CAN_TRD", "CREATE_USER", "CREATE_DEPT", "CREATE_TIME", "UPDATE_USER", "UPDATE_TIME") VALUES ('CPZCLZCGM', '01', 'SQL', 'select PORTFOLIO_ID RKEY,sum(TRADE_AMT) as RVALUE from																							
 (																							
select m.PORTFOLIO_ID,nvl(sum(nvl(m.TDY_FLOAT_INGPL, 0) + nvl(m.DSC_COST_AMT, 0)),0) as TRADE_AMT from PTL_SEC_VALUTION m 																							
  INNER JOIN FIN_PRODUCT_ADD PFP on m.FINPROD_ID = PFP.FINPROD_ID and PFP.INVEST_NATURE =''01''																							
  LEFT JOIN FIN_PRODUCT_TYPE FPT ON m.FINPROD_ID=FPT.FINPROD_ID AND FPT.BRANCH=''0''																							
where   m.CDATE =date''${valDate}''-1  AND m.PORTFOLIO_ID!=m.FINPROD_ID																							
AND (FPT.TYPE_8 NOT IN (''F02'') OR (FPT.TYPE_8 =''F02'' AND FPT.TYPE_7 NOT IN (''04'',''03''))) group by m.PORTFOLIO_ID 																							
																							
union all																							
select  m.PORTFOLIO_ID,																							
  sum(nvl(m.TDY_FLOAT_INGPL, 0) + nvl(m.DSC_COST_AMT, 0)) as  TRADE_AMT from PTL_SEC_VALUTION m																							
INNER JOIN FIN_TRADE_PRODUCT n on m.FINPROD_ID = n.FINPROD_ID and n.FINPROD_TYPE2 in (''F03'',''F05'',''F09'')																							
where  m.CDATE =date''${valDate}''-1  group by m.PORTFOLIO_ID 																							
) group by PORTFOLIO_ID 																							
																							
union all																							
   select t.PTL_BAG_ID as RKEY,																							
   ( SELECT NVL(SUM(nvl(M.TDY_FLOAT_INGPL, 0) + nvl(M.DSC_COST_AMT, 0)),0)  AS RVALUE 																							
	FROM PTL_SEC_VALUTION M																						
	INNER JOIN FIN_PRODUCT_ADD PFP																						
	ON M.FINPROD_ID = PFP.FINPROD_ID AND PFP.INVEST_NATURE = ''01''																						
	LEFT JOIN FIN_PRODUCT_TYPE FPT ON m.FINPROD_ID=FPT.FINPROD_ID AND FPT.BRANCH=''0''																						
	WHERE M.CDATE = date''${valDate}''-1  AND m.PORTFOLIO_ID!=m.FINPROD_ID 																						
	AND (FPT.TYPE_8 NOT IN (''F02'') OR (FPT.TYPE_8 =''F02'' AND FPT.TYPE_7 NOT IN (''04'',''03''))) AND 																						
	M.PORTFOLIO_ID in (   select t1.PORTFOLIO_ID from RSK_PORTFOLIO_PACKAGE_DTL t1  inner join PTL_PORTFOLIO t2 on t1.PORTFOLIO_ID=t2.PORTFOLIO_ID and t2.MDATE>date''${valDate}'' where t1.PTL_BAG_ID=t.PTL_BAG_ID)																						
   )																							
   from RSK_PORTFOLIO_PACKAGE t', 'portfolioCode', 'N', 'whmcp', '2222222', sysdate, 'whmcp', sysdate);
INSERT INTO "RSK_ISUP_INDICATOR_PARA_DTL"("PARA_CODE", "PARA_GRANULARITY", "PARA_DISPLAY_TYPE", "CONTENT", "REDIS_FIELD", "IS_FRESH_CAN_TRD", "CREATE_USER", "CREATE_DEPT", "CREATE_TIME", "UPDATE_USER", "UPDATE_TIME") VALUES ('CPZCLZCGM', '04', 'SQL', 'select sum(TRADE_AMT) as tradeAmt from																		
 (																		
select sum(nvl(m.TDY_FLOAT_INGPL, 0) + nvl(m.DSC_COST_AMT, 0)) as TRADE_AMT from PTL_SEC_VALUTION m 																		
  INNER JOIN FIN_PRODUCT_ADD PFP																		
  on m.FINPROD_ID = PFP.FINPROD_ID and PFP.INVEST_NATURE =''01''																		
   LEFT JOIN FIN_PRODUCT_TYPE FPT ON m.FINPROD_ID=FPT.FINPROD_ID AND FPT.BRANCH=''0''																		
where m.PORTFOLIO_ID in ${portfolioCode}  and  m.CDATE =date''${valDate}''-1 	 AND m.PORTFOLIO_ID!=m.FINPROD_ID																	
	AND (FPT.TYPE_8 NOT IN (''F02'') OR (FPT.TYPE_8 =''F02'' AND FPT.TYPE_7 NOT IN (''04'',''03'')))																	
union all																		
select 																		
  sum(nvl(m.TDY_FLOAT_INGPL, 0) + nvl(m.DSC_COST_AMT, 0)) as  TRADE_AMT from PTL_SEC_VALUTION m																		
INNER JOIN FIN_TRADE_PRODUCT n on m.FINPROD_ID = n.FINPROD_ID and n.FINPROD_TYPE2 in (''F03'',''F05'',''F09'')																		
where m.PORTFOLIO_ID in ${portfolioCode}  and  m.CDATE =date''${valDate}''-1 																		
																		
union ALL																		
  select																		
  nvl(sum(decode(n.PS,''T07'',n.TRADE_AMT)),0)																		
  +nvl(sum(decode(n.PS,''T17'',n.TRADE_AMT)),0)																		
  -nvl(sum(decode(n.PS,''T09'',n.TRADE_AMT)),0)																		
  -nvl(sum(decode(n.PS,''T19'',n.TRADE_AMT)),0) as TRADE_AMT  																		
  from  TRD_PRODUCT_DEAL n 																		
  INNER JOIN FIN_TRADE_PRODUCT t2 on t2.FINPROD_ID=n.FINPROD_ID and t2.FINPROD_TYPE2 in (''F03'',''F05'',''F09'')	
  LEFT JOIN TRD_PRODUCT_DEAL_ADD n1 ON n.TRADE_ID =n1.TRADE_ID
  where n1.PORTFOLIO_ID in ${portfolioCode} and n.TRADE_DATE=date''${valDate}'' and n.PS in (''T07'',''T09'',''T17'',''T19'')																		
																		
union ALL																		
  select																		
   nvl(sum(decode(n.PS,''T01'',n.TRADE_AMT)),0)																		
  +nvl(sum(decode(n.PS,''T04'',n.TRADE_AMT)),0)																		
  +nvl(sum(decode(n.PS,''T36'',n.TRADE_AMT)),0)																		
  -nvl(sum(decode(n.PS,''T03'',n.TRADE_AMT)),0)																		
  -nvl(sum(decode(n.PS,''T12'',n.TRADE_AMT)),0)																		
  -nvl(sum(decode(n.PS,''T02'',n.TRADE_AMT)),0)																		
  -nvl(sum(decode(n.PS,''T13'',n.TRADE_AMT)),0)																		
  -nvl(sum(decode(n.PS,''T14'',n.TRADE_AMT)),0)																		
  -nvl(sum(decode(n.PS,''T20'',n.TRADE_AMT)),0)																		
  -nvl(sum(decode(n.PS,''T05'',n.TRADE_AMT)),0) as  TRADE_AMT																		
  from TRD_PRODUCT_DEAL n  																		
    INNER JOIN FIN_PRODUCT_ADD PFP																		
   on n.FINPROD_ID = PFP.FINPROD_ID and PFP.INVEST_NATURE =''01''
   LEFT JOIN TRD_PRODUCT_DEAL_ADD n1 ON n.TRADE_ID =n1.TRADE_ID 
   LEFT JOIN FIN_PRODUCT_TYPE FPT ON n.FINPROD_ID=FPT.FINPROD_ID AND FPT.BRANCH=''0''																		
  where n1.PORTFOLIO_ID in ${portfolioCode} and n.TRADE_DATE=date''${valDate}'' and n.PS in (''T01'',''T02'',''T03'',''T12'',''T04'',''T13'',''T05'',''T36'',''T14'',''T20'')																		
  AND (FPT.TYPE_6 NOT IN (''84'',''85'') OR (FPT.TYPE_6 IN (''84'',''85'') AND FPT.TYPE_7 NOT IN (''04'',''05''))	)																	
)', 'portfolioCode', 'N', 'whmcp', '2222222', sysdate, 'whmcp', sysdate);
INSERT INTO "RSK_ISUP_INDICATOR_PARA_DTL"("PARA_CODE", "PARA_GRANULARITY", "PARA_DISPLAY_TYPE", "CONTENT", "REDIS_FIELD", "IS_FRESH_CAN_TRD", "CREATE_USER", "CREATE_DEPT", "CREATE_TIME", "UPDATE_USER", "UPDATE_TIME") VALUES ('SSGSKLTGB', '04', 'SQL', 'SELECT RVALUE,RKEY,RKEYCN FROM (		
	SELECT (SELECT nvl(sum(s.C_SHARES),0) FROM MST_SHARE_PRICE s WHERE s.SHARES_ID=t2.FINPROD_MARKET_ID AND s.DEAL_DATE=(	
		SELECT max(DEAL_DATE) FROM MST_SHARE_PRICE m WHERE m.SHARES_ID=t2.FINPROD_MARKET_ID and m.DEAL_DATE<=date''${valDate}'')
	) AS RVALUE,	
    T2.FINPROD_ID RKEY,		
	t2.FINPROD_NAME RKEYCN FROM PTL_SEC_VALUTION T1 	
	INNER JOIN FIN_PRODUCT t2 ON t1.FINPROD_ID=t2.FINPROD_ID AND T2.FINPROD_TYPE2 =''F10''	
	WHERE t1.PORTFOLIO_ID IN ${portfolioCode} AND t1.CDATE=date''${valDate}''	
	)', 'assetCode', 'N', 'admin', '2222222', sysdate, 'admin', sysdate);
INSERT INTO "RSK_ISUP_INDICATOR_PARA_DTL"("PARA_CODE", "PARA_GRANULARITY", "PARA_DISPLAY_TYPE", "CONTENT", "REDIS_FIELD", "IS_FRESH_CAN_TRD", "CREATE_USER", "CREATE_DEPT", "CREATE_TIME", "UPDATE_USER", "UPDATE_TIME") VALUES ('SPJJRYSPLZCGM', '02', 'SQL', 'select m.PORTFOLIO_ID as RKEY,nvl(sum(nvl(m.TDY_FLOAT_INGPL, 0) + nvl(m.DSC_COST_AMT, 0)),0) as  RVALUE from PTL_SEC_VALUTION m	
INNER JOIN FIN_PRODUCT_ADD PFP	
on m.FINPROD_ID = PFP.FINPROD_ID and PFP.INVEST_NATURE =''03''	
LEFT JOIN FIN_PRODUCT_TYPE FPT ON m.FINPROD_ID=FPT.FINPROD_ID AND FPT.BRANCH=''0''	
where  m.CDATE =date''${valDate}''-1  AND m.PORTFOLIO_ID!=m.FINPROD_ID 	
AND (FPT.TYPE_8 NOT IN (''F02'') OR (FPT.TYPE_8 =''F02'' AND FPT.TYPE_7 NOT IN (''04'',''03''))) group by m.PORTFOLIO_ID	
union all	
   select t.PTL_BAG_ID as RKEY,	
   ( SELECT NVL(SUM(nvl(m.TDY_FLOAT_INGPL, 0) + nvl(m.DSC_COST_AMT, 0)),0)  AS RVALUE 	
	FROM PTL_SEC_VALUTION M
	INNER JOIN FIN_PRODUCT_ADD PFP
	ON M.FINPROD_ID = PFP.FINPROD_ID AND PFP.INVEST_NATURE = ''03''
LEFT JOIN FIN_PRODUCT_TYPE FPT ON m.FINPROD_ID=FPT.FINPROD_ID AND FPT.BRANCH=''0''	
	WHERE M.CDATE = date''${valDate}''-1  AND m.PORTFOLIO_ID!=m.FINPROD_ID 
	AND (FPT.TYPE_8 NOT IN (''F02'') OR (FPT.TYPE_8 =''F02'' AND FPT.TYPE_7 NOT IN (''04'',''03''))) AND 
	M.PORTFOLIO_ID in (   select t1.PORTFOLIO_ID from RSK_PORTFOLIO_PACKAGE_DTL t1  inner join PTL_PORTFOLIO t2 on t1.PORTFOLIO_ID=t2.PORTFOLIO_ID and t2.MDATE>date''${valDate}'' where t1.PTL_BAG_ID=t.PTL_BAG_ID)
   )	
   from RSK_PORTFOLIO_PACKAGE t', 'portfolioCode', 'Y', 'admin', '2222222', sysdate, 'admin', sysdate);
INSERT INTO "RSK_ISUP_INDICATOR_PARA_DTL"("PARA_CODE", "PARA_GRANULARITY", "PARA_DISPLAY_TYPE", "CONTENT", "REDIS_FIELD", "IS_FRESH_CAN_TRD", "CREATE_USER", "CREATE_DEPT", "CREATE_TIME", "UPDATE_USER", "UPDATE_TIME") VALUES ('CPZCLZCGM', '05', 'SQL', 'select sum(TRADE_AMT) as tradeAmt from												
 (												
select nvl(sum(nvl(m.TDY_FLOAT_INGPL, 0) + nvl(m.DSC_COST_AMT, 0)),0) as TRADE_AMT from PTL_SEC_VALUTION m 												
  INNER JOIN FIN_PRODUCT_ADD PFP												
  on m.FINPROD_ID = PFP.FINPROD_ID and PFP.INVEST_NATURE =''01''												
   LEFT JOIN FIN_PRODUCT_TYPE FPT ON m.FINPROD_ID=FPT.FINPROD_ID AND FPT.BRANCH=''0''												
where m.PORTFOLIO_ID in ${portfolioCode}  and  m.CDATE =date''${valDate}'' AND m.PORTFOLIO_ID!=m.FINPROD_ID	 											
AND (FPT.TYPE_8 NOT IN (''F02'') OR (FPT.TYPE_8 =''F02'' AND FPT.TYPE_7 NOT IN (''04'',''03'')))												
union all												
select 												
  sum(nvl(m.TDY_FLOAT_INGPL, 0) + nvl(m.DSC_COST_AMT, 0)) as  TRADE_AMT from PTL_SEC_VALUTION m												
INNER JOIN FIN_TRADE_PRODUCT n on m.FINPROD_ID = n.FINPROD_ID and n.FINPROD_TYPE2 in (''F03'',''F05'',''F09'')												
where m.PORTFOLIO_ID in ${portfolioCode}  and  m.CDATE =date''${valDate}''												
)', 'portfolioCode', 'N', 'whmcp', '2222222', sysdate, 'whmcp', sysdate);
INSERT INTO "RSK_ISUP_INDICATOR_PARA_DTL"("PARA_CODE", "PARA_GRANULARITY", "PARA_DISPLAY_TYPE", "CONTENT", "REDIS_FIELD", "IS_FRESH_CAN_TRD", "CREATE_USER", "CREATE_DEPT", "CREATE_TIME", "UPDATE_USER", "UPDATE_TIME") VALUES ('HBJJCCGM', '01', 'SQL', 'select m.PORTFOLIO_ID as RKEY,nvl(sum(nvl(m.TDY_FLOAT_INGPL, 0) + nvl(m.DSC_COST_AMT, 0)+ nvl(m.TDY_INTINCEXP, 0)+ nvl(m.DELAY_PAY_AMT, 0)),0) as RVALUE from PTL_SEC_VALUTION m	

	INNER  JOIN FIN_PRODUCT_TYPE n on m.FINPROD_ID=n.FINPROD_ID and n.TYPE_6=''84''

	where   m.CDATE =date''${valDate}'' group by m.PORTFOLIO_ID', 'portfolioCode', 'N', 'whmcp', '2222222', sysdate, 'whmcp', sysdate);
