INSERT INTO "RSK_ISUP_INDICATOR_PARA_DTL"("PARA_CODE", "PARA_GRANULARITY", "PARA_DISPLAY_TYPE", "CONTENT", "REDIS_FIELD", "IS_FRESH_CAN_TRD", "CREATE_USER", "CREATE_DEPT", "CREATE_TIME", "UPDATE_USER", "UPDATE_TIME") VALUES ('DYGLF', '04', 'SQL', 'select 1 from dual', 'portfolioCode', 'N', 'jjpei', '2222222', sysdate, 'jjpei', sysdate);
INSERT INTO "RSK_ISUP_INDICATOR_PARA_DTL"("PARA_CODE", "PARA_GRANULARITY", "PARA_DISPLAY_TYPE", "CONTENT", "REDIS_FIELD", "IS_FRESH_CAN_TRD", "CREATE_USER", "CREATE_DEPT", "CREATE_TIME", "UPDATE_USER", "UPDATE_TIME") VALUES ('DYGLF', '02', 'SQL', 'SELECT case(SELECT count(*) FROM (SELECT
	ORG_NO
FROM
	INF_ORG_CORRELATION
START WITH
	COR_ORGID =(
	SELECT
	CASE
			fp.FINPROD_TYPE2 WHEN ''F01'' THEN fp.ISSUER
			WHEN ''F06'' THEN fp.manager
			WHEN ''F07'' THEN fp.ISSUER
			WHEN ''F10'' THEN fp.ISSUER
			WHEN ''F18'' THEN fp.financier
			WHEN ''F17'' THEN fp.manager
			WHEN ''F16'' THEN fp.trustee_id
			ELSE ''null''
	END AS org
	FROM
		FIN_PRODUCT fp
	WHERE
		fp.FINPROD_ID = ${assetCode} )
CONNECT BY
	PRIOR ORG_NO = COR_ORGID
UNION ALL
SELECT
	COR_ORGID
FROM
	INF_ORG_CORRELATION a
START WITH
	a.ORG_NO =(
	SELECT
	CASE
			fp.FINPROD_TYPE2 WHEN ''F01'' THEN fp.ISSUER
			WHEN ''F06'' THEN fp.manager
			WHEN ''F07'' THEN fp.ISSUER
			WHEN ''F10'' THEN fp.ISSUER
			WHEN ''F18'' THEN fp.financier
			WHEN ''F17'' THEN fp.manager
			WHEN ''F16'' THEN fp.trustee_id
			ELSE ''null''
	END AS org
	FROM
		FIN_PRODUCT fp
	WHERE
		fp.FINPROD_ID = ${assetCode} )
CONNECT BY
	PRIOR a.COR_ORGID = a.ORG_NO )
) WHEN  0  THEN  0
	  ELSE 10
	  END AS RVALUE
	
	FROM dual', 'portfolioCode', 'N', 'jjpei', '2222222', sysdate, 'jjpei', sysdate);
