INSERT INTO "RSK_ISUP_INDICATOR_PARA_DTL"("PARA_CODE", "PARA_GRANULARITY", "PARA_DISPLAY_TYPE", "CONTENT", "REDIS_FIELD", "IS_FRESH_CAN_TRD", "CREATE_USER", "CREATE_DEPT", "CREATE_TIME", "UPDATE_USER", "UPDATE_TIME") VALUES ('HBJJCCGM', '04', 'SQL', 'select nvl(sum(nvl(RVALUE, 0)),0) as RVALUE from	
 (	select nvl(sum(nvl(m.TDY_FLOAT_INGPL, 0) + nvl(m.DSC_COST_AMT, 0)+ nvl(m.TDY_INTINCEXP, 0)+ nvl(m.DELAY_PAY_AMT, 0)),0) as RVALUE from PTL_SEC_VALUTION m
	INNER  JOIN FIN_PRODUCT_TYPE n on m.FINPROD_ID=n.FINPROD_ID and n.TYPE_6=''84''
	where m.PORTFOLIO_ID in ${portfolioCode}  and  m.CDATE =date''${valDate}'' -1 
union ALL	
	  select nvl(sum(decode(n.PS,''T04'',n.TRADE_AMT)), 0)
	  + nvl(sum(decode(n.PS,''T36'',n.TRADE_AMT)), 0)
	  - nvl(sum(decode(n.PS,''T23'',n.TRADE_AMT)), 0) 
	  + nvl(sum(decode(n.PS,''T01'',n.TRADE_AMT)), 0)
	  - nvl(sum(decode(n.PS,''T02'',n.TRADE_AMT)), 0) 
	  as RVALUE
	  from  TRD_PRODUCT_DEAL n 
	  INNER  JOIN FIN_PRODUCT_TYPE  m on m.FINPROD_ID=n.FINPROD_ID and m.TYPE_6=''84''
	    LEFT JOIN TRD_PRODUCT_DEAL_ADD n1 ON n.TRADE_ID =n1.TRADE_ID 
	  where  n1.PORTFOLIO_ID in ${portfolioCode}  and n.TRADE_DATE=date''${valDate}'' and n.PS in (''T04'',''T23'',''T01'',''T02'',''T36'')
 ) s1', 'portfolioCode', 'N', 'whmcp', '2222222', sysdate, 'whmcp', sysdate);
INSERT INTO "RSK_ISUP_INDICATOR_PARA_DTL"("PARA_CODE", "PARA_GRANULARITY", "PARA_DISPLAY_TYPE", "CONTENT", "REDIS_FIELD", "IS_FRESH_CAN_TRD", "CREATE_USER", "CREATE_DEPT", "CREATE_TIME", "UPDATE_USER", "UPDATE_TIME") VALUES ('HBJJCCGM', '05', 'SQL', 'select nvl(sum(nvl(m.TDY_FLOAT_INGPL, 0) + nvl(m.DSC_COST_AMT, 0)+ nvl(m.TDY_INTINCEXP, 0)+ nvl(m.DELAY_PAY_AMT, 0)),0) as RVALUE from PTL_SEC_VALUTION m	

INNER  JOIN FIN_PRODUCT_TYPE n on m.FINPROD_ID=n.FINPROD_ID and n.TYPE_6=''84''	

where m.PORTFOLIO_ID in ${portfolioCode}  and  m.CDATE =date''${valDate}''', 'portfolioCode', 'N', 'whmcp', '2222222', sysdate, 'whmcp', sysdate);
