 m.PORTFOLIO_ID as RKEY,sum(nvl(m.DSC_COST_AMT, 0)) as  RVALUE from PTL_SEC_VALUTION m	

INNER JOIN FIN_TRADE_PRODUCT n on m.FINPROD_ID = n.FINPROD_ID and n.FINPROD_TYPE in (''F02'',''F04'')	

where  m.CDATE =date''${valDate}''-1  group by m.PORTFOLIO_ID	

	

union all	

   select t.PTL_BAG_ID as RKEY,	

   ( select sum(nvl(m.DSC_COST_AMT, 0)) as  RVALUE from PTL_SEC_VALUTION m	

