INSERT INTO "RSK_ISUP_INDICATOR_PARA_DTL"("PARA_CODE", "PARA_GRANULARITY", "PARA_DISPLAY_TYPE", "CONTENT", "REDIS_FIELD", "IS_FRESH_CAN_TRD", "CREATE_USER", "CREATE_DEPT", "CREATE_TIME", "UPDATE_USER", "UPDATE_TIME") VALUES ('FXJZC', '03', 'SQL', 'select	
 sum(nvl(t1.TDY_FLOAT_INGPL, 0) + nvl(t1.DSC_COST_AMT, 0)+ nvl(t1.TDY_INTINCEXP, 0)+ nvl(t1.DELAY_PAY_AMT, 0)) as RVALUE, t1.PORTFOLIO_ID as RKEY	
from PTL_SEC_VALUTION t1	
   left join FIN_PRODUCT t2	on t1.FINPROD_ID = t2.FINPROD_ID 
   left join FIN_TRADE_PRODUCT t3 on t1.FINPROD_ID = t3.FINPROD_ID 	
	where  t1.CDATE = date''${valDate}''-1 AND t1.PORTFOLIO_ID!=t1.FINPROD_ID 
	and ((t3.FINPROD_TYPE is null and t2.FINPROD_TYPE is not null) or t3.FINPROD_TYPE not in (''F02'', ''F08'', ''F25''))
group by t1.PORTFOLIO_ID', 'portfolioCode', 'N', 'whmcp', '2222222', sysdate, 'whmcp', sysdate);
INSERT INTO "RSK_ISUP_INDICATOR_PARA_DTL"("PARA_CODE", "PARA_GRANULARITY", "PARA_DISPLAY_TYPE", "CONTENT", "REDIS_FIELD", "IS_FRESH_CAN_TRD", "CREATE_USER", "CREATE_DEPT", "CREATE_TIME", "UPDATE_USER", "UPDATE_TIME") VALUES ('FXJZC', '01', 'SQL', 'select	
 sum(nvl(t1.TDY_FLOAT_INGPL, 0) + nvl(t1.DSC_COST_AMT, 0)+ nvl(t1.TDY_INTINCEXP, 0)+ nvl(t1.DELAY_PAY_AMT, 0)) as RVALUE, t1.PORTFOLIO_ID as RKEY	
from PTL_SEC_VALUTION t1	
   left join FIN_PRODUCT t2	on t1.FINPROD_ID = t2.FINPROD_ID 
   left join FIN_TRADE_PRODUCT t3 on t1.FINPROD_ID = t3.FINPROD_ID 	
	where  t1.CDATE = date''${valDate}''-1  AND t1.PORTFOLIO_ID!=t1.FINPROD_ID 
	and ((t3.FINPROD_TYPE is null and t2.FINPROD_TYPE is not null) or t3.FINPROD_TYPE not in (''F02'', ''F08'', ''F25''))
group by t1.PORTFOLIO_ID', 'portfolioCode', 'N', 'whmcp', '2222222', sysdate, 'whmcp', sysdate);
INSERT INTO "RSK_ISUP_INDICATOR_PARA_DTL"("PARA_CODE", "PARA_GRANULARITY", "PARA_DISPLAY_TYPE", "CONTENT", "REDIS_FIELD", "IS_FRESH_CAN_TRD", "CREATE_USER", "CREATE_DEPT", "CREATE_TIME", "UPDATE_USER", "UPDATE_TIME") VALUES ('FXJZC', '02', 'SQL', 'select	
 sum(nvl(t1.TDY_FLOAT_INGPL, 0) + nvl(t1.DSC_COST_AMT, 0)+ nvl(t1.TDY_INTINCEXP, 0)+ nvl(t1.DELAY_PAY_AMT, 0)) as RVALUE, t1.PORTFOLIO_ID as RKEY	
from PTL_SEC_VALUTION t1	
   left join FIN_PRODUCT t2	on t1.FINPROD_ID = t2.FINPROD_ID 
   left join FIN_TRADE_PRODUCT t3 on t1.FINPROD_ID = t3.FINPROD_ID 	
	where  t1.CDATE = date''${valDate}''-1 AND t1.PORTFOLIO_ID!=t1.FINPROD_ID 
	and ((t3.FINPROD_TYPE is null and t2.FINPROD_TYPE is not null) or t3.FINPROD_TYPE not in (''F02'', ''F08'', ''F25''))
group by t1.PORTFOLIO_ID', 'portfolioCode', 'N', 'whmcp', '2222222', sysdate, 'whmcp', sysdate);
INSERT INTO "RSK_ISUP_INDICATOR_PARA_DTL"("PARA_CODE", "PARA_GRANULARITY", "PARA_DISPLAY_TYPE", "CONTENT", "REDIS_FIELD", "IS_FRESH_CAN_TRD", "CREATE_USER", "CREATE_DEPT", "CREATE_TIME", "UPDATE_USER", "UPDATE_TIME") VALUES ('FXJZC', '04', 'SQL', 'select sum(TRADE_AMT) as tradeAmt FROM (				
  select nvl(sum(nvl(m.TDY_FLOAT_INGPL, 0) + nvl(m.DSC_COST_AMT, 0)+ nvl(m.TDY_INTINCEXP, 0)+ nvl(m.DELAY_PAY_AMT, 0)),0) as  TRADE_AMT from PTL_SEC_VALUTION m				
   left join FIN_PRODUCT t2	on m.FINPROD_ID = t2.FINPROD_ID 			
   left join FIN_TRADE_PRODUCT t3 on m.FINPROD_ID = t3.FINPROD_ID 				
	where m.PORTFOLIO_ID in ${portfolioCode} and  m.CDATE = date''${valDate}''-1 AND m.PORTFOLIO_ID!=m.FINPROD_ID			
	and ((t3.FINPROD_TYPE is null and t2.FINPROD_TYPE is not null) or t3.FINPROD_TYPE not in (''F02'', ''F08'', ''F25''))			
				
union ALL				
  select				
      nvl(sum(decode(n.PS,''T01'',n.TRADE_AMT)),0)				
      +nvl(sum(decode(n.PS,''T07'',n.TRADE_AMT)),0)				
      +nvl(sum(decode(n.PS,''T17'',n.TRADE_AMT)),0)				
	  +nvl(sum(decode(n.PS,''T04'',n.TRADE_AMT)),0)			
  	  +nvl(sum(decode(n.PS,''T36'',n.TRADE_AMT)),0)			
	  -nvl(sum(decode(n.PS,''T03'',n.TRADE_AMT)),0)			
	  -nvl(sum(decode(n.PS,''T12'',n.TRADE_AMT)),0)			
	  -nvl(sum(decode(n.PS,''T02'',n.TRADE_AMT)),0)			
      -nvl(sum(decode(n.PS,''T09'',n.TRADE_AMT)),0)				
      -nvl(sum(decode(n.PS,''T19'',n.TRADE_AMT)),0)				
	  -nvl(sum(decode(n.PS,''T13'',n.TRADE_AMT)),0)			
      -nvl(sum(decode(n.PS,''T14'',n.TRADE_AMT)),0)				
      -nvl(sum(decode(n.PS,''T20'',n.TRADE_AMT)),0)				
	  -nvl(sum(decode(n.PS,''T05'',n.TRADE_AMT)),0)  as  TRADE_AMT  			
  from TRD_PRODUCT_DEAL n 				
    left join FIN_PRODUCT t2  on n.FINPROD_ID = t2.FINPROD_ID				
  left join FIN_TRADE_PRODUCT t3 on n.FINPROD_ID = t3.FINPROD_ID	
    LEFT JOIN TRD_PRODUCT_DEAL_ADD n1 ON n.TRADE_ID =n1.TRADE_ID 

  where  n1.PORTFOLIO_ID in ${portfolioCode} and n.TRADE_DATE=date''${valDate}'' 				
    and ((t3.FINPROD_TYPE is null and t2.FINPROD_TYPE is not null) or t3.FINPROD_TYPE not in (''F02'', ''F08'', ''F25''))				
    and n.PS in (''T01'',''T07'',''T17'',''T02'',''T03'',''T04'',''T05'',''T12'',''T13'',''T09'',''T19'',''T36'',''T14'',''T20'')				
    )', 'portfolioCode', 'N', 'whmcp', '2222222', sysdate, 'whmcp', sysdate);
INSERT INTO "RSK_ISUP_INDICATOR_PARA_DTL"("PARA_CODE", "PARA_GRANULARITY", "PARA_DISPLAY_TYPE", "CONTENT", "REDIS_FIELD", "IS_FRESH_CAN_TRD", "CREATE_USER", "CREATE_DEPT", "CREATE_TIME", "UPDATE_USER", "UPDATE_TIME") VALUES ('FXJZC', '05', 'SQL', 'select nvl(sum(nvl(m.TDY_FLOAT_INGPL, 0) + nvl(m.DSC_COST_AMT, 0)+ nvl(m.TDY_INTINCEXP, 0)+ nvl(m.DELAY_PAY_AMT, 0)),0) as  TRADE_AMT from PTL_SEC_VALUTION m			
   left join FIN_PRODUCT t2	on m.FINPROD_ID = t2.FINPROD_ID 		
   left join FIN_TRADE_PRODUCT t3 on m.FINPROD_ID = t3.FINPROD_ID 			
	where m.PORTFOLIO_ID in ${portfolioCode} and  m.CDATE = date''${valDate}'' AND m.PORTFOLIO_ID!=m.FINPROD_ID 		
	and ((t3.FINPROD_TYPE is null and t2.FINPROD_TYPE is not null) or t3.FINPROD_TYPE not in (''F02'', ''F08'', ''F25''))', 'portfolioCode', 'N', 'whmcp', '2222222', sysdate, 'whmcp', sysdate);
