INSERT INTO "RSK_ISUP_INDICATOR_PARA_DTL"("PARA_CODE", "PARA_GRANULARITY", "PARA_DISPLAY_TYPE", "CONTENT", "REDIS_FIELD", "IS_FRESH_CAN_TRD", "CREATE_USER", "CREATE_DEPT", "CREATE_TIME", "UPDATE_USER", "UPDATE_TIME") VALUES ('ZQNHGZZYE', '04', 'SQL', 'select sum(TRADE_AMT) as tradeAmt from	
(	
  select 		sum(nvl(m.DSC_COST_AMT, 0)) as  TRADE_AMT from PTL_SEC_VALUTION m
 INNER JOIN FIN_TRADE_PRODUCT n on m.FINPROD_ID = n.FINPROD_ID and n.FINPROD_TYPE in (''F03'',''F05'')	
