  where n1.PORTFOLIO_ID in ${portfolioCode} and n.TRADE_DATE=date''${valDate}'' and n.PS in (''T09'',''T07'')	
)', 'portfolioCode', 'N', 'whmcp', '2222222', sysdate, 'whmcp', sysdate);
