(  select 	sum(nvl(m.DSC_COST_AMT, 0)) as  TRADE_AMT from PTL_SEC_VALUTION m
  INNER JOIN FIN_TRADE_PRODUCT n on m.FINPROD_ID = n.FINPROD_ID and n.FINPROD_TYPE in (''F02'',''F04'')	
  where m.PORTFOLIO_ID in ${portfolioCode}  and  m.CDATE =date''${valDate}''-1 	
union ALL	
  select	
  nvl(sum(decode(n.PS,''T06'',n.TRADE_AMT)),0)	
  -nvl(sum(decode(n.PS,''T08'',n.TRADE_AMT)),0) as TRADE_AMT  from  TRD_PRODUCT_DEAL n  	
  INNER JOIN FIN_TRADE_PRODUCT t2 on t2.FINPROD_ID=n.FINPROD_ID and t2.FINPROD_TYPE in (''F02'',''F04'')	
    LEFT JOIN TRD_PRODUCT_DEAL_ADD n1 ON n.TRADE_ID =n1.TRADE_ID 
  where n1.PORTFOLIO_ID in ${portfolioCode} and n.TRADE_DATE=date''${valDate}'' and n.PS in (''T06'',''T08'')	
)', 'portfolioCode', 'N', 'whmcp', '2222222', sysdate, 'whmcp', sysdate);
INSERT INTO "RSK_ISUP_INDICATOR_PARA_DTL"("PARA_CODE", "PARA_GRANULARITY", "PARA_DISPLAY_TYPE", "CONTENT", "REDIS_FIELD", "IS_FRESH_CAN_TRD", "CREATE_USER", "CREATE_DEPT", "CREATE_TIME", "UPDATE_USER", "UPDATE_TIME") VALUES ('ZQZGHHNHGZJYE', '05', 'SQL', 'select 	

  sum(nvl(m.DSC_COST_AMT, 0)) as  TRADE_AMT from PTL_SEC_VALUTION m	

INNER JOIN FIN_TRADE_PRODUCT n on m.FINPROD_ID = n.FINPROD_ID and n.FINPROD_TYPE in (''F02'',''F04'')	

where m.PORTFOLIO_ID in ${portfolioCode}  and  m.CDATE =date''${valDate}''', 'portfolioCode', 'N', 'whmcp', '2222222', sysdate, 'whmcp', sysdate);
INSERT INTO "RSK_ISUP_INDICATOR_PARA_DTL"("PARA_CODE", "PARA_GRANULARITY", "PARA_DISPLAY_TYPE", "CONTENT", "REDIS_FIELD", "IS_FRESH_CAN_TRD", "CREATE_USER", "CREATE_DEPT", "CREATE_TIME", "UPDATE_USER", "UPDATE_TIME") VALUES ('XJGZZYYHPJZCXJRZQGM', '02', 'SQL', 'select y1.PORTFOLIO_ID as RKEY,sum(TRADE_AMT)  as RVALUE from						
(						
  select PORTFOLIO_ID,nvl(sum(AMOUNT),0) as  TRADE_AMT from PTL_CASH_POSITION						
  where  HODING_TYPE=''03'' and CDATE =date''${valDate}''-1  group by PORTFOLIO_ID						
						
	union all					
   select t.PTL_BAG_ID as RKEY,						
   ( select nvl(sum(AMOUNT),0) as  TRADE_AMT from PTL_CASH_POSITION						
	where  HODING_TYPE=''03'' and CDATE =date''${valDate}''-1  AND 					
	PORTFOLIO_ID in (   select t1.PORTFOLIO_ID from RSK_PORTFOLIO_PACKAGE_DTL t1  inner join PTL_PORTFOLIO t2 on t1.PORTFOLIO_ID=t2.PORTFOLIO_ID and t2.MDATE>date''${valDate}'' where t1.PTL_BAG_ID=t.PTL_BAG_ID)					
   )						
   from RSK_PORTFOLIO_PACKAGE t						
   						
	union ALL					
  select m.PORTFOLIO_ID,nvl(sum(nvl(m.TDY_FLOAT_INGPL, 0) + nvl(m.DSC_COST_AMT, 0)),0) as  TRADE_AMT from PTL_SEC_VALUTION m						
  INNER JOIN FIN_PRODUCT n on m.FINPROD_ID=n.FINPROD_ID and n.FINPROD_TYPE2 =''F01'' and n.MDATE>=date''${valDate}'' and n.MDATE<=add_months(date''${valDate}'', 12)						
  inner join FIN_PRODUCT_TYPE t3 on n.FINPROD_ID=t3.FINPROD_ID and t3.TYPE_6 in (''B01'',''B03'',''B05'')  and t3.TYPE_8 =''F01''						
  where  m.CDATE=date''${valDate}''-1  AND m.PORTFOLIO_ID!=m.FINPROD_ID group by m.PORTFOLIO_ID						
						
	union all					
   select t.PTL_BAG_ID as RKEY,						
   ( select nvl(sum(nvl(m.TDY_FLOAT_INGPL, 0) + nvl(m.DSC_COST_AMT, 0)),0) as  TRADE_AMT from PTL_SEC_VALUTION m						
  INNER JOIN FIN_PRODUCT n on m.FINPROD_ID=n.FINPROD_ID and n.FINPROD_TYPE2 =''F01'' and n.MDATE>=date''${valDate}'' and n.MDATE<=add_months(date''${valDate}'', 12)						
  inner join FIN_PRODUCT_TYPE t3 on n.FINPROD_ID=t3.FINPROD_ID and t3.TYPE_6 in (''B01'',''B03'',''B05'')  and t3.TYPE_8 =''F01''						
  where  m.CDATE=date''${valDate}''-1  AND m.PORTFOLIO_ID!=m.FINPROD_ID	AND 					
	m.PORTFOLIO_ID in (   select t1.PORTFOLIO_ID from RSK_PORTFOLIO_PACKAGE_DTL t1  inner join PTL_PORTFOLIO t2 on t1.PORTFOLIO_ID=t2.PORTFOLIO_ID and t2.MDATE>date''${valDate}'' where t1.PTL_BAG_ID=t.PTL_BAG_ID)					
   )						
   from RSK_PORTFOLIO_PACKAGE t						
   						
) y1 group by y1.PORTFOLIO_ID', 'portfolioCode', 'N', 'whmcp', '2222222', sysdate, 'whmcp', sysdate);
