INSERT INTO "RSK_ISUP_INDICATOR_PARA_DTL"("PARA_CODE", "PARA_GRANULARITY", "PARA_DISPLAY_TYPE", "CONTENT", "REDIS_FIELD", "IS_FRESH_CAN_TRD", "CREATE_USER", "CREATE_DEPT", "CREATE_TIME", "UPDATE_USER", "UPDATE_TIME") VALUES ('QYLZCGM', '02', 'SQL', 'select m.PORTFOLIO_ID as RKEY,nvl(sum(nvl(m.TDY_FLOAT_INGPL, 0) + nvl(m.DSC_COST_AMT, 0)),0) as  RVALUE from PTL_SEC_VALUTION m	
INNER JOIN FIN_PRODUCT_ADD PFP	
on m.FINPROD_ID = PFP.FINPROD_ID and PFP.INVEST_NATURE =''02''	
LEFT JOIN FIN_PRODUCT_TYPE FPT ON m.FINPROD_ID=FPT.FINPROD_ID AND FPT.BRANCH=''0''	
where  m.CDATE =date''${valDate}''-1  AND m.PORTFOLIO_ID!=m.FINPROD_ID 	
AND (FPT.TYPE_8 NOT IN (''F02'') OR (FPT.TYPE_8 =''F02'' AND FPT.TYPE_7 NOT IN (''04'',''03''))) group by m.PORTFOLIO_ID	
	
union all	
   select t.PTL_BAG_ID as RKEY,	
   ( SELECT NVL(SUM(nvl(M.TDY_FLOAT_INGPL, 0) + nvl(M.DSC_COST_AMT, 0)),0)  AS RVALUE 	
	FROM PTL_SEC_VALUTION M
	INNER JOIN FIN_PRODUCT_ADD PFP
	ON M.FINPROD_ID = PFP.FINPROD_ID AND PFP.INVEST_NATURE = ''02''
	LEFT JOIN FIN_PRODUCT_TYPE FPT ON m.FINPROD_ID=FPT.FINPROD_ID AND FPT.BRANCH=''0''
	WHERE M.CDATE = date''${valDate}''-1  AND m.PORTFOLIO_ID!=m.FINPROD_ID
	AND (FPT.TYPE_8 NOT IN (''F02'') OR (FPT.TYPE_8 =''F02'' AND FPT.TYPE_7 NOT IN (''04'',''03''))) AND 
	M.PORTFOLIO_ID in (   select t1.PORTFOLIO_ID from RSK_PORTFOLIO_PACKAGE_DTL t1  inner join PTL_PORTFOLIO t2 on t1.PORTFOLIO_ID=t2.PORTFOLIO_ID and t2.MDATE>date''${valDate}'' where t1.PTL_BAG_ID=t.PTL_BAG_ID)
   )	
   from RSK_PORTFOLIO_PACKAGE t', 'portfolioCode', 'N', 'whmcp', '2222222', sysdate, 'whmcp', sysdate);
INSERT INTO "RSK_ISUP_INDICATOR_PARA_DTL"("PARA_CODE", "PARA_GRANULARITY", "PARA_DISPLAY_TYPE", "CONTENT", "REDIS_FIELD", "IS_FRESH_CAN_TRD", "CREATE_USER", "CREATE_DEPT", "CREATE_TIME", "UPDATE_USER", "UPDATE_TIME") VALUES ('XJGZZYYHPJZCXJRZQGM', '05', 'SQL', 'select sum(TRADE_AMT) as tradeAmt from	
(	
  select nvl(sum(AMOUNT),0) as  TRADE_AMT from PTL_CASH_POSITION	
  where  PORTFOLIO_ID in ${portfolioCode} and HODING_TYPE=''03'' and CDATE =date''${valDate}''	
union ALL	
  select nvl(sum(nvl(m.TDY_FLOAT_INGPL, 0) + nvl(m.DSC_COST_AMT, 0)),0) as  TRADE_AMT from PTL_SEC_VALUTION m	
  INNER JOIN FIN_PRODUCT n on m.FINPROD_ID=n.FINPROD_ID and n.FINPROD_TYPE2 =''F01'' and n.MDATE>=date''${valDate}'' and n.MDATE<=add_months(date''${valDate}'', 12)	
  inner join FIN_PRODUCT_TYPE t3 on n.FINPROD_ID=t3.FINPROD_ID and t3.TYPE_6 in (''B01'',''B03'',''B05'')  and t3.TYPE_8 =''F01''	
  where  m.PORTFOLIO_ID in ${portfolioCode}  and m.CDATE=date''${valDate}''	
)', 'portfolioCode', 'N', 'whmcp', '2222222', sysdate, 'whmcp', sysdate);
INSERT INTO "RSK_ISUP_INDICATOR_PARA_DTL"("PARA_CODE", "PARA_GRANULARITY", "PARA_DISPLAY_TYPE", "CONTENT", "REDIS_FIELD", "IS_FRESH_CAN_TRD", "CREATE_USER", "CREATE_DEPT", "CREATE_TIME", "UPDATE_USER", "UPDATE_TIME") VALUES ('GMZDDDZZQHJJ', '05', 'SQL', 'SELECT nvl(sum(nvl(RVALUE, 0)),0) as RVALUE,s1.FINPROD_ID as RKEY,s1.FINPROD_NAME RKEYCN FROM (	

 select nvl(sum(nvl(m.TDY_FLOAT_INGPL, 0) + nvl(m.DSC_COST_AMT, 0)+ nvl(m.TDY_INTINCEXP, 0)+ nvl(m.DELAY_PAY_AMT, 0)),0) as RVALUE,m.FINPROD_ID ,n.FINPROD_NAME  from PTL_SEC_VALUTION m	

INNER  JOIN FIN_PRODUCT n on m.FINPROD_ID=n.FINPROD_ID and n.FINPROD_TYPE=''F01''	

where m.PORTFOLIO_ID in ${portfolioCode}  and  m.CDATE =date''${valDate}'' group by m.FINPROD_ID,n.FINPROD_NAME	

	

UNION all	

 select nvl(sum(nvl(m.TDY_FLOAT_INGPL, 0) + nvl(m.DSC_COST_AMT, 0)+ nvl(m.TDY_INTINCEXP, 0)+ nvl(m.DELAY_PAY_AMT, 0)),0) as RVALUE,m.FINPROD_ID ,n.FINPROD_NAME  from PTL_SEC_VALUTION m	

INNER  JOIN FIN_PRODUCT n on m.FINPROD_ID=n.FINPROD_ID and n.FINPROD_TYPE=''F06''	

where m.PORTFOLIO_ID in ${portfolioCode}  and  m.CDATE =date''${valDate}'' group by m.FINPROD_ID,n.FINPROD_NAME	

 ) s1 group by s1.FINPROD_ID,s1.FINPROD_NAME', 'portfolioCode,assetCode', 'N', 'whmcp', '2222222', sysdate, 'whmcp', sysdate);
