select m.PORTFOLIO_ID AS RKEY,nvl(sum(nvl(m.TDY_FLOAT_INGPL, 0) + nvl(m.DSC_COST_AMT, 0)),0) as  RVALUE from PTL_SEC_VALUTION m								
inner join FIN_PRODUCT_TYPE fpt on m.FINPROD_ID=fpt.FINPROD_ID  and fpt.TYPE_8 =''F06'' and fpt.TYPE_6 not in(''P11'')								
where    m.CDATE =date''${valDate}''-1  group by m.PORTFOLIO_ID								
 union all								
   select t.PTL_BAG_ID as RKEY,								
   ( select nvl(sum(nvl(m.TDY_FLOAT_INGPL, 0) + nvl(m.DSC_COST_AMT, 0)),0) as  RVALUE from PTL_SEC_VALUTION m								
   inner join FIN_PRODUCT_TYPE fpt on m.FINPROD_ID=fpt.FINPROD_ID  and fpt.TYPE_8 =''F06'' and fpt.TYPE_6 not in(''P11'')								
	where    m.CDATE =date''${valDate}''-1  AND 							
	m.PORTFOLIO_ID in (   select t1.PORTFOLIO_ID from RSK_PORTFOLIO_PACKAGE_DTL t1  inner join PTL_PORTFOLIO t2 on t1.PORTFOLIO_ID=t2.PORTFOLIO_ID and t2.MDATE>date''${valDate}'' where t1.PTL_BAG_ID=t.PTL_BAG_ID)							
