INSERT INTO "RSK_ISUP_INDICATOR_PARA_DTL"("PARA_CODE", "PARA_GRANULARITY", "PARA_DISPLAY_TYPE", "CONTENT", "REDIS_FIELD", "IS_FRESH_CAN_TRD", "CREATE_USER", "CREATE_DEPT", "CREATE_TIME", "UPDATE_USER", "UPDATE_TIME") VALUES ('FHMB', '05', 'SQL', 'content5', 'portfolioCode', 'N', 'admin', '001', sysdate, 'admin', sysdate);
INSERT INTO "RSK_ISUP_INDICATOR_PARA_DTL"("PARA_CODE", "PARA_GRANULARITY", "PARA_DISPLAY_TYPE", "CONTENT", "REDIS_FIELD", "IS_FRESH_CAN_TRD", "CREATE_USER", "CREATE_DEPT", "CREATE_TIME", "UPDATE_USER", "UPDATE_TIME") VALUES ('ZHGSYQX', '04', 'SQL', 'SELECT (nvl(sum(TRADE_AMT*LAST_PERIOD),0)) AS lastPeriod FROM (			
  select 			
	DISTINCT TRADE_AMT,		
	 nvl((A1.mdate)-(date''${valDate}''),0)  LAST_PERIOD		
	from		
	(		
		SELECT t1.FINPROD_ID ,	
		( nvl(t1.TDY_FLOAT_INGPL, 0) + nvl(t1.DSC_COST_AMT, 0)+ nvl(t1.TDY_INTINCEXP, 0)+ nvl(t1.DELAY_PAY_AMT, 0)) as TRADE_AMT,t2.MDATE	
		from PTL_SEC_VALUTION t1	
		INNER JOIN FIN_TRADE_PRODUCT t2 on t2.FINPROD_ID=t1.FINPROD_ID and t2.FINPROD_TYPE =''F02''	
		where t1.PORTFOLIO_ID in ${portfolioCode} and  t1.CDATE = date''${valDate}''-1 	
			
		UNION ALL	
			
		select n.FINPROD_ID ,	
		 nvl(sum(decode(n.PS,''T06'',n.TRADE_AMT)),0)	
		  -nvl(sum(decode(n.PS,''T08'',n.TRADE_AMT)),0)	 as  TRADE_AMT,t2.MDATE
		  from TRD_PRODUCT_DEAL n 
		  INNER JOIN TRD_PRODUCT_DEAL_ADD n1 ON n1.trade_id =n.TRADE_ID 
		  INNER JOIN FIN_TRADE_PRODUCT t2 on t2.FINPROD_ID=n.FINPROD_ID and t2.FINPROD_TYPE =''F02''	
		  where n1.PORTFOLIO_ID in ${portfolioCode} and  n.TRADE_DATE = date''${valDate}''	
		  and n.PS in (''T06'',''T08'') group by n.FINPROD_ID,t2.MDATE	
	) A1 		
)', 'portfolioCode', 'N', 'admin', '2222222', sysdate, 'admin', sysdate);
INSERT INTO "RSK_ISUP_INDICATOR_PARA_DTL"("PARA_CODE", "PARA_GRANULARITY", "PARA_DISPLAY_TYPE", "CONTENT", "REDIS_FIELD", "IS_FRESH_CAN_TRD", "CREATE_USER", "CREATE_DEPT", "CREATE_TIME", "UPDATE_USER", "UPDATE_TIME") VALUES ('ZHGSYQX', '02', 'SQL', 'select 1 from dual', 'portfolioCode', 'N', 'admin', '2222222', sysdate, 'admin', sysdate);
INSERT INTO "RSK_ISUP_INDICATOR_PARA_DTL"("PARA_CODE", "PARA_GRANULARITY", "PARA_DISPLAY_TYPE", "CONTENT", "REDIS_FIELD", "IS_FRESH_CAN_TRD", "CREATE_USER", "CREATE_DEPT", "CREATE_TIME", "UPDATE_USER", "UPDATE_TIME") VALUES ('ZHGSYQX', '01', 'SQL', 'select 1 from dual', 'portfolioCode', 'N', 'admin', '2222222', sysdate, 'admin', sysdate);
INSERT INTO "RSK_ISUP_INDICATOR_PARA_DTL"("PARA_CODE", "PARA_GRANULARITY", "PARA_DISPLAY_TYPE", "CONTENT", "REDIS_FIELD", "IS_FRESH_CAN_TRD", "CREATE_USER", "CREATE_DEPT", "CREATE_TIME", "UPDATE_USER", "UPDATE_TIME") VALUES ('FBZHZQLZCDYE', '04', 'SQL', 'select sum(TRADE_AMT) as tradeAmt from
(
	select nvl(sum(nvl(m.TDY_FLOAT_INGPL, 0) + nvl(m.DSC_COST_AMT, 0)),0) as  TRADE_AMT from PTL_SEC_VALUTION m			
  inner join FIN_PRODUCT_TYPE fpt on m.FINPROD_ID=fpt.FINPROD_ID  and fpt.TYPE_8 =''F06'' and fpt.TYPE_6 not in(''P11'')			
  where m.PORTFOLIO_ID in ${portfolioCode}  and  m.CDATE =date''${valDate}''-1	
union ALL
  select
  nvl(sum(decode(n.PS,''T01'',decode(TRADE_STATUS,''03'',n.TRADE_AMT*-1,n.TRADE_AMT))),0)
  -nvl(sum(decode(n.PS,''T02'',decode(TRADE_STATUS,''03'',n.TRADE_AMT*-1,n.TRADE_AMT))),0)
  -nvl(sum(decode(n.PS,''T07'',decode(TRADE_STATUS,''03'',n.TRADE_AMT*-1,n.TRADE_AMT))),0)
  -nvl(sum(decode(n.PS,''T08'',decode(TRADE_STATUS,''03'',n.TRADE_AMT*-1,n.TRADE_AMT))),0) as  TRADE_AMT  from TRD_PRODUCT_DEAL_ADD m
  inner join TRD_PRODUCT_DEAL n on m.TRADE_ID=n.TRADE_ID
 inner join FIN_PRODUCT_TYPE fpt on n.FINPROD_ID=fpt.FINPROD_ID  and fpt.TYPE_8 =''F06'' and fpt.TYPE_6 not in(''P11'')
  where m.PORTFOLIO_ID in ${portfolioCode} and n.TRADE_DATE=date''${valDate}'' and n.PS in (''T01'',''T02'',''T07'',''T08'')

union ALL
  select
  nvl(sum(decode(n.PS,''T01'',decode(TRADE_STATUS,''03'',n.TRADE_AMT*-1,n.TRADE_AMT))),0)
  -nvl(sum(decode(n.PS,''T02'',decode(TRADE_STATUS,''03'',n.TRADE_AMT*-1,n.TRADE_AMT))),0)
  -nvl(sum(decode(n.PS,''T07'',decode(TRADE_STATUS,''03'',n.TRADE_AMT*-1,n.TRADE_AMT))),0)
  -nvl(sum(decode(n.PS,''T08'',decode(TRADE_STATUS,''03'',n.TRADE_AMT*-1,n.TRADE_AMT))),0) as  TRADE_AMT  from WFL_TRD_PRODUCT_DEAL_ADD m
  inner join WFL_TRD_PRODUCT_DEAL n on m.TRADE_ID=n.TRADE_ID and n.TRADE_STATUS != ''03''
  inner join FIN_PRODUCT_TYPE fpt on n.FINPROD_ID=fpt.FINPROD_ID  and fpt.TYPE_8 =''F06'' and fpt.TYPE_6 not in(''P11'')   
  where m.PORTFOLIO_ID in ${portfolioCode} and n.TRADE_DATE=date''${valDate}'' and n.PS in (''T01'',''T02'',''T07'',''T08'') and m.WORKFLOW_ID != ${tradeCode}
)', 'portfolioCode', 'N', 'jjpei', '2222222', sysdate, 'jjpei', sysdate);
INSERT INTO "RSK_ISUP_INDICATOR_PARA_DTL"("PARA_CODE", "PARA_GRANULARITY", "PARA_DISPLAY_TYPE", "CONTENT", "REDIS_FIELD", "IS_FRESH_CAN_TRD", "CREATE_USER", "CREATE_DEPT", "CREATE_TIME", "UPDATE_USER", "UPDATE_TIME") VALUES ('FBZHZQLZCDYE', '05', 'SQL', 'select nvl(sum(nvl(m.TDY_FLOAT_INGPL, 0) + nvl(m.DSC_COST_AMT, 0)),0) as  TRADE_AMT from PTL_SEC_VALUTION m	
 inner join FIN_PRODUCT_TYPE fpt on m.FINPROD_ID=fpt.FINPROD_ID  and fpt.TYPE_8 =''F06'' and fpt.TYPE_6 not in(''P11'') 	
  where  m.PORTFOLIO_ID in ${portfolioCode}  and m.CDATE=date''${valDate}''', 'portfolioCode', 'N', 'jjpei', '2222222', sysdate, 'jjpei', sysdate);
INSERT INTO "RSK_ISUP_INDICATOR_PARA_DTL"("PARA_CODE", "PARA_GRANULARITY", "PARA_DISPLAY_TYPE", "CONTENT", "REDIS_FIELD", "IS_FRESH_CAN_TRD", "CREATE_USER", "CREATE_DEPT", "CREATE_TIME", "UPDATE_USER", "UPDATE_TIME") VALUES ('DQRZSGJYRYNDZCJZ', '02', 'SQL', 'SELECT RKEY,(sum(RVALUE)) AS RVALUE FROM (				

  select t1.PORTFOLIO_ID as RKEY,nvl(sum(nvl(t1.TDY_FLOAT_INGPL, 0) + nvl(t1.DSC_COST_AMT, 0)+ nvl(t1.TDY_INTINCEXP, 0)+ nvl(t1.DELAY_PAY_AMT, 0)),0) as  RVALUE from PTL_SEC_VALUTION t1				

  inner join ( 				

   SELECT FINPROD_ID,MDATE,CALENDAR_ID,CDATE,FINPROD_TYPE FROM (	 			

  SELECT s1.FINPROD_ID,s1.MDATE,s1.CALENDAR_ID,s1.CDATE,s1.FINPROD_TYPE,ROW_NUMBER() OVER(PARTITION BY s1.FINPROD_ID ORDER BY s1.CDATE asc) AS rn FROM (				

			    SELECT s.FINPROD_ID,s.MDATE,s.CALENDAR_ID,s.CDATE,s.FINPROD_TYPE,s.rownum1 FROM (	

			    SELECT m.FINPROD_ID,m.MDATE,m.FINPROD_TYPE,m.CALENDAR_ID,n.CDATE,RANK() OVER(PARTITION BY m.FINPROD_ID ORDER BY n.CDATE desc) AS  rownum1 FROM (	

			  SELECT FINPROD_ID,FINPROD_TYPE,MDATE,CASE WHEN CALENDAR_ID IS NULL THEN ''01'' ELSE CALENDAR_ID end CALENDAR_ID FROM FIN_PRODUCT WHERE MDATE IS NOT null) m 	

			  INNER JOIN MST_HOLIDAY n ON  m.CALENDAR_ID=n.CALENDAR_ID  AND n.CDATE<=m.MDATE AND n.IS_HOLIDAY=0 ) s WHERE s.rownum1<=10 	

		  ) s1  		

	  )  WHERE rn=1			

  ) t2				

  on t1.FINPROD_ID = t2.FINPROD_ID and t2.MDATE>=date''${valDate}''-1  and t2.CDATE<=date''${valDate}''-1 				

  where  t1.CDATE=date''${valDate}'' -1   group by t1.PORTFOLIO_ID				

  				

  UNION ALL				

    select t1.PORTFOLIO_ID as RKEY,nvl(sum(nvl(t1.TDY_FLOAT_INGPL, 0) + nvl(t1.DSC_COST_AMT, 0)+ nvl(t1.TDY_INTINCEXP, 0)+ nvl(t1.DELAY_PAY_AMT, 0)),0) as  RVALUE from PTL_SEC_VALUTION t1				

  inner join ( 				

   SELECT FINPROD_ID,MDATE,CALENDAR_ID,CDATE,FINPROD_TYPE FROM (	 			

  SELECT s1.FINPROD_ID,s1.MDATE,s1.CALENDAR_ID,s1.CDATE,s1.FINPROD_TYPE,ROW_NUMBER() OVER(PARTITION BY s1.FINPROD_ID ORDER BY s1.CDATE asc) AS rn FROM (				

			    SELECT s.FINPROD_ID,s.MDATE,s.CALENDAR_ID,s.CDATE,s.FINPROD_TYPE,s.rownum1 FROM (	

			    SELECT m.FINPROD_ID,m.MDATE,m.FINPROD_TYPE,m.CALENDAR_ID,n.CDATE,RANK() OVER(PARTITION BY m.FINPROD_ID ORDER BY n.CDATE desc) AS  rownum1 FROM (	

			  SELECT FINPROD_ID,FINPROD_TYPE,MDATE,CASE WHEN CALENDAR_ID IS NULL THEN ''01'' ELSE CALENDAR_ID end CALENDAR_ID FROM FIN_TRADE_PRODUCT WHERE FINPROD_TYPE not in (''F02'', ''F08'', ''F25'') and MDATE IS NOT null) m 	

			  INNER JOIN MST_HOLIDAY n ON  m.CALENDAR_ID=n.CALENDAR_ID  AND n.CDATE<=m.MDATE AND n.IS_HOLIDAY=0 ) s WHERE s.rownum1<=10 	

		  ) s1  		

	  )  WHERE rn=1			

  ) t2				

  on t1.FINPROD_ID = t2.FINPROD_ID and t2.MDATE>=date''${valDate}''-1  and t2.CDATE<=date''${valDate}''-1 				

  where  t1.CDATE=date''${valDate}'' -1   group by t1.PORTFOLIO_ID				

  ) GROUP BY RKEY', 'portfolioCode', 'N', 'jjpei', 'jsadjflsajfsdkl', sysdate, 'jjpei', sysdate);
