INSERT INTO "RSK_ISUP_INDICATOR_PARA_DTL"("PARA_CODE", "PARA_GRANULARITY", "PARA_DISPLAY_TYPE", "CONTENT", "REDIS_FIELD", "IS_FRESH_CAN_TRD", "CREATE_USER", "CREATE_DEPT", "CREATE_TIME", "UPDATE_USER", "UPDATE_TIME") VALUES ('CPZDHC', '01', 'SQL', 'select 1 from dual', 'portfolioCode', 'N', 'whmcp', '2222222', sysdate, 'whmcp', sysdate);
INSERT INTO "RSK_ISUP_INDICATOR_PARA_DTL"("PARA_CODE", "PARA_GRANULARITY", "PARA_DISPLAY_TYPE", "CONTENT", "REDIS_FIELD", "IS_FRESH_CAN_TRD", "CREATE_USER", "CREATE_DEPT", "CREATE_TIME", "UPDATE_USER", "UPDATE_TIME") VALUES ('CPZDHC', '04', 'SQL', 'with jzDayData as (
select
max(t1.TDY_UNIT_VALUE_SUM) as jzDayValue
from PTL_PORTFOLIO_VALUATION t1
inner join PTL_PORTFOLIO pp on t1.PORTFOLIO_ID = pp.PORTFOLIO_ID and t1.CDATE = pp.VDATE
where t1.PORTFOLIO_ID in ${portfolioCode}
),
allLjSylData as (
select
t1.CDATE,
(nvl(t1.TDY_UNIT_VALUE_SUM, 0) - nvl(jzDayData.jzDayValue, 0)) / nvl(jzDayData.jzDayValue, 0) as ljSylValue
from PTL_PORTFOLIO_VALUATION t1
inner join jzDayData on 1=1
where t1.PORTFOLIO_ID in ${portfolioCode} and t1.CDATE <= date ''${valDate}''
order by t1.CDATE
)
select
max(
round(allLjSylData1.ljSylValue -
(select min(allLjSylData2.ljSylValue) from allLjSylData allLjSylData2 where allLjSylData2.CDATE <= allLjSylData1.CDATE), 6)
)
as resultValue
from allLjSylData allLjSylData1', 'portfolioCode', 'N', 'whmcp', '2222222', sysdate, 'whmcp', sysdate);
INSERT INTO "RSK_ISUP_INDICATOR_PARA_DTL"("PARA_CODE", "PARA_GRANULARITY", "PARA_DISPLAY_TYPE", "CONTENT", "REDIS_FIELD", "IS_FRESH_CAN_TRD", "CREATE_USER", "CREATE_DEPT", "CREATE_TIME", "UPDATE_USER", "UPDATE_TIME") VALUES ('TZSYQXSNYNDZQZC', '04', 'SQL', 'SELECT nvl(SUM(TRADE_AMT),0) TRADE_AMT FROM (				

	  select 			

		SUM(A1.TRADE_AMT) TRADE_AMT,		

		(		

		 	select B1.LAST_PERIOD from  MST_BOND_VALUATION_INFO B1	

		    inner join		

		    (select to_char(max(VALUE_DATE),''yyyy-MM-dd'') as VALUE_DATE,SEC_ID from MST_BOND_VALUATION_INFO where VALUE_DATE<=date''${valDate}'' group by sec_id) B2		

		    on B1.SEC_ID=B2.SEC_ID and B1.VALUE_DATE=B2.VALUE_DATE WHERE B1.SEC_ID=A1.FINPROD_ID		

		)		

	    LAST_PERIOD			

		from		

		(		

			select	

			t1.FINPROD_ID,( nvl(t1.TDY_FLOAT_INGPL, 0) + nvl(t1.DSC_COST_AMT, 0)+ nvl(t1.TDY_INTINCEXP, 0)+ nvl(t1.DELAY_PAY_AMT, 0)) as TRADE_AMT,t2.FINPROD_TYPE,t2.MDATE	

			from PTL_SEC_VALUTION t1	

			 INNER  join FIN_PRODUCT t2	on t1.FINPROD_ID = t2.FINPROD_ID AND t2.FINPROD_TYPE =''F01''

			where t1.PORTFOLIO_ID in ${portfolioCode} and  t1.CDATE = date''${valDate}''-1 	

				

				

			UNION ALL	

				select

				n.FINPROD_ID ,

				 nvl(sum(decode(n.PS,''T01'',n.TRADE_AMT)),0)

			  -nvl(sum(decode(n.PS,''T02'',n.TRADE_AMT)),0)	as  TRADE_AMT,n.FINPROD_TYPE,t2.MDATE

			  from TRD_PRODUCT_DEAL n

			    INNER JOIN TRD_PRODUCT_DEAL_ADD n1 ON n1.trade_id =n.TRADE_ID 

			  inner join FIN_PRODUCT t2  on n.FINPROD_ID = t2.FINPROD_ID  AND t2.FINPROD_TYPE =''F01''	

			  where n1.PORTFOLIO_ID in ${portfolioCode} and  n.TRADE_DATE = date''${valDate}''	

			  and n.PS in (''T01'',''T02'') group by n.FINPROD_ID,t2.MDATE,n.FINPROD_TYPE	

		) A1 GROUP BY A1.FINPROD_ID,A1.FINPROD_TYPE,A1.MDATE		

	) B1 WHERE B1.LAST_PERIOD<=3', 'portfolioCode', 'N', 'jjpei', 'jsadjflsajfsdkl', sysdate, 'jjpei', sysdate);
INSERT INTO "RSK_ISUP_INDICATOR_PARA_DTL"("PARA_CODE", "PARA_GRANULARITY", "PARA_DISPLAY_TYPE", "CONTENT", "REDIS_FIELD", "IS_FRESH_CAN_TRD", "CREATE_USER", "CREATE_DEPT", "CREATE_TIME", "UPDATE_USER", "UPDATE_TIME") VALUES ('TZSYQXSNYNDZQZC', '05', 'SQL', 'SELECT nvl(SUM(TRADE_AMT),0) TRADE_AMT FROM (				

	  select 			

		SUM(A1.TRADE_AMT) TRADE_AMT,		

		(		

		 	select B1.LAST_PERIOD from  MST_BOND_VALUATION_INFO B1	

		    inner join		

		    (select to_char(max(VALUE_DATE),''yyyy-MM-dd'') as VALUE_DATE,SEC_ID from MST_BOND_VALUATION_INFO where VALUE_DATE<=date''${valDate}'' group by sec_id) B2		

		    on B1.SEC_ID=B2.SEC_ID and B1.VALUE_DATE=B2.VALUE_DATE WHERE B1.SEC_ID=A1.FINPROD_ID		

		)		

	    LAST_PERIOD			

		from		

		(		

			select	

			t1.FINPROD_ID,( nvl(t1.TDY_FLOAT_INGPL, 0) + nvl(t1.DSC_COST_AMT, 0)+ nvl(t1.TDY_INTINCEXP, 0)+ nvl(t1.DELAY_PAY_AMT, 0)) as TRADE_AMT,t2.FINPROD_TYPE,t2.MDATE	

			from PTL_SEC_VALUTION t1	

			 INNER  join FIN_PRODUCT t2 on t1.FINPROD_ID = t2.FINPROD_ID AND t2.FINPROD_TYPE =''F01''	

			where t1.PORTFOLIO_ID in ${portfolioCode} and  t1.CDATE = date''${valDate}''	

				

		) A1 GROUP BY A1.FINPROD_ID,A1.FINPROD_TYPE,A1.MDATE		

	) B1 WHERE B1.LAST_PERIOD<=3', 'portfolioCode', 'N', 'jjpei', 'jsadjflsajfsdkl', sysdate, 'jjpei', sysdate);
INSERT INTO "RSK_ISUP_INDICATOR_PARA_DTL"("PARA_CODE", "PARA_GRANULARITY", "PARA_DISPLAY_TYPE", "CONTENT", "REDIS_FIELD", "IS_FRESH_CAN_TRD", "CREATE_USER", "CREATE_DEPT", "CREATE_TIME", "UPDATE_USER", "UPDATE_TIME") VALUES ('CPZDHC', '05', 'SQL', 'with jzDayData as (
select
max(t1.TDY_UNIT_VALUE_SUM) as jzDayValue
from PTL_PORTFOLIO_VALUATION t1
inner join PTL_PORTFOLIO pp on t1.PORTFOLIO_ID = pp.PORTFOLIO_ID and t1.CDATE = pp.VDATE
where t1.PORTFOLIO_ID in ${portfolioCode}
),
allLjSylData as (
select
t1.CDATE,
(nvl(t1.TDY_UNIT_VALUE_SUM, 0) - nvl(jzDayData.jzDayValue, 0)) / nvl(jzDayData.jzDayValue, 0) as ljSylValue
from PTL_PORTFOLIO_VALUATION t1
inner join jzDayData on 1=1
where t1.PORTFOLIO_ID in ${portfolioCode} and t1.CDATE <= date ''${valDate}''
order by t1.CDATE
)
select
max(
round(allLjSylData1.ljSylValue -
(select min(allLjSylData2.ljSylValue) from allLjSylData allLjSylData2 where allLjSylData2.CDATE <= allLjSylData1.CDATE), 6)
)
as resultValue
from allLjSylData allLjSylData1', 'portfolioCode', 'N', 'whmcp', '2222222', sysdate, 'whmcp', sysdate);
INSERT INTO "RSK_ISUP_INDICATOR_PARA_DTL"("PARA_CODE", "PARA_GRANULARITY", "PARA_DISPLAY_TYPE", "CONTENT", "REDIS_FIELD", "IS_FRESH_CAN_TRD", "CREATE_USER", "CREATE_DEPT", "CREATE_TIME", "UPDATE_USER", "UPDATE_TIME") VALUES ('DYZCGM', '04', 'SQL', 'select 	
sum(nvl(targetData.VALUE, 0)) as RVALUE, targetData.ASSETCODE AS RKEY, targetData.ASSETNAME AS RKEYCN	
from	
(	
select	
 nvl(t1.TDY_FLOAT_INGPL, 0) + nvl(t1.DSC_COST_AMT, 0) as VALUE, t1.FINPROD_ID as ASSETCODE, t2.FINPROD_NAME as ASSETNAME	
from PTL_SEC_VALUTION t1	
 left join FIN_PRODUCT t2  on t1.FINPROD_ID = t2.FINPROD_ID	
 left join FIN_TRADE_PRODUCT t3 on t1.FINPROD_ID = t3.FINPROD_ID	
where t1.PORTFOLIO_ID in ${portfolioCode} and  t1.CDATE = date''${valDate}''-1  AND t1.PORTFOLIO_ID!=t1.FINPROD_ID	
and ((t3.FINPROD_TYPE is null and t2.FINPROD_TYPE2 is not null) or t3.FINPROD_TYPE2 not in (''F02'', ''F03'', ''F04'',''F05'', ''F08'',''F09'', ''F25''))	
	
union all	
 select	
   nvl(sum(decode(n.PS,''T01'',n.TRADE_AMT)),0)	
  +nvl(sum(decode(n.PS,''T04'',n.TRADE_AMT)),0)	
  +nvl(sum(decode(n.PS,''T36'',n.TRADE_AMT)),0)	
  -nvl(sum(decode(n.PS,''T03'',n.TRADE_AMT)),0)	
  -nvl(sum(decode(n.PS,''T12'',n.TRADE_AMT)),0)	
  -nvl(sum(decode(n.PS,''T02'',n.TRADE_AMT)),0)	
  -nvl(sum(decode(n.PS,''T13'',n.TRADE_AMT)),0)	
  -nvl(sum(decode(n.PS,''T14'',n.TRADE_AMT)),0)	
  -nvl(sum(decode(n.PS,''T20'',n.TRADE_AMT)),0)	
  -nvl(sum(decode(n.PS,''T05'',n.TRADE_AMT)),0) as  TRADE_AMT,n.FINPROD_ID as ASSETCODE, t2.FINPROD_NAME as ASSETNAME	
  from TRD_PRODUCT_DEAL n  	
    left join FIN_PRODUCT t2  on n.FINPROD_ID = t2.FINPROD_ID	
 left join FIN_TRADE_PRODUCT t3 on n.FINPROD_ID = t3.FINPROD_ID
   LEFT JOIN TRD_PRODUCT_DEAL_ADD n1 ON n.TRADE_ID =n1.TRADE_ID 
  where n1.PORTFOLIO_ID in ${portfolioCode} and  n.TRADE_DATE = date''${valDate}''	
  and ((t3.FINPROD_TYPE2 is null and t2.FINPROD_TYPE is not null) or t3.FINPROD_TYPE2 not in (''F02'', ''F03'', ''F04'',''F05'', ''F08'',''F09'',''F25''))	
  and n.PS in (''T01'',''T02'',''T03'',''T12'',''T04'',''T05'',''T13'',''T36'',''T14'',''T20'') group by n.FINPROD_ID, t2.FINPROD_NAME 	
) targetData	
group by targetData.ASSETCODE, targetData.ASSETNAME', 'portfolioCode,assetCode', 'N', 'whmcp', '2222222', sysdate, 'whmcp', sysdate);
INSERT INTO "RSK_ISUP_INDICATOR_PARA_DTL"("PARA_CODE", "PARA_GRANULARITY", "PARA_DISPLAY_TYPE", "CONTENT", "REDIS_FIELD", "IS_FRESH_CAN_TRD", "CREATE_USER", "CREATE_DEPT", "CREATE_TIME", "UPDATE_USER", "UPDATE_TIME") VALUES ('TZSYQXSNYNDZQZC', '03', 'SQL', 'SELECT B1.PORTFOLIO_ID AS RKEY,sum(B1.TRADE_AMT) AS RVALUE FROM (				

	  select 			

	    A1.PORTFOLIO_ID,			

		SUM(A1.TRADE_AMT) TRADE_AMT,		

		CASE WHEN A1.FINPROD_TYPE =''F01'' THEN 		

		(		

		 	select B1.LAST_PERIOD from  MST_BOND_VALUATION_INFO B1	

		    inner join		

		    (select to_char(max(VALUE_DATE),''yyyy-MM-dd'') as VALUE_DATE,SEC_ID from MST_BOND_VALUATION_INFO where VALUE_DATE<=date''${valDate}'' group by sec_id) B2		

		    on B1.SEC_ID=B2.SEC_ID and B1.VALUE_DATE=B2.VALUE_DATE WHERE B1.SEC_ID=A1.FINPROD_ID		

		)		

	    ELSE (((A1.mdate)-(date''${valDate}''))) END LAST_PERIOD			

		from		

		(		

			select	

			t1.PORTFOLIO_ID,t1.FINPROD_ID,( nvl(t1.TDY_FLOAT_INGPL, 0) + nvl(t1.DSC_COST_AMT, 0)+ nvl(t1.TDY_INTINCEXP, 0)+ nvl(t1.DELAY_PAY_AMT, 0)) as TRADE_AMT,t2.FINPROD_TYPE,t2.MDATE	

			from PTL_SEC_VALUTION t1	

			 INNER  join FIN_PRODUCT t2 on t1.FINPROD_ID = t2.FINPROD_ID AND t2.FINPROD_TYPE =''F01''	

			where   t1.CDATE = date''${valDate}''-1  	

				

		) A1 GROUP BY A1.PORTFOLIO_ID,A1.FINPROD_ID,A1.FINPROD_TYPE,A1.MDATE		

	) B1 WHERE B1.LAST_PERIOD<=3	 GROUP BY B1.PORTFOLIO_ID', 'portfolioCode', 'N', 'jjpei', 'jsadjflsajfsdkl', sysdate, 'jjpei', sysdate);
INSERT INTO "RSK_ISUP_INDICATOR_PARA_DTL"("PARA_CODE", "PARA_GRANULARITY", "PARA_DISPLAY_TYPE", "CONTENT", "REDIS_FIELD", "IS_FRESH_CAN_TRD", "CREATE_USER", "CREATE_DEPT", "CREATE_TIME", "UPDATE_USER", "UPDATE_TIME") VALUES ('GZQSZHZZQTZJJSZ', '01', 'SQL', 'SELECT S1.RVALUE,S1.RKEY FROM (					
	SELECT RVALUE*RVALUE2/100 AS RVALUE,RKEY FROM (				
		SELECT nvl(sum(t2.ISSUE_AMT),0) AS RVALUE,			
		(SELECT nvl(sum(s.PRICE),100) FROM MST_BOND_VALUATION_INFO s WHERE s.SEC_ID=t2.FINPROD_ID AND s.VALUE_DATE=(			
					SELECT max(VALUE_DATE) FROM MST_BOND_VALUATION_INFO m WHERE m.SEC_ID=t2.FINPROD_ID and m.VALUE_DATE<=date''${valDate}'')
			) AS RVALUE2,		
		T2.FINPROD_ID RKEY FROM  FIN_PRODUCT t2  			
		WHERE T2.FINPROD_TYPE =''F01''  GROUP BY T2.FINPROD_ID 			
	)				
					
UNION ALL					
	SELECT RVALUE,RKEY FROM (				
		SELECT			
		(SELECT nvl(sum(s.CLOSE_PRICE),0) FROM MST_FUND_MARKET_INFO s WHERE s.FUND_CODE=t2.FINPROD_MARKET_ID AND s.VALUE_DATE=(SELECT max(VALUE_DATE) 			
		FROM MST_FUND_MARKET_INFO m WHERE m.FUND_CODE=t2.FINPROD_MARKET_ID and m.VALUE_DATE<=date''${valDate}'')			
		) AS RVALUE,			
		T2.FINPROD_ID RKEY FROM FIN_PRODUCT t2  			
		WHERE  T2.FINPROD_TYPE =''F06'' GROUP BY T2.FINPROD_ID,T2.FINPROD_MARKET_ID			
	)				
) S1', 'assetCode', 'N', 'jjpei', '2222222', sysdate, 'jjpei', sysdate);
INSERT INTO "RSK_ISUP_INDICATOR_PARA_DTL"("PARA_CODE", "PARA_GRANULARITY", "PARA_DISPLAY_TYPE", "CONTENT", "REDIS_FIELD", "IS_FRESH_CAN_TRD", "CREATE_USER", "CREATE_DEPT", "CREATE_TIME", "UPDATE_USER", "UPDATE_TIME") VALUES ('GZQSZHZZQTZJJSZ', '05', 'SQL', 'SELECT DISTINCT RVALUE,RKEY,RKEYCN FROM (					
	SELECT RVALUE*RVALUE2/100 AS RVALUE,RKEY,RKEYCN FROM (				
	SELECT DISTINCT nvl(t2.ISSUE_AMT,0) AS RVALUE,				
	(SELECT nvl(sum(s.PRICE),100) FROM MST_BOND_VALUATION_INFO s WHERE s.SEC_ID=t2.FINPROD_ID AND s.VALUE_DATE=(				
			SELECT max(VALUE_DATE) FROM MST_BOND_VALUATION_INFO m WHERE m.SEC_ID=t2.FINPROD_ID and m.VALUE_DATE<=date''${valDate}'')		
	) AS RVALUE2,				
	T2.FINPROD_ID RKEY,t2.FINPROD_NAME RKEYCN FROM PTL_SEC_VALUTION T1 				
	INNER JOIN FIN_PRODUCT t2 ON t1.FINPROD_ID=t2.FINPROD_ID AND T2.FINPROD_TYPE2 =''F01''				
	WHERE t1.PORTFOLIO_ID IN ${portfolioCode} AND t1.CDATE=date''${valDate}''				
 	)				
UNION ALL					
 					
	SELECT RVALUE,RKEY,RKEYCN FROM (				
	SELECT (SELECT nvl(sum(s.CLOSE_PRICE),0) FROM MST_FUND_MARKET_INFO s WHERE s.FUND_CODE=t2.FINPROD_MARKET_ID AND s.VALUE_DATE=(				
		SELECT max(VALUE_DATE) FROM MST_FUND_MARKET_INFO m WHERE m.FUND_CODE=t2.FINPROD_MARKET_ID and m.VALUE_DATE<=date''${valDate}'')			
	) AS RVALUE,				
    T2.FINPROD_ID RKEY,					
	t2.FINPROD_NAME RKEYCN FROM PTL_SEC_VALUTION T1 				
	INNER JOIN FIN_PRODUCT t2 ON t1.FINPROD_ID=t2.FINPROD_ID AND T2.FINPROD_TYPE2 =''F06''				
	WHERE t1.PORTFOLIO_ID IN ${portfolioCode} AND t1.CDATE=date''${valDate}''				
	)				
) S1', 'assetCode', 'N', 'jjpei', '2222222', sysdate, 'jjpei', sysdate);
INSERT INTO "RSK_ISUP_INDICATOR_PARA_DTL"("PARA_CODE", "PARA_GRANULARITY", "PARA_DISPLAY_TYPE", "CONTENT", "REDIS_FIELD", "IS_FRESH_CAN_TRD", "CREATE_USER", "CREATE_DEPT", "CREATE_TIME", "UPDATE_USER", "UPDATE_TIME") VALUES ('TZSYQXSNYNDZQZC', '01', 'SQL', 'SELECT B1.PORTFOLIO_ID AS RKEY,sum(B1.TRADE_AMT) AS RVALUE FROM (				

	  select 			

	    A1.PORTFOLIO_ID,			

		SUM(A1.TRADE_AMT) TRADE_AMT,		

		CASE WHEN A1.FINPROD_TYPE =''F01'' THEN 		

		(		

		 	select B1.LAST_PERIOD from  MST_BOND_VALUATION_INFO B1	

		    inner join		

		    (select to_char(max(VALUE_DATE),''yyyy-MM-dd'') as VALUE_DATE,SEC_ID from MST_BOND_VALUATION_INFO where VALUE_DATE<=date''${valDate}'' group by sec_id) B2		

		    on B1.SEC_ID=B2.SEC_ID and B1.VALUE_DATE=B2.VALUE_DATE WHERE B1.SEC_ID=A1.FINPROD_ID		

		)		

	    ELSE (((A1.mdate)-(date''${valDate}''))) END LAST_PERIOD			

		from		

		(		

			select	

			t1.PORTFOLIO_ID,t1.FINPROD_ID,( nvl(t1.TDY_FLOAT_INGPL, 0) + nvl(t1.DSC_COST_AMT, 0)+ nvl(t1.TDY_INTINCEXP, 0)+ nvl(t1.DELAY_PAY_AMT, 0)) as TRADE_AMT,t2.FINPROD_TYPE,t2.MDATE	

			from PTL_SEC_VALUTION t1	

			 INNER  join FIN_PRODUCT t2 on t1.FINPROD_ID = t2.FINPROD_ID AND t2.FINPROD_TYPE =''F01''	

			where   t1.CDATE = date''${valDate}''-1  	

				

		) A1 GROUP BY A1.PORTFOLIO_ID,A1.FINPROD_ID,A1.FINPROD_TYPE,A1.MDATE		

	) B1 WHERE B1.LAST_PERIOD<=3	 GROUP BY B1.PORTFOLIO_ID', 'portfolioCode', 'N', 'jjpei', 'jsadjflsajfsdkl', sysdate, 'jjpei', sysdate);
INSERT INTO "RSK_ISUP_INDICATOR_PARA_DTL"("PARA_CODE", "PARA_GRANULARITY", "PARA_DISPLAY_TYPE", "CONTENT", "REDIS_FIELD", "IS_FRESH_CAN_TRD", "CREATE_USER", "CREATE_DEPT", "CREATE_TIME", "UPDATE_USER", "UPDATE_TIME") VALUES ('SSGSKLTGB', '03', 'SQL', 'SELECT (SELECT nvl(sum(s.C_SHARES),0) FROM MST_SHARE_PRICE s WHERE s.SHARES_ID=t2.FINPROD_MARKET_ID AND s.DEAL_DATE=(		
		SELECT max(DEAL_DATE) FROM MST_SHARE_PRICE m WHERE m.SHARES_ID=t2.FINPROD_MARKET_ID and m.DEAL_DATE<=date''${valDate}'')
	) AS RVALUE,	
    T2.FINPROD_ID RKEY		
	from FIN_PRODUCT t2 where T2.FINPROD_TYPE2 =''F10'' GROUP BY T2.FINPROD_ID,T2.FINPROD_MARKET_ID', 'assetCode', 'N', 'admin', '2222222', sysdate, 'admin', sysdate);
INSERT INTO "RSK_ISUP_INDICATOR_PARA_DTL"("PARA_CODE", "PARA_GRANULARITY", "PARA_DISPLAY_TYPE", "CONTENT", "REDIS_FIELD", "IS_FRESH_CAN_TRD", "CREATE_USER", "CREATE_DEPT", "CREATE_TIME", "UPDATE_USER", "UPDATE_TIME") VALUES ('CPZZC', '02', 'SQL', 'select PORTFOLIO_ID as RKEY,nvl(sum(TDY_ASSET_VALUE),0) as RVALUE from PTL_PORTFOLIO_VALUATION	
where   CDATE=date''${valDate}''-1 group by PORTFOLIO_ID	
	
union all	
   select m.PTL_BAG_ID as RKEY,	
   ( select NVL(SUM(TDY_ASSET_VALUE),0) AS RVALUE	
  from PTL_PORTFOLIO_VALUATION where CDATE = date''${valDate}''-1 AND PORTFOLIO_ID in (select t1.PORTFOLIO_ID from RSK_PORTFOLIO_PACKAGE_DTL t1 	
  inner join PTL_PORTFOLIO t2 on t1.PORTFOLIO_ID=t2.PORTFOLIO_ID and t2.MDATE>date''${valDate}'' where t1.PTL_BAG_ID=m.PTL_BAG_ID)	
   )	
   from RSK_PORTFOLIO_PACKAGE m', 'portfolioCode', 'N', 'whmcp', '2222222', sysdate, 'whmcp', sysdate);
INSERT INTO "RSK_ISUP_INDICATOR_PARA_DTL"("PARA_CODE", "PARA_GRANULARITY", "PARA_DISPLAY_TYPE", "CONTENT", "REDIS_FIELD", "IS_FRESH_CAN_TRD", "CREATE_USER", "CREATE_DEPT", "CREATE_TIME", "UPDATE_USER", "UPDATE_TIME") VALUES ('DYZCGM', '05', 'SQL', 'select 	
sum(nvl(targetData.VALUE, 0)) as RVALUE, targetData.ASSETCODE RKEY, targetData.ASSETNAME RKEYCN	
from	
(	
select	
 nvl(t1.TDY_FLOAT_INGPL, 0) + nvl(t1.DSC_COST_AMT, 0) as VALUE, t1.FINPROD_ID as ASSETCODE, t2.FINPROD_NAME as ASSETNAME	
from PTL_SEC_VALUTION t1	
 left join FIN_PRODUCT t2	
  on t1.FINPROD_ID = t2.FINPROD_ID	
	left join FIN_TRADE_PRODUCT t3
  on t1.FINPROD_ID = t3.FINPROD_ID	
where t1.PORTFOLIO_ID in ${portfolioCode} and  t1.CDATE = date''${valDate}''	
and ((t3.FINPROD_TYPE2 is null and t2.FINPROD_TYPE2 is not null) or t3.FINPROD_TYPE2 not in (''F02'', ''F04'', ''F08'',''F25''))	
) targetData	
group by targetData.ASSETCODE, targetData.ASSETNAME', 'portfolioCode,assetCode', 'N', 'whmcp', '2222222', sysdate, 'whmcp', sysdate);
INSERT INTO "RSK_ISUP_INDICATOR_PARA_DTL"("PARA_CODE", "PARA_GRANULARITY", "PARA_DISPLAY_TYPE", "CONTENT", "REDIS_FIELD", "IS_FRESH_CAN_TRD", "CREATE_USER", "CREATE_DEPT", "CREATE_TIME", "UPDATE_USER", "UPDATE_TIME") VALUES ('FGKFXZQZC', '02', 'SQL', 'select	

