s2 where s1.PORTFOLIO_ID=s2.PORTFOLIO_ID  group by s2.PTL_BAG_ID,s1.FINPROD_ID	

 ) s1 group by s1.RKEY', 'portfolioCode,assetCode', 'N', 'whmcp', '2222222', sysdate, 'whmcp', sysdate);
INSERT INTO "RSK_ISUP_INDICATOR_PARA_DTL"("PARA_CODE", "PARA_GRANULARITY", "PARA_DISPLAY_TYPE", "CONTENT", "REDIS_FIELD", "IS_FRESH_CAN_TRD", "CREATE_USER", "CREATE_DEPT", "CREATE_TIME", "UPDATE_USER", "UPDATE_TIME") VALUES ('FGKFXZQZC', '04', 'SQL', 'select nvl(sum(nvl(t1.TDY_FLOAT_INGPL, 0) + nvl(t1.DSC_COST_AMT, 0)),0) as RVALUE from PTL_SEC_VALUTION t1	 

	left join FIN_PRODUCT t2 on t1.FINPROD_ID=t2.FINPROD_ID 	

	where t1.PORTFOLIO_ID in ${portfolioCode} and  t1.CDATE=date''${valDate}''   	

	AND t2.FINPROD_TYPE2  =''F01'' AND t2.ISSUE_TYPE =''02''	

	UNION ALL 	

	SELECT	nvl(sum(

	 nvl(sum(decode(n.PS,''T01'',n.TRADE_AMT)),0)	

	  -nvl(sum(decode(n.PS,''T02'',n.TRADE_AMT)),0)	

	  -nvl(sum(decode(n.PS,''T03'',n.TRADE_AMT)),0)	

	),0) as  TRADE_AMT	

	  from  TRD_PRODUCT_DEAL n 	

	 inner join FIN_PRODUCT FP	on n.FINPROD_ID = FP.FINPROD_ID  

	 INNER JOIN TRD_PRODUCT_DEAL_ADD n1 ON n1.TRADE_ID =n.TRADE_ID 	

	  where n1.PORTFOLIO_ID in ${portfolioCode} and n.TRADE_DATE=date''${valDate}'' and n.PS in (''T01'',''T02'',''T03'')	AND FP.ISSUE_TYPE =''02''

	  GROUP BY n1.PORTFOLIO_ID', 'portfolioCode', 'Y', 'admin', '2222222', sysdate, 'admin', sysdate);
