 sum(nvl(t1.TDY_FLOAT_INGPL, 0) + nvl(t1.DSC_COST_AMT, 0)) as RVALUE	

from PTL_SEC_VALUTION t1	

 left join FIN_PRODUCT t2 on t1.FINPROD_ID=t2.FINPROD_ID 	

where  t1.CDATE = date''${valDate}''  AND t1.PORTFOLIO_ID!=t1.FINPROD_ID	

AND t2.FINPROD_TYPE2  =''F01'' AND t2.ISSUE_TYPE =''02''	

group by t1.PORTFOLIO_ID', 'portfolioCode', 'Y', 'admin', '2222222', sysdate, 'admin', sysdate);
