INSERT INTO "RSK_ISUP_INDICATOR_PARA_DTL"("PARA_CODE", "PARA_GRANULARITY", "PARA_DISPLAY_TYPE", "CONTENT", "REDIS_FIELD", "IS_FRESH_CAN_TRD", "CREATE_USER", "CREATE_DEPT", "CREATE_TIME", "UPDATE_USER", "UPDATE_TIME") VALUES ('AZZCJZJQDZHJQ', '01', 'SQL', 'select 1 from dual', 'portfolioCode', 'N', 'admin', '2222222', sysdate, 'admin', sysdate);
INSERT INTO "RSK_ISUP_INDICATOR_PARA_DTL"("PARA_CODE", "PARA_GRANULARITY", "PARA_DISPLAY_TYPE", "CONTENT", "REDIS_FIELD", "IS_FRESH_CAN_TRD", "CREATE_USER", "CREATE_DEPT", "CREATE_TIME", "UPDATE_USER", "UPDATE_TIME") VALUES ('AZZCJZJQDZHJQ', '04', 'SQL', 'SELECT sum((TRADE_AMT)*(M_DURATION)) AS RVALUE FROM (			
  select 			
	SUM(A1.TRADE_AMT) TRADE_AMT,		
	CASE WHEN A1.FINPROD_TYPE =''F01'' THEN 		
	(		
	 	select  CASE WHEN nvl(sum(B1.M_DURATION),0)=0 THEN (((A1.mdate)-(date''${valDate}''))/365) ELSE (nvl(sum(B1.M_DURATION),0)) END M_DURATION from  MST_BOND_VALUATION_INFO B1	
	    inner join		
	    (select to_char(max(VALUE_DATE),''yyyy-MM-dd'') as VALUE_DATE,SEC_ID from MST_BOND_VALUATION_INFO where VALUE_DATE<=date''${valDate}'' group by sec_id) B2		
	    on B1.SEC_ID=B2.SEC_ID and B1.VALUE_DATE=B2.VALUE_DATE WHERE B1.SEC_ID=A1.FINPROD_ID		
	)		
	WHEN (A1.FINPROD_TYPE =''F06'' OR A1.FINPROD_TYPE =''XJ'') THEN (1)/365			
	WHEN a1.FINPROD_ID =a1.PORTFOLIO_ID		
	THEN (1)/365		
    ELSE ((nvl((A1.mdate)-(date''${valDate}''),0))/365) END M_DURATION			
	from		
	(	
 	select NULL AS FINPROD_ID,NULL AS PORTFOLIO_ID,nvl(sum(AMOUNT),0) as  TRADE_AMT,''XJ'' AS FINPROD_TYPE,NULL AS MDATE   from PTL_CASH_POSITION		
 	 where  PORTFOLIO_ID in ${portfolioCode} and HODING_TYPE=''03'' and CDATE =date''${valDate}''			
    UNION ALL
		select	
		t1.FINPROD_ID,t1.PORTFOLIO_ID,( nvl(t1.TDY_FLOAT_INGPL, 0) + nvl(t1.DSC_COST_AMT, 0)+ nvl(t1.TDY_INTINCEXP, 0)+ nvl(t1.DELAY_PAY_AMT, 0)) as TRADE_AMT,t2.FINPROD_TYPE,t2.MDATE	
		from PTL_SEC_VALUTION t1	
		inner join FIN_PRODUCT t2	on t1.FINPROD_ID = t2.FINPROD_ID
		where t1.PORTFOLIO_ID in ${portfolioCode} and  t1.CDATE = date''${valDate}''-1 	
	   UNION ALL		
	   select		
		t1.FINPROD_ID,t1.PORTFOLIO_ID,( nvl(t1.TDY_FLOAT_INGPL, 0) + nvl(t1.DSC_COST_AMT, 0)+ nvl(t1.TDY_INTINCEXP, 0)+ nvl(t1.DELAY_PAY_AMT, 0)) as TRADE_AMT,t3.FINPROD_TYPE,t3.MDATE	
		from PTL_SEC_VALUTION t1	
		inner join FIN_TRADE_PRODUCT t3	 on t1.FINPROD_ID = t3.FINPROD_ID 
		where t1.PORTFOLIO_ID in ${portfolioCode} and  t1.CDATE = date''${valDate}''-1 	
		and  t3.FINPROD_TYPE not in (''F02'', ''F08'', ''F25'')	
			
	UNION ALL		
		select	
		n.FINPROD_ID ,t4.PORTFOLIO_ID,	
		 nvl(sum(decode(n.PS,''T01'',n.TRADE_AMT)),0)	
	  	  +nvl(sum(decode(n.PS,''T07'',n.TRADE_AMT)),0)	
   		  +nvl(sum(decode(n.PS,''T17'',n.TRADE_AMT)),0)	
		  +nvl(sum(decode(n.PS,''T04'',n.TRADE_AMT)),0)	
		  +nvl(sum(decode(n.PS,''T36'',n.TRADE_AMT)),0)	
		  -nvl(sum(decode(n.PS,''T03'',n.TRADE_AMT)),0)	
		  -nvl(sum(decode(n.PS,''T12'',n.TRADE_AMT)),0)	
		  -nvl(sum(decode(n.PS,''T02'',n.TRADE_AMT)),0)	
	   	  -nvl(sum(decode(n.PS,''T09'',n.TRADE_AMT)),0)	
    	  -nvl(sum(decode(n.PS,''T19'',n.TRADE_AMT)),0)		
      	  -nvl(sum(decode(n.PS,''T14'',n.TRADE_AMT)),0)		
      	  -nvl(sum(decode(n.PS,''T20'',n.TRADE_AMT)),0)		
		  -nvl(sum(decode(n.PS,''T13'',n.TRADE_AMT)),0)	
		  -nvl(sum(decode(n.PS,''T05'',n.TRADE_AMT)),0) as  TRADE_AMT,n.FINPROD_TYPE,t2.MDATE	
		  from TRD_PRODUCT_DEAL n  	
		  left join FIN_PRODUCT t2  on n.FINPROD_ID = t2.FINPROD_ID	
		  left join FIN_TRADE_PRODUCT t3 on n.FINPROD_ID = t3.FINPROD_ID
		  LEFT JOIN TRD_PRODUCT_DEAL_ADD t4 ON n.TRADE_ID=t4.TRADE_ID
		  where t4.PORTFOLIO_ID in ${portfolioCode} and  n.TRADE_DATE = date''${valDate}''	
		  and ((t3.FINPROD_TYPE is null and t2.FINPROD_TYPE is not null) or t3.FINPROD_TYPE not in (''F02'', ''F08'', ''F25''))	
		  and n.PS in (''T01'',''T07'',''T17'',''T02'',''T03'',''T12'',''T04'',''T05'',''T13'',''T09'',''T19'',''T36'',''T14'',''T20'') group by t4.PORTFOLIO_ID,n.FINPROD_ID,t2.MDATE,n.FINPROD_TYPE	
	) A1 GROUP BY A1.PORTFOLIO_ID,A1.FINPROD_ID,A1.FINPROD_TYPE,A1.MDATE		
)', 'portfolioCode', 'N', 'admin', '2222222', sysdate, 'admin', sysdate);
