INSERT INTO "RSK_ISUP_INDICATOR_PARA_DTL"("PARA_CODE", "PARA_GRANULARITY", "PARA_DISPLAY_TYPE", "CONTENT", "REDIS_FIELD", "IS_FRESH_CAN_TRD", "CREATE_USER", "CREATE_DEPT", "CREATE_TIME", "UPDATE_USER", "UPDATE_TIME") VALUES ('XJGM', '02', 'SQL', 'select PORTFOLIO_ID as RKEY,nvl(sum(AMOUNT),0) as  RVALUE from PTL_CASH_POSITION		

 	 where   HODING_TYPE=''03'' and CDATE =date''${valDate}'' group by PORTFOLIO_ID', 'portfolioCode', 'N', 'jjpei', 'jsadjflsajfsdkl', sysdate, 'jjpei', sysdate);
INSERT INTO "RSK_ISUP_INDICATOR_PARA_DTL"("PARA_CODE", "PARA_GRANULARITY", "PARA_DISPLAY_TYPE", "CONTENT", "REDIS_FIELD", "IS_FRESH_CAN_TRD", "CREATE_USER", "CREATE_DEPT", "CREATE_TIME", "UPDATE_USER", "UPDATE_TIME") VALUES ('DQRZSGJYRYNDZCJZ', '03', 'SQL', 'SELECT RKEY,(sum(RVALUE)) AS RVALUE FROM (				

  select t1.PORTFOLIO_ID as RKEY,nvl(sum(nvl(t1.TDY_FLOAT_INGPL, 0) + nvl(t1.DSC_COST_AMT, 0)+ nvl(t1.TDY_INTINCEXP, 0)+ nvl(t1.DELAY_PAY_AMT, 0)),0) as  RVALUE from PTL_SEC_VALUTION t1				

  inner join ( 				

   SELECT FINPROD_ID,MDATE,CALENDAR_ID,CDATE,FINPROD_TYPE FROM (	 			

  SELECT s1.FINPROD_ID,s1.MDATE,s1.CALENDAR_ID,s1.CDATE,s1.FINPROD_TYPE,ROW_NUMBER() OVER(PARTITION BY s1.FINPROD_ID ORDER BY s1.CDATE asc) AS rn FROM (				

			    SELECT s.FINPROD_ID,s.MDATE,s.CALENDAR_ID,s.CDATE,s.FINPROD_TYPE,s.rownum1 FROM (	

			    SELECT m.FINPROD_ID,m.MDATE,m.FINPROD_TYPE,m.CALENDAR_ID,n.CDATE,ROW_NUMBER() OVER(PARTITION BY m.FINPROD_ID ORDER BY n.CDATE desc) AS  rownum1 FROM (	

			  SELECT FINPROD_ID,FINPROD_TYPE,MDATE,CASE WHEN CALENDAR_ID IS NULL THEN ''01'' ELSE CALENDAR_ID end CALENDAR_ID FROM FIN_PRODUCT WHERE MDATE IS NOT null) m 	

			  INNER JOIN MST_HOLIDAY n ON  m.CALENDAR_ID=n.CALENDAR_ID  AND n.CDATE<=m.MDATE AND n.IS_HOLIDAY=0 ) s WHERE s.rownum1<=10 	

		  ) s1  		

	  )  WHERE rn=1			

  ) t2				

  on t1.FINPROD_ID = t2.FINPROD_ID and t2.MDATE>=date''${valDate}''-1  and t2.CDATE<=date''${valDate}''-1 				

  where  t1.CDATE=date''${valDate}'' -1   group by t1.PORTFOLIO_ID				

  				

  UNION ALL				

    select t1.PORTFOLIO_ID as RKEY,nvl(sum(nvl(t1.TDY_FLOAT_INGPL, 0) + nvl(t1.DSC_COST_AMT, 0)+ nvl(t1.TDY_INTINCEXP, 0)+ nvl(t1.DELAY_PAY_AMT, 0)),0) as  RVALUE from PTL_SEC_VALUTION t1				

  inner join ( 				

   SELECT FINPROD_ID,MDATE,CALENDAR_ID,CDATE,FINPROD_TYPE FROM (	 			

  SELECT s1.FINPROD_ID,s1.MDATE,s1.CALENDAR_ID,s1.CDATE,s1.FINPROD_TYPE,ROW_NUMBER() OVER(PARTITION BY s1.FINPROD_ID ORDER BY s1.CDATE asc) AS rn FROM (				

			    SELECT s.FINPROD_ID,s.MDATE,s.CALENDAR_ID,s.CDATE,s.FINPROD_TYPE,s.rownum1 FROM (	

			    SELECT m.FINPROD_ID,m.MDATE,m.FINPROD_TYPE,m.CALENDAR_ID,n.CDATE,ROW_NUMBER() OVER(PARTITION BY m.FINPROD_ID ORDER BY n.CDATE desc) AS  rownum1 FROM (	

			  SELECT FINPROD_ID,FINPROD_TYPE,MDATE,CASE WHEN CALENDAR_ID IS NULL THEN ''01'' ELSE CALENDAR_ID end CALENDAR_ID FROM FIN_TRADE_PRODUCT WHERE FINPROD_TYPE not in (''F02'', ''F08'', ''F25'') and MDATE IS NOT null) m 	

			  INNER JOIN MST_HOLIDAY n ON  m.CALENDAR_ID=n.CALENDAR_ID  AND n.CDATE<=m.MDATE AND n.IS_HOLIDAY=0 ) s WHERE s.rownum1<=10 	

		  ) s1  		

	  )  WHERE rn=1			

  ) t2				

  on t1.FINPROD_ID = t2.FINPROD_ID and t2.MDATE>=date''${valDate}''-1  and t2.CDATE<=date''${valDate}''-1 				

  where  t1.CDATE=date''${valDate}'' -1   group by t1.PORTFOLIO_ID				

  ) GROUP BY RKEY', 'portfolioCode', 'N', 'jjpei', 'jsadjflsajfsdkl', sysdate, 'jjpei', sysdate);
INSERT INTO "RSK_ISUP_INDICATOR_PARA_DTL"("PARA_CODE", "PARA_GRANULARITY", "PARA_DISPLAY_TYPE", "CONTENT", "REDIS_FIELD", "IS_FRESH_CAN_TRD", "CREATE_USER", "CREATE_DEPT", "CREATE_TIME", "UPDATE_USER", "UPDATE_TIME") VALUES ('GMCPSTZBZLZC', '02', 'SQL', 'select	
 sum(nvl(t1.TDY_FLOAT_INGPL, 0) + nvl(t1.DSC_COST_AMT, 0)) as RVALUE, t1.PORTFOLIO_ID as RKEY	
from PTL_SEC_VALUTION t1	
 left join FIN_PRODUCT_TYPE t2 on t1.FINPROD_ID=t2.FINPROD_ID 	
where  t1.CDATE = date''${valDate}''-1  AND t1.PORTFOLIO_ID!=t1.FINPROD_ID	
AND t2.TYPE_8  IN (''F01'',''F02'',''F03'',''F04'',''F05'',''F07'',''F09'',''F10'') OR (t2.TYPE_8=''F06'' AND T2.TYPE_6=''P08'')	
group by t1.PORTFOLIO_ID	
	
union all	
  select sum(nvl(s1.TDY_FLOAT_INGPL, 0) + nvl(s1.DSC_COST_AMT, 0)) as RVALUE, s2.PTL_BAG_ID as RKEY	
 from (select t1.*	
from PTL_SEC_VALUTION t1	
left join FIN_PRODUCT_TYPE t2 on t1.FINPROD_ID=t2.FINPROD_ID 	
where  t1.CDATE = date''${valDate}''-1 	AND t1.PORTFOLIO_ID!=t1.FINPROD_ID
and  t2.TYPE_8  IN (''F01'',''F02'',''F03'',''F04'',''F05'',''F07'',''F09'',''F10'') OR (t2.TYPE_8=''F06'' AND T2.TYPE_6=''P08'')	
) s1,( select t1.PORTFOLIO_ID,t1.PTL_BAG_ID from RSK_PORTFOLIO_PACKAGE_DTL t1  inner join PTL_PORTFOLIO t2 on t1.PORTFOLIO_ID=t2.PORTFOLIO_ID and t2.MDATE>date''${valDate}'')	
s2 where s1.PORTFOLIO_ID=s2.PORTFOLIO_ID  group by s2.PTL_BAG_ID', 'portfolioCode', 'N', 'whmcp', '2222222', sysdate, 'whmcp', sysdate);
INSERT INTO "RSK_ISUP_INDICATOR_PARA_DTL"("PARA_CODE", "PARA_GRANULARITY", "PARA_DISPLAY_TYPE", "CONTENT", "REDIS_FIELD", "IS_FRESH_CAN_TRD", "CREATE_USER", "CREATE_DEPT", "CREATE_TIME", "UPDATE_USER", "UPDATE_TIME") VALUES ('GMCPSTZBZLZC', '03', 'SQL', 'select	
 sum(nvl(t1.TDY_FLOAT_INGPL, 0) + nvl(t1.DSC_COST_AMT, 0)) as RVALUE, t1.PORTFOLIO_ID as RKEY	
from PTL_SEC_VALUTION t1	
 left join FIN_PRODUCT_TYPE t2 on t1.FINPROD_ID=t2.FINPROD_ID 	
where  t1.CDATE = date''${valDate}''-1  AND t1.PORTFOLIO_ID!=t1.FINPROD_ID	
AND t2.TYPE_8  IN (''F01'',''F02'',''F03'',''F04'',''F05'',''F07'',''F09'',''F10'') OR (t2.TYPE_8=''F06'' AND T2.TYPE_6=''P08'')	
group by t1.PORTFOLIO_ID	
	
union all	
  select sum(nvl(s1.TDY_FLOAT_INGPL, 0) + nvl(s1.DSC_COST_AMT, 0)) as RVALUE, s2.PTL_BAG_ID as RKEY	
 from (select t1.*	
from PTL_SEC_VALUTION t1	
left join FIN_PRODUCT_TYPE t2 on t1.FINPROD_ID=t2.FINPROD_ID 	
where  t1.CDATE = date''${valDate}''-1 	AND t1.PORTFOLIO_ID!=t1.FINPROD_ID
and  t2.TYPE_8  IN (''F01'',''F02'',''F03'',''F04'',''F05'',''F07'',''F09'',''F10'') OR (t2.TYPE_8=''F06'' AND T2.TYPE_6=''P08'')	
) s1,( select t1.PORTFOLIO_ID,t1.PTL_BAG_ID from RSK_PORTFOLIO_PACKAGE_DTL t1  inner join PTL_PORTFOLIO t2 on t1.PORTFOLIO_ID=t2.PORTFOLIO_ID and t2.MDATE>date''${valDate}'')	
s2 where s1.PORTFOLIO_ID=s2.PORTFOLIO_ID  group by s2.PTL_BAG_ID', 'portfolioCode', 'N', 'whmcp', '2222222', sysdate, 'whmcp', sysdate);
INSERT INTO "RSK_ISUP_INDICATOR_PARA_DTL"("PARA_CODE", "PARA_GRANULARITY", "PARA_DISPLAY_TYPE", "CONTENT", "REDIS_FIELD", "IS_FRESH_CAN_TRD", "CREATE_USER", "CREATE_DEPT", "CREATE_TIME", "UPDATE_USER", "UPDATE_TIME") VALUES ('GMCPSTZBZLZC', '04', 'SQL', 'select nvl(sum(nvl(t1.TDY_FLOAT_INGPL, 0) + nvl(t1.DSC_COST_AMT, 0)),0) as RVALUE from PTL_SEC_VALUTION t1	 
left join FIN_PRODUCT_TYPE t2 on t1.FINPROD_ID=t2.FINPROD_ID 	
where t1.PORTFOLIO_ID in ${portfolioCode} and  t1.CDATE=date''${valDate}'' and  t2.TYPE_8  IN (''F01'',''F02'',''F03'',''F04'',''F05'',''F07'',''F09'',''F10'') OR (t2.TYPE_8=''F06'' AND T2.TYPE_6=''P08'')', 'portfolioCode', 'N', 'whmcp', '2222222', sysdate, 'whmcp', sysdate);
INSERT INTO "RSK_ISUP_INDICATOR_PARA_DTL"("PARA_CODE", "PARA_GRANULARITY", "PARA_DISPLAY_TYPE", "CONTENT", "REDIS_FIELD", "IS_FRESH_CAN_TRD", "CREATE_USER", "CREATE_DEPT", "CREATE_TIME", "UPDATE_USER", "UPDATE_TIME") VALUES ('GMCPSTZBZLZC', '01', 'SQL', 'select	
 sum(nvl(t1.TDY_FLOAT_INGPL, 0) + nvl(t1.DSC_COST_AMT, 0)) as RVALUE, t1.PORTFOLIO_ID as RKEY	
from PTL_SEC_VALUTION t1	
 left join FIN_PRODUCT_TYPE t2 on t1.FINPROD_ID=t2.FINPROD_ID 	
where  t1.CDATE = date''${valDate}''-1  AND t1.PORTFOLIO_ID!=t1.FINPROD_ID	
AND t2.TYPE_8 NOT IN (''F01'',''F02'',''F03'',''F04'',''F05'',''F07'',''F09'',''F10'') OR (t2.TYPE_8=''F06'' AND T2.TYPE_6=''P08'')	
group by t1.PORTFOLIO_ID	
	
union all	
  select sum(nvl(s1.TDY_FLOAT_INGPL, 0) + nvl(s1.DSC_COST_AMT, 0)) as RVALUE, s2.PTL_BAG_ID as RKEY	
 from (select t1.*	
from PTL_SEC_VALUTION t1	
left join FIN_PRODUCT_TYPE t2 on t1.FINPROD_ID=t2.FINPROD_ID 	
where  t1.CDATE = date''${valDate}''-1 	AND t1.PORTFOLIO_ID!=t1.FINPROD_ID
and  t2.TYPE_8  IN (''F01'',''F02'',''F03'',''F04'',''F05'',''F07'',''F09'',''F10'') OR (t2.TYPE_8=''F06'' AND T2.TYPE_6=''P08'')	
) s1,( select t1.PORTFOLIO_ID,t1.PTL_BAG_ID from RSK_PORTFOLIO_PACKAGE_DTL t1  inner join PTL_PORTFOLIO t2 on t1.PORTFOLIO_ID=t2.PORTFOLIO_ID and t2.MDATE>date''${valDate}'')	
s2 where s1.PORTFOLIO_ID=s2.PORTFOLIO_ID  group by s2.PTL_BAG_ID', 'portfolioCode', 'N', 'whmcp', '2222222', sysdate, 'whmcp', sysdate);
INSERT INTO "RSK_ISUP_INDICATOR_PARA_DTL"("PARA_CODE", "PARA_GRANULARITY", "PARA_DISPLAY_TYPE", "CONTENT", "REDIS_FIELD", "IS_FRESH_CAN_TRD", "CREATE_USER", "CREATE_DEPT", "CREATE_TIME", "UPDATE_USER", "UPDATE_TIME") VALUES ('GMCPSTZBZLZC', '05', 'SQL', 'select nvl(sum(nvl(t1.TDY_FLOAT_INGPL, 0) + nvl(t1.DSC_COST_AMT, 0)),0) as RVALUE from PTL_SEC_VALUTION t1	 
left join FIN_PRODUCT_TYPE t2 on t1.FINPROD_ID=t2.FINPROD_ID 	
where t1.PORTFOLIO_ID in ${portfolioCode} and  t1.CDATE=date''${valDate}'' and  t2.TYPE_8  IN (''F01'',''F02'',''F03'',''F04'',''F05'',''F07'',''F09'',''F10'') OR (t2.TYPE_8=''F06'' AND T2.TYPE_6=''P08'')', 'portfolioCode', 'N', 'whmcp', '2222222', sysdate, 'whmcp', sysdate);
INSERT INTO "RSK_ISUP_INDICATOR_PARA_DTL"("PARA_CODE", "PARA_GRANULARITY", "PARA_DISPLAY_TYPE", "CONTENT", "REDIS_FIELD", "IS_FRESH_CAN_TRD", "CREATE_USER", "CREATE_DEPT", "CREATE_TIME", "UPDATE_USER", "UPDATE_TIME") VALUES ('DYZCGM', '02', 'SQL', 'select	
 sum(nvl(t1.TDY_FLOAT_INGPL, 0) + nvl(t1.DSC_COST_AMT, 0)) as RVALUE, t1.PORTFOLIO_ID||'',''||t1.FINPROD_ID as RKEY	
from PTL_SEC_VALUTION t1	
 left join FIN_PRODUCT t2	
  on t1.FINPROD_ID = t2.FINPROD_ID	
left join FIN_TRADE_PRODUCT t3	
  on t1.FINPROD_ID = t3.FINPROD_ID	
where  t1.CDATE = date''${valDate}''-1  AND t1.PORTFOLIO_ID!=t1.FINPROD_ID	
and ((t3.FINPROD_TYPE2 is null and t2.FINPROD_TYPE2 is not null) or t3.FINPROD_TYPE2 not in (''F02'', ''F04'', ''F08'',''F25''))	
group by t1.PORTFOLIO_ID,t1.FINPROD_ID,t2.FINPROD_NAME	
	
union all	
  select sum(nvl(s1.TDY_FLOAT_INGPL, 0) + nvl(s1.DSC_COST_AMT, 0)) as RVALUE, s2.PTL_BAG_ID||'',''||s1.FINPROD_ID as RKEY	
 from (select t1.*	
from PTL_SEC_VALUTION t1	
 left join FIN_PRODUCT t2	
  on t1.FINPROD_ID = t2.FINPROD_ID	
left join FIN_TRADE_PRODUCT t3	
  on t1.FINPROD_ID = t3.FINPROD_ID	
where  t1.CDATE = date''${valDate}''-1 	AND t1.PORTFOLIO_ID!=t1.FINPROD_ID
and ((t3.FINPROD_TYPE2 is null and t2.FINPROD_TYPE2 is not null) or t3.FINPROD_TYPE2 not in (''F02'', ''F04'', ''F08'',''F25''))	
) s1,( select t1.PORTFOLIO_ID,t1.PTL_BAG_ID from RSK_PORTFOLIO_PACKAGE_DTL t1  inner join PTL_PORTFOLIO t2 on t1.PORTFOLIO_ID=t2.PORTFOLIO_ID and t2.MDATE>date''${valDate}'')	
s2 where s1.PORTFOLIO_ID=s2.PORTFOLIO_ID  group by s2.PTL_BAG_ID,s1.FINPROD_ID', 'portfolioCode,assetCode', 'N', 'whmcp', '2222222', sysdate, 'whmcp', sysdate);
INSERT INTO "RSK_ISUP_INDICATOR_PARA_DTL"("PARA_CODE", "PARA_GRANULARITY", "PARA_DISPLAY_TYPE", "CONTENT", "REDIS_FIELD", "IS_FRESH_CAN_TRD", "CREATE_USER", "CREATE_DEPT", "CREATE_TIME", "UPDATE_USER", "UPDATE_TIME") VALUES ('SPJJRYSPLZCGM', '04', 'SQL', 'select sum(TRADE_AMT) as tradeAmt from										
 (										
select nvl(sum(nvl(m.TDY_FLOAT_INGPL, 0) + nvl(m.DSC_COST_AMT, 0)+ nvl(m.TDY_INTINCEXP, 0)+ nvl(m.DELAY_PAY_AMT, 0)),0) as TRADE_AMT from PTL_SEC_VALUTION m 										
  INNER JOIN FIN_PRODUCT_ADD PFP										
  on m.FINPROD_ID = PFP.FINPROD_ID and PFP.INVEST_NATURE =''03''										
  LEFT JOIN FIN_PRODUCT_TYPE FPT ON m.FINPROD_ID=FPT.FINPROD_ID AND FPT.BRANCH=''0''										
where m.PORTFOLIO_ID in ${portfolioCode}  and  m.CDATE =date''${valDate}''-1 	AND m.PORTFOLIO_ID!=m.FINPROD_ID									
AND (FPT.TYPE_8 NOT IN (''F02'') OR (FPT.TYPE_8 =''F02'' AND FPT.TYPE_7 NOT IN (''04'',''03'')))										
union ALL										
select										
 nvl(sum(decode(n.PS,''T01'',n.TRADE_AMT)),0)										
  +nvl(sum(decode(n.PS,''T04'',n.TRADE_AMT)),0)										
  +nvl(sum(decode(n.PS,''T36'',n.TRADE_AMT)),0)										
  -nvl(sum(decode(n.PS,''T03'',n.TRADE_AMT)),0)										
  -nvl(sum(decode(n.PS,''T12'',n.TRADE_AMT)),0)										
  -nvl(sum(decode(n.PS,''T02'',n.TRADE_AMT)),0)										
  -nvl(sum(decode(n.PS,''T13'',n.TRADE_AMT)),0)										
  -nvl(sum(decode(n.PS,''T14'',n.TRADE_AMT)),0)										
  -nvl(sum(decode(n.PS,''T20'',n.TRADE_AMT)),0)										
  -nvl(sum(decode(n.PS,''T05'',n.TRADE_AMT)),0) as  TRADE_AMT										
  from  TRD_PRODUCT_DEAL n 										
    inner join FIN_PRODUCT_ADD FPA										
     on n.FINPROD_ID = FPA.FINPROD_ID  and FPA.INVEST_NATURE =''03''
     INNER JOIN TRD_PRODUCT_DEAL_ADD n1 ON n.TRADE_ID =n1.TRADE_ID 
  where n1.PORTFOLIO_ID in ${portfolioCode} and n.TRADE_DATE=date''${valDate}'' and n.PS in (''T01'',''T02'',''T03'',''T12'',''T04'',''T13'',''T05'',''T36'',''T14'',''T20'')										
)', 'portfolioCode', 'Y', 'admin', '2222222', sysdate, 'admin', sysdate);
INSERT INTO "RSK_ISUP_INDICATOR_PARA_DTL"("PARA_CODE", "PARA_GRANULARITY", "PARA_DISPLAY_TYPE", "CONTENT", "REDIS_FIELD", "IS_FRESH_CAN_TRD", "CREATE_USER", "CREATE_DEPT", "CREATE_TIME", "UPDATE_USER", "UPDATE_TIME") VALUES ('SPJJRYSPLZCGM', '05', 'SQL', 'select nvl(sum(nvl(m.TDY_FLOAT_INGPL, 0) + nvl(m.DSC_COST_AMT, 0)),0) as  TRADE_AMT from PTL_SEC_VALUTION m								
INNER JOIN FIN_PRODUCT_ADD PFP								
on m.FINPROD_ID = PFP.FINPROD_ID and PFP.INVEST_NATURE =''03''								
LEFT JOIN FIN_PRODUCT_TYPE FPT ON m.FINPROD_ID=FPT.FINPROD_ID AND FPT.BRANCH=''0''								
where m.PORTFOLIO_ID in ${portfolioCode}  and  m.CDATE =date''${valDate}'' AND m.PORTFOLIO_ID!=m.FINPROD_ID								
AND (FPT.TYPE_8 NOT IN (''F02'') OR (FPT.TYPE_8 =''F02'' AND FPT.TYPE_7 NOT IN (''04'',''03'')))', 'portfolioCode', 'Y', 'admin', '2222222', sysdate, 'admin', sysdate);
INSERT INTO "RSK_ISUP_INDICATOR_PARA_DTL"("PARA_CODE", "PARA_GRANULARITY", "PARA_DISPLAY_TYPE", "CONTENT", "REDIS_FIELD", "IS_FRESH_CAN_TRD", "CREATE_USER", "CREATE_DEPT", "CREATE_TIME", "UPDATE_USER", "UPDATE_TIME") VALUES ('DQRZSGJYRYNDZCJZ', '04', 'SQL', 'content1', 'portfolioCode', 'N', 'jjpei', 'jsadjflsajfsdkl', sysdate, 'jjpei', sysdate);
INSERT INTO "RSK_ISUP_INDICATOR_PARA_DTL"("PARA_CODE", "PARA_GRANULARITY", "PARA_DISPLAY_TYPE", "CONTENT", "REDIS_FIELD", "IS_FRESH_CAN_TRD", "CREATE_USER", "CREATE_DEPT", "CREATE_TIME", "UPDATE_USER", "UPDATE_TIME") VALUES ('GZQSZHZZQTZJJSZ', '02', 'SQL', 'SELECT S1.RVALUE,S1.RKEY FROM (					
	SELECT RVALUE*RVALUE2/100 AS RVALUE,RKEY FROM (				
		SELECT nvl(sum(t2.ISSUE_AMT),0) AS RVALUE,			
		(SELECT nvl(sum(s.PRICE),100) FROM MST_BOND_VALUATION_INFO s WHERE s.SEC_ID=t2.FINPROD_ID AND s.VALUE_DATE=(			
					SELECT max(VALUE_DATE) FROM MST_BOND_VALUATION_INFO m WHERE m.SEC_ID=t2.FINPROD_ID and m.VALUE_DATE<=date''${valDate}'')
			) AS RVALUE2,		
		T2.FINPROD_ID RKEY FROM  FIN_PRODUCT t2  			
		WHERE T2.FINPROD_TYPE =''F01''  GROUP BY T2.FINPROD_ID 			
	)				
					
UNION ALL					
	SELECT RVALUE,RKEY FROM (				
		SELECT			
		(SELECT nvl(sum(s.CLOSE_PRICE),0) FROM MST_FUND_MARKET_INFO s WHERE s.FUND_CODE=t2.FINPROD_MARKET_ID AND s.VALUE_DATE=(SELECT max(VALUE_DATE) 			
		FROM MST_FUND_MARKET_INFO m WHERE m.FUND_CODE=t2.FINPROD_MARKET_ID and m.VALUE_DATE<=date''${valDate}'')			
		) AS RVALUE,			
		T2.FINPROD_ID RKEY FROM FIN_PRODUCT t2  			
		WHERE  T2.FINPROD_TYPE =''F06'' GROUP BY T2.FINPROD_ID,T2.FINPROD_MARKET_ID			
	)				
) S1', 'assetCode', 'N', 'jjpei', '2222222', sysdate, 'jjpei', sysdate);
INSERT INTO "RSK_ISUP_INDICATOR_PARA_DTL"("PARA_CODE", "PARA_GRANULARITY", "PARA_DISPLAY_TYPE", "CONTENT", "REDIS_FIELD", "IS_FRESH_CAN_TRD", "CREATE_USER", "CREATE_DEPT", "CREATE_TIME", "UPDATE_USER", "UPDATE_TIME") VALUES ('GZQSZHZZQTZJJSZ', '04', 'SQL', 'SELECT DISTINCT RVALUE, RKEY, RKEYCN FROM 					
	(				
	SELECT RVALUE*RVALUE2/100 AS RVALUE,RKEY,RKEYCN FROM (				
	SELECT DISTINCT nvl(t2.ISSUE_AMT,0) AS RVALUE,				
	(SELECT nvl(sum(s.PRICE),100) FROM MST_BOND_VALUATION_INFO s WHERE s.SEC_ID=t2.FINPROD_ID AND s.VALUE_DATE=(				
			SELECT max(VALUE_DATE) FROM MST_BOND_VALUATION_INFO m WHERE m.SEC_ID=t2.FINPROD_ID and m.VALUE_DATE<=date''${valDate}'')		
	) AS RVALUE2,				
	T2.FINPROD_ID RKEY,t2.FINPROD_NAME RKEYCN FROM PTL_SEC_VALUTION T1 				
	INNER JOIN FIN_PRODUCT t2 ON t1.FINPROD_ID=t2.FINPROD_ID AND T2.FINPROD_TYPE2 =''F01''				
	WHERE t1.PORTFOLIO_ID IN ${portfolioCode} AND t1.CDATE=date''${valDate}''	-1			
 	)				
    					
UNION ALL					
	SELECT RVALUE*RVALUE2/100 AS RVALUE,RKEY,RKEYCN FROM (				
	  select DISTINCT nvl(m.ISSUE_AMT,0) AS RVALUE,				
	  (SELECT nvl(sum(s.PRICE),100) FROM MST_BOND_VALUATION_INFO s WHERE s.SEC_ID=m.FINPROD_ID AND s.VALUE_DATE=(				
				SELECT max(VALUE_DATE) FROM MST_BOND_VALUATION_INFO s1 WHERE s1.SEC_ID=m.FINPROD_ID and s1.VALUE_DATE<=date''${valDate}'')	
		) AS RVALUE2,			
	  m.FINPROD_ID RKEY,				
	  m.FINPROD_NAME RKEYCN				
	  from  TRD_PRODUCT_DEAL n 				
	  INNER JOIN TRD_PRODUCT_DEAL_ADD s ON  n.TRADE_ID=s.TRADE_ID				
	  INNER  JOIN FIN_PRODUCT m on m.FINPROD_ID=n.FINPROD_ID and n.FINPROD_TYPE2=''F01''				
	  where  s.PORTFOLIO_ID in ${portfolioCode}  and n.TRADE_DATE=date''${valDate}'' 				
  )					
  					
UNION ALL					
 SELECT RVALUE,RKEY,RKEYCN FROM (					
	SELECT (SELECT nvl(sum(s.CLOSE_PRICE),0) FROM MST_FUND_MARKET_INFO s WHERE s.FUND_CODE=t2.FINPROD_MARKET_ID AND s.VALUE_DATE=(				
		SELECT max(VALUE_DATE) FROM MST_FUND_MARKET_INFO m WHERE m.FUND_CODE=t2.FINPROD_MARKET_ID and m.VALUE_DATE<=date''${valDate}'')			
	) AS RVALUE,				
    T2.FINPROD_ID RKEY,					
	t2.FINPROD_NAME RKEYCN FROM PTL_SEC_VALUTION T1 				
	INNER JOIN FIN_PRODUCT t2 ON t1.FINPROD_ID=t2.FINPROD_ID AND T2.FINPROD_TYPE2 =''F06''				
	WHERE t1.PORTFOLIO_ID IN ${portfolioCode} AND t1.CDATE=date''${valDate}'' -1 				
	)				
					
UNION ALL					
 SELECT RVALUE,RKEY,RKEYCN FROM (					
	  select  (SELECT nvl(s.CLOSE_PRICE,0) FROM MST_FUND_MARKET_INFO s WHERE s.FUND_CODE=m.FINPROD_MARKET_ID AND s.VALUE_DATE=				
	  (SELECT max(VALUE_DATE) FROM MST_FUND_MARKET_INFO  WHERE FUND_CODE=m.FINPROD_MARKET_ID and VALUE_DATE<=date''${valDate}''))				
	   AS RVALUE,				
	   m.FINPROD_ID RKEY,m.FINPROD_NAME	RKEYCN			
	  from  TRD_PRODUCT_DEAL n 				
	  INNER JOIN TRD_PRODUCT_DEAL_ADD s ON n.TRADE_ID=s.TRADE_ID				
	  INNER  JOIN FIN_PRODUCT m on m.FINPROD_ID=n.FINPROD_ID and n.FINPROD_TYPE2=''F06''				
	  where  s.PORTFOLIO_ID in ${portfolioCode}  and n.TRADE_DATE=date''${valDate}'' 				
  )					
) T', 'assetCode', 'N', 'jjpei', '2222222', sysdate, 'jjpei', sysdate);
INSERT INTO "RSK_ISUP_INDICATOR_PARA_DTL"("PARA_CODE", "PARA_GRANULARITY", "PARA_DISPLAY_TYPE", "CONTENT", "REDIS_FIELD", "IS_FRESH_CAN_TRD", "CREATE_USER", "CREATE_DEPT", "CREATE_TIME", "UPDATE_USER", "UPDATE_TIME") VALUES ('ZHGSYQX', '03', 'SQL', 'select 1 from dual', 'portfolioCode', 'N', 'admin', '2222222', sysdate, 'admin', sysdate);
INSERT INTO "RSK_ISUP_INDICATOR_PARA_DTL"("PARA_CODE", "PARA_GRANULARITY", "PARA_DISPLAY_TYPE", "CONTENT", "REDIS_FIELD", "IS_FRESH_CAN_TRD", "CREATE_USER", "CREATE_DEPT", "CREATE_TIME", "UPDATE_USER", "UPDATE_TIME") VALUES ('ZHGSYQX', '05', 'SQL', 'SELECT (nvl(sum(TRADE_AMT*LAST_PERIOD),0)) AS lastPeriod FROM 			
(			
	select A1.TRADE_AMT,nvl((A1.mdate)-(date''${valDate}''),0) AS LAST_PERIOD		
	from		
	(		
		select	
		( nvl(m.TDY_FLOAT_INGPL, 0) + nvl(m.DSC_COST_AMT, 0)+ nvl(m.TDY_INTINCEXP, 0)+ nvl(m.DELAY_PAY_AMT, 0)) as TRADE_AMT,n.MDATE	
		from PTL_SEC_VALUTION m	
		INNER JOIN FIN_TRADE_PRODUCT n on m.FINPROD_ID = n.FINPROD_ID and n.FINPROD_TYPE =''F02''	
		where m.PORTFOLIO_ID in ${portfolioCode}  and  m.CDATE =date''${valDate}''	
	) A1		
)', 'portfolioCode', 'N', 'admin', '2222222', sysdate, 'admin', sysdate);
INSERT INTO "RSK_ISUP_INDICATOR_PARA_DTL"("PARA_CODE", "PARA_GRANULARITY", "PARA_DISPLAY_TYPE", "CONTENT", "REDIS_FIELD", "IS_FRESH_CAN_TRD", "CREATE_USER", "CREATE_DEPT", "CREATE_TIME", "UPDATE_USER", "UPDATE_TIME") VALUES ('XJGM', '03', 'SQL', 'select PORTFOLIO_ID as RKEY,nvl(sum(AMOUNT),0) as  RVALUE from PTL_CASH_POSITION		

 	 where   HODING_TYPE=''03'' and CDATE =date''${valDate}'' group by PORTFOLIO_ID', 'portfolioCode', 'N', 'jjpei', 'jsadjflsajfsdkl', sysdate, 'jjpei', sysdate);
INSERT INTO "RSK_ISUP_INDICATOR_PARA_DTL"("PARA_CODE", "PARA_GRANULARITY", "PARA_DISPLAY_TYPE", "CONTENT", "REDIS_FIELD", "IS_FRESH_CAN_TRD", "CREATE_USER", "CREATE_DEPT", "CREATE_TIME", "UPDATE_USER", "UPDATE_TIME") VALUES ('DQRZSGJYRYNDZCJZ', '05', 'SQL', 'SELECT (ROUND(sum(RVALUE),6)) AS RVALUE FROM (													

select nvl(sum(nvl(t1.TDY_FLOAT_INGPL, 0) + nvl(t1.DSC_COST_AMT, 0)+ nvl(t1.TDY_INTINCEXP, 0)+ nvl(t1.DELAY_PAY_AMT, 0)),0) as  RVALUE from PTL_SEC_VALUTION t1							

  inner join ( 							

	SELECT FINPROD_ID,MDATE,CALENDAR_ID,CDATE,FINPROD_TYPE FROM (	 					

  SELECT s1.FINPROD_ID,s1.MDATE,s1.CALENDAR_ID,s1.CDATE,s1.FINPROD_TYPE,ROW_NUMBER() OVER(PARTITION BY s1.FINPROD_ID ORDER BY s1.CDATE asc) AS rn FROM (							

			    SELECT s.FINPROD_ID,s.MDATE,s.CALENDAR_ID,s.CDATE,s.FINPROD_TYPE,s.rownum1 FROM (				

			    SELECT m.FINPROD_ID,m.MDATE,m.FINPROD_TYPE,m.CALENDAR_ID,n.CDATE,row_number() OVER(PARTITION BY m.FINPROD_ID ORDER BY n.CDATE desc) AS  rownum1 FROM (				

			  SELECT FINPROD_ID,FINPROD_TYPE,MDATE,CASE WHEN CALENDAR_ID IS NULL THEN ''01'' ELSE CALENDAR_ID end CALENDAR_ID FROM FIN_PRODUCT WHERE MDATE IS NOT null) m 				

			  INNER JOIN MST_HOLIDAY n ON  m.CALENDAR_ID=n.CALENDAR_ID  AND n.CDATE<=m.MDATE AND n.IS_HOLIDAY=0 ) s WHERE s.rownum1<=10 				

		  ) s1  					

	  )  WHERE rn=1						

  ) t2							

  on t1.FINPROD_ID = t2.FINPROD_ID and t2.MDATE>=date''${valDate}'' and t2.CDATE<=date''${valDate}''							

  where t1.PORTFOLIO_ID!=t1.FINPROD_ID AND t1.PORTFOLIO_ID in ${portfolioCode} and t1.CDATE=date''${valDate}'' 							

  GROUP BY T2.FINPROD_ID							

  							

  UNION ALL 							

  							

  select nvl(sum(nvl(t1.TDY_FLOAT_INGPL, 0) + nvl(t1.DSC_COST_AMT, 0)+ nvl(t1.TDY_INTINCEXP, 0)+ nvl(t1.DELAY_PAY_AMT, 0)),0) as  RVALUE from PTL_SEC_VALUTION t1							

  inner join ( 							

	SELECT FINPROD_ID,MDATE,CALENDAR_ID,CDATE,FINPROD_TYPE FROM (	 					

  SELECT s1.FINPROD_ID,s1.MDATE,s1.CALENDAR_ID,s1.CDATE,s1.FINPROD_TYPE,ROW_NUMBER() OVER(PARTITION BY s1.FINPROD_ID ORDER BY s1.CDATE asc) AS rn FROM (							

			    SELECT s.FINPROD_ID,s.MDATE,s.CALENDAR_ID,s.CDATE,s.FINPROD_TYPE,s.rownum1 FROM (				

			    SELECT m.FINPROD_ID,m.MDATE,m.FINPROD_TYPE,m.CALENDAR_ID,n.CDATE,row_number() OVER(PARTITION BY m.FINPROD_ID ORDER BY n.CDATE desc) AS  rownum1 FROM (				

			  SELECT FINPROD_ID,FINPROD_TYPE,MDATE,CASE WHEN CALENDAR_ID IS NULL THEN ''01'' ELSE CALENDAR_ID end CALENDAR_ID FROM FIN_TRADE_PRODUCT WHERE  FINPROD_TYPE not in (''F02'', ''F08'', ''F25'') AND MDATE IS NOT null) m 				

			  INNER JOIN MST_HOLIDAY n ON  m.CALENDAR_ID=n.CALENDAR_ID  AND n.CDATE<=m.MDATE AND n.IS_HOLIDAY=0 ) s WHERE s.rownum1<=10 				

		  ) s1  					

	  )  WHERE rn=1						

  ) t2							

  on t1.FINPROD_ID = t2.FINPROD_ID and t2.MDATE>=date''${valDate}'' and t2.CDATE<=date''${valDate}''							

  where t1.PORTFOLIO_ID!=t1.FINPROD_ID AND t1.PORTFOLIO_ID in ${portfolioCode} and t1.CDATE=date''${valDate}''  							

  GROUP BY T2.FINPROD_ID							

  )', 'portfolioCode', 'N', 'jjpei', 'jsadjflsajfsdkl', sysdate, 'jjpei', sysdate);
INSERT INTO "RSK_ISUP_INDICATOR_PARA_DTL"("PARA_CODE", "PARA_GRANULARITY", "PARA_DISPLAY_TYPE", "CONTENT", "REDIS_FIELD", "IS_FRESH_CAN_TRD", "CREATE_USER", "CREATE_DEPT", "CREATE_TIME", "UPDATE_USER", "UPDATE_TIME") VALUES ('XJGM', '01', 'SQL', 'select PORTFOLIO_ID as RKEY,nvl(sum(AMOUNT),0) as  RVALUE from PTL_CASH_POSITION		

 	 where   HODING_TYPE=''03'' and CDATE =date''${valDate}'' group by PORTFOLIO_ID', 'portfolioCode', 'N', 'jjpei', 'jsadjflsajfsdkl', sysdate, 'jjpei', sysdate);
INSERT INTO "RSK_ISUP_INDICATOR_PARA_DTL"("PARA_CODE", "PARA_GRANULARITY", "PARA_DISPLAY_TYPE", "CONTENT", "REDIS_FIELD", "IS_FRESH_CAN_TRD", "CREATE_USER", "CREATE_DEPT", "CREATE_TIME", "UPDATE_USER", "UPDATE_TIME") VALUES ('DYZCGM', '03', 'SQL', 'select	
 sum(nvl(t1.TDY_FLOAT_INGPL, 0) + nvl(t1.DSC_COST_AMT, 0)) as RVALUE, t1.PORTFOLIO_ID||'',''||t1.FINPROD_ID as RKEY	
from PTL_SEC_VALUTION t1	
 left join FIN_PRODUCT t2	
  on t1.FINPROD_ID = t2.FINPROD_ID	
left join FIN_TRADE_PRODUCT t3	
  on t1.FINPROD_ID = t3.FINPROD_ID	
where  t1.CDATE = date''${valDate}''-1  AND t1.PORTFOLIO_ID!=t1.FINPROD_ID	
and ((t3.FINPROD_TYPE2 is null and t2.FINPROD_TYPE2 is not null) or t3.FINPROD_TYPE2 not in (''F02'', ''F04'', ''F08'',''F25''))	
group by t1.PORTFOLIO_ID,t1.FINPROD_ID,t2.FINPROD_NAME	
	
union all	
  select sum(nvl(s1.TDY_FLOAT_INGPL, 0) + nvl(s1.DSC_COST_AMT, 0)) as RVALUE, s2.PTL_BAG_ID||'',''||s1.FINPROD_ID as RKEY	
 from (select t1.*	
from PTL_SEC_VALUTION t1	
 left join FIN_PRODUCT t2	
  on t1.FINPROD_ID = t2.FINPROD_ID	
left join FIN_TRADE_PRODUCT t3	
  on t1.FINPROD_ID = t3.FINPROD_ID	
where  t1.CDATE = date''${valDate}''-1 	AND t1.PORTFOLIO_ID!=t1.FINPROD_ID
and ((t3.FINPROD_TYPE2 is null and t2.FINPROD_TYPE2 is not null) or t3.FINPROD_TYPE2 not in (''F02'', ''F04'', ''F08'',''F25''))	
) s1,( select t1.PORTFOLIO_ID,t1.PTL_BAG_ID from RSK_PORTFOLIO_PACKAGE_DTL t1  inner join PTL_PORTFOLIO t2 on t1.PORTFOLIO_ID=t2.PORTFOLIO_ID and t2.MDATE>date''${valDate}'')	
s2 where s1.PORTFOLIO_ID=s2.PORTFOLIO_ID  group by s2.PTL_BAG_ID,s1.FINPROD_ID', 'portfolioCode,assetCode', 'N', 'whmcp', '2222222', sysdate, 'whmcp', sysdate);
INSERT INTO "RSK_ISUP_INDICATOR_PARA_DTL"("PARA_CODE", "PARA_GRANULARITY", "PARA_DISPLAY_TYPE", "CONTENT", "REDIS_FIELD", "IS_FRESH_CAN_TRD", "CREATE_USER", "CREATE_DEPT", "CREATE_TIME", "UPDATE_USER", "UPDATE_TIME") VALUES ('DYZCGM', '01', 'SQL', 'select	
 sum(nvl(t1.TDY_FLOAT_INGPL, 0) + nvl(t1.DSC_COST_AMT, 0)) as RVALUE, t1.PORTFOLIO_ID||'',''||t1.FINPROD_ID as RKEY	
from PTL_SEC_VALUTION t1	
 left join FIN_PRODUCT t2	
  on t1.FINPROD_ID = t2.FINPROD_ID	
left join FIN_TRADE_PRODUCT t3	
  on t1.FINPROD_ID = t3.FINPROD_ID	
where  t1.CDATE = date''${valDate}''-1  AND t1.PORTFOLIO_ID!=t1.FINPROD_ID	
and ((t3.FINPROD_TYPE2 is null and t2.FINPROD_TYPE2 is not null) or t3.FINPROD_TYPE2 not in (''F02'', ''F04'', ''F08'',''F25''))	
group by t1.PORTFOLIO_ID,t1.FINPROD_ID,t2.FINPROD_NAME	
	
union all	
  select sum(nvl(s1.TDY_FLOAT_INGPL, 0) + nvl(s1.DSC_COST_AMT, 0)) as RVALUE, s2.PTL_BAG_ID||'',''||s1.FINPROD_ID as RKEY	
 from (select t1.*	
from PTL_SEC_VALUTION t1	
 left join FIN_PRODUCT t2	
  on t1.FINPROD_ID = t2.FINPROD_ID	
left join FIN_TRADE_PRODUCT t3	
  on t1.FINPROD_ID = t3.FINPROD_ID	
where  t1.CDATE = date''${valDate}''-1 	AND t1.PORTFOLIO_ID!=t1.FINPROD_ID
and ((t3.FINPROD_TYPE2 is null and t2.FINPROD_TYPE2 is not null) or t3.FINPROD_TYPE2 not in (''F02'', ''F04'', ''F08'',''F25''))	
) s1,( select t1.PORTFOLIO_ID,t1.PTL_BAG_ID from RSK_PORTFOLIO_PACKAGE_DTL t1  inner join PTL_PORTFOLIO t2 on t1.PORTFOLIO_ID=t2.PORTFOLIO_ID and t2.MDATE>date''${valDate}'')	
s2 where s1.PORTFOLIO_ID=s2.PORTFOLIO_ID  group by s2.PTL_BAG_ID,s1.FINPROD_ID', 'portfolioCode,assetCode', 'N', 'whmcp', '2222222', sysdate, 'whmcp', sysdate);
INSERT INTO "RSK_ISUP_INDICATOR_PARA_DTL"("PARA_CODE", "PARA_GRANULARITY", "PARA_DISPLAY_TYPE", "CONTENT", "REDIS_FIELD", "IS_FRESH_CAN_TRD", "CREATE_USER", "CREATE_DEPT", "CREATE_TIME", "UPDATE_USER", "UPDATE_TIME") VALUES ('QYLZCGM', '01', 'SQL', 'select m.PORTFOLIO_ID as RKEY,nvl(sum(nvl(m.TDY_FLOAT_INGPL, 0) + nvl(m.DSC_COST_AMT, 0)),0) as  RVALUE from PTL_SEC_VALUTION m	
INNER JOIN FIN_PRODUCT_ADD PFP	
on m.FINPROD_ID = PFP.FINPROD_ID and PFP.INVEST_NATURE =''02''	
LEFT JOIN FIN_PRODUCT_TYPE FPT ON m.FINPROD_ID=FPT.FINPROD_ID AND FPT.BRANCH=''0''	
where  m.CDATE =date''${valDate}''-1  AND m.PORTFOLIO_ID!=m.FINPROD_ID 	
AND (FPT.TYPE_8 NOT IN (''F02'') OR (FPT.TYPE_8 =''F02'' AND FPT.TYPE_7 NOT IN (''04'',''03''))) group by m.PORTFOLIO_ID	
	
union all	
   select t.PTL_BAG_ID as RKEY,	
   ( SELECT NVL(SUM(nvl(M.TDY_FLOAT_INGPL, 0) + nvl(M.DSC_COST_AMT, 0)),0)  AS RVALUE 	
	FROM PTL_SEC_VALUTION M
	INNER JOIN FIN_PRODUCT_ADD PFP
	ON M.FINPROD_ID = PFP.FINPROD_ID AND PFP.INVEST_NATURE = ''02''
	LEFT JOIN FIN_PRODUCT_TYPE FPT ON m.FINPROD_ID=FPT.FINPROD_ID AND FPT.BRANCH=''0''
	WHERE M.CDATE = date''${valDate}''-1  AND m.PORTFOLIO_ID!=m.FINPROD_ID
	AND (FPT.TYPE_8 NOT IN (''F02'') OR (FPT.TYPE_8 =''F02'' AND FPT.TYPE_7 NOT IN (''04'',''03''))) AND 
	M.PORTFOLIO_ID in (   select t1.PORTFOLIO_ID from RSK_PORTFOLIO_PACKAGE_DTL t1  inner join PTL_PORTFOLIO t2 on t1.PORTFOLIO_ID=t2.PORTFOLIO_ID and t2.MDATE>date''${valDate}'' where t1.PTL_BAG_ID=t.PTL_BAG_ID)
   )	
   from RSK_PORTFOLIO_PACKAGE t', 'portfolioCode', 'N', 'whmcp', '2222222', sysdate, 'whmcp', sysdate);
INSERT INTO "RSK_ISUP_INDICATOR_PARA_DTL"("PARA_CODE", "PARA_GRANULARITY", "PARA_DISPLAY_TYPE", "CONTENT", "REDIS_FIELD", "IS_FRESH_CAN_TRD", "CREATE_USER", "CREATE_DEPT", "CREATE_TIME", "UPDATE_USER", "UPDATE_TIME") VALUES ('QYLZCGM', '03', 'SQL', 'select m.PORTFOLIO_ID as RKEY,nvl(sum(nvl(m.TDY_FLOAT_INGPL, 0) + nvl(m.DSC_COST_AMT, 0)),0) as  RVALUE from PTL_SEC_VALUTION m	
INNER JOIN FIN_PRODUCT_ADD PFP	
on m.FINPROD_ID = PFP.FINPROD_ID and PFP.INVEST_NATURE =''02''	
LEFT JOIN FIN_PRODUCT_TYPE FPT ON m.FINPROD_ID=FPT.FINPROD_ID AND FPT.BRANCH=''0''	
where  m.CDATE =date''${valDate}''-1  AND m.PORTFOLIO_ID!=m.FINPROD_ID 	
AND (FPT.TYPE_8 NOT IN (''F02'') OR (FPT.TYPE_8 =''F02'' AND FPT.TYPE_7 NOT IN (''04'',''03''))) group by m.PORTFOLIO_ID	
	
union all	
   select t.PTL_BAG_ID as RKEY,	
   ( SELECT NVL(SUM(nvl(M.TDY_FLOAT_INGPL, 0) + nvl(M.DSC_COST_AMT, 0)),0)  AS RVALUE 	
	FROM PTL_SEC_VALUTION M
	INNER JOIN FIN_PRODUCT_ADD PFP
	ON M.FINPROD_ID = PFP.FINPROD_ID AND PFP.INVEST_NATURE = ''02''
	LEFT JOIN FIN_PRODUCT_TYPE FPT ON m.FINPROD_ID=FPT.FINPROD_ID AND FPT.BRANCH=''0''
	WHERE M.CDATE = date''${valDate}''-1  AND m.PORTFOLIO_ID!=m.FINPROD_ID
	AND (FPT.TYPE_8 NOT IN (''F02'') OR (FPT.TYPE_8 =''F02'' AND FPT.TYPE_7 NOT IN (''04'',''03''))) AND 
	M.PORTFOLIO_ID in (   select t1.PORTFOLIO_ID from RSK_PORTFOLIO_PACKAGE_DTL t1  inner join PTL_PORTFOLIO t2 on t1.PORTFOLIO_ID=t2.PORTFOLIO_ID and t2.MDATE>date''${valDate}'' where t1.PTL_BAG_ID=t.PTL_BAG_ID)
   )	
   from RSK_PORTFOLIO_PACKAGE t', 'portfolioCode', 'N', 'whmcp', '2222222', sysdate, 'whmcp', sysdate);
INSERT INTO "RSK_ISUP_INDICATOR_PARA_DTL"("PARA_CODE", "PARA_GRANULARITY", "PARA_DISPLAY_TYPE", "CONTENT", "REDIS_FIELD", "IS_FRESH_CAN_TRD", "CREATE_USER", "CREATE_DEPT", "CREATE_TIME", "UPDATE_USER", "UPDATE_TIME") VALUES ('TZDYSSGSFXGP', '02', 'SQL', 'SELECT nvl(sum(nvl(RVALUE, 0)),0) as RVALUE,s1.RKEY  FROM (	
select	
 sum(nvl(t1.TDY_FLOAT_INGPL, 0) + nvl(t1.DSC_COST_AMT, 0)) as RVALUE, t1.PORTFOLIO_ID||'',''||t1.FINPROD_ID as RKEY	
from PTL_SEC_VALUTION t1	
inner join FIN_PRODUCT t2 on t1.FINPROD_ID = t2.FINPROD_ID and t2.FINPROD_TYPE =''F10''	
where  t1.CDATE = date''${valDate}''-1 	
group by t1.PORTFOLIO_ID,t1.FINPROD_ID,t2.FINPROD_NAME	
	
UNION ALL	
  select sum(nvl(s1.TDY_FLOAT_INGPL, 0) + nvl(s1.DSC_COST_AMT, 0)) as RVALUE, s2.PTL_BAG_ID||'',''||s1.FINPROD_ID as RKEY	
 from (select t1.*	
from PTL_SEC_VALUTION t1	
inner join FIN_PRODUCT t2 on t1.FINPROD_ID = t2.FINPROD_ID and t2.FINPROD_TYPE =''F10''	
where  t1.CDATE = date''${valDate}''-1 	
) s1,( select t1.PORTFOLIO_ID,t1.PTL_BAG_ID from RSK_PORTFOLIO_PACKAGE_DTL t1  inner join PTL_PORTFOLIO t2 on t1.PORTFOLIO_ID=t2.PORTFOLIO_ID and t2.MDATE>date''${valDate}''-1 )	
s2 where s1.PORTFOLIO_ID=s2.PORTFOLIO_ID  group by s2.PTL_BAG_ID,s1.FINPROD_ID	
	
 ) s1 group by s1.RKEY', 'portfolioCode,assetCode', 'N', 'admin', '2222222', sysdate, 'admin', sysdate);
INSERT INTO "RSK_ISUP_INDICATOR_PARA_DTL"("PARA_CODE", "PARA_GRANULARITY", "PARA_DISPLAY_TYPE", "CONTENT", "REDIS_FIELD", "IS_FRESH_CAN_TRD", "CREATE_USER", "CREATE_DEPT", "CREATE_TIME", "UPDATE_USER", "UPDATE_TIME") VALUES ('QYLZCGM', '04', 'SQL', 'select sum(TRADE_AMT) as tradeAmt from											
 (											
select nvl(sum(nvl(m.TDY_FLOAT_INGPL, 0) + nvl(m.DSC_COST_AMT, 0)),0) as TRADE_AMT from PTL_SEC_VALUTION m 											
  INNER JOIN FIN_PRODUCT_ADD PFP											
  on m.FINPROD_ID = PFP.FINPROD_ID and PFP.INVEST_NATURE =''02''											
  LEFT JOIN FIN_PRODUCT_TYPE FPT ON m.FINPROD_ID=FPT.FINPROD_ID AND FPT.BRANCH=''0''											
where m.PORTFOLIO_ID in ${portfolioCode}  and  m.CDATE =date''${valDate}''-1 	AND m.PORTFOLIO_ID!=m.FINPROD_ID										
AND (FPT.TYPE_8 NOT IN (''F02'') OR (FPT.TYPE_8 =''F02'' AND FPT.TYPE_7 NOT IN (''04'',''03'')))	)										
union ALL											
  select											
     nvl(sum(decode(n.PS,''T01'',n.TRADE_AMT)),0)											
  +nvl(sum(decode(n.PS,''T04'',n.TRADE_AMT)),0)											
  +nvl(sum(decode(n.PS,''T36'',n.TRADE_AMT)),0)											
  -nvl(sum(decode(n.PS,''T03'',n.TRADE_AMT)),0)											
  -nvl(sum(decode(n.PS,''T12'',n.TRADE_AMT)),0)											
  -nvl(sum(decode(n.PS,''T02'',n.TRADE_AMT)),0)											
  -nvl(sum(decode(n.PS,''T13'',n.TRADE_AMT)),0)											
  -nvl(sum(decode(n.PS,''T14'',n.TRADE_AMT)),0)											
  -nvl(sum(decode(n.PS,''T20'',n.TRADE_AMT)),0)											
  -nvl(sum(decode(n.PS,''T05'',n.TRADE_AMT)),0) as  TRADE_AMT											
  from TRD_PRODUCT_DEAL n  											
    INNER JOIN FIN_PRODUCT_ADD PFP											
   on n.FINPROD_ID = PFP.FINPROD_ID and PFP.INVEST_NATURE =''02''	
     LEFT JOIN TRD_PRODUCT_DEAL_ADD n1 ON n.TRADE_ID =n1.TRADE_ID 
  where n1.PORTFOLIO_ID in ${portfolioCode} and n.TRADE_DATE=date''${valDate}'' and n.PS in (''T01'',''T02'',''T03'',''T12'',''T04'',''T13'',''T05'',''T36'',''T14'',''T20'')											
)', 'portfolioCode', 'N', 'whmcp', '2222222', sysdate, 'whmcp', sysdate);
INSERT INTO "RSK_ISUP_INDICATOR_PARA_DTL"("PARA_CODE", "PARA_GRANULARITY", "PARA_DISPLAY_TYPE", "CONTENT", "REDIS_FIELD", "IS_FRESH_CAN_TRD", "CREATE_USER", "CREATE_DEPT", "CREATE_TIME", "UPDATE_USER", "UPDATE_TIME") VALUES ('QYLZCGM', '05', 'SQL', 'select nvl(sum(nvl(m.TDY_FLOAT_INGPL, 0) + nvl(m.DSC_COST_AMT, 0)),0) as  TRADE_AMT from PTL_SEC_VALUTION m											
INNER JOIN FIN_PRODUCT_ADD PFP											
on m.FINPROD_ID = PFP.FINPROD_ID and PFP.INVEST_NATURE =''02'' 											
LEFT JOIN FIN_PRODUCT_TYPE FPT ON m.FINPROD_ID=FPT.FINPROD_ID AND FPT.BRANCH=''0''											
where m.PORTFOLIO_ID in ${portfolioCode}  and  m.CDATE =date''${valDate}'' AND m.PORTFOLIO_ID!=m.FINPROD_ID											
AND (FPT.TYPE_8 NOT IN (''F02'') OR (FPT.TYPE_8 =''F02'' AND FPT.TYPE_7 NOT IN (''04'',''03'')))', 'portfolioCode', 'N', 'whmcp', '2222222', sysdate, 'whmcp', sysdate);
INSERT INTO "RSK_ISUP_INDICATOR_PARA_DTL"("PARA_CODE", "PARA_GRANULARITY", "PARA_DISPLAY_TYPE", "CONTENT", "REDIS_FIELD", "IS_FRESH_CAN_TRD", "CREATE_USER", "CREATE_DEPT", "CREATE_TIME", "UPDATE_USER", "UPDATE_TIME") VALUES ('FBZCJE', '02', 'SQL', 'select m.PORTFOLIO_ID AS RKEY,nvl(sum(nvl(m.TDY_FLOAT_INGPL, 0) + nvl(m.DSC_COST_AMT, 0)),0) as  RVALUE from PTL_SEC_VALUTION m		
inner join FIN_PRODUCT_TYPE fpt on m.FINPROD_ID=fpt.FINPROD_ID 		
    and (fpt.TYPE_8 =''F06'' or  (fpt.TYPE_8 =''F01'' and fpt.TYPE_6 in (''B13'',''B18'')))	 	
where    m.CDATE =date''${valDate}''-1  group by m.PORTFOLIO_ID		
		
union all		
   select t.PTL_BAG_ID as RKEY,		
   ( select nvl(sum(nvl(m.TDY_FLOAT_INGPL, 0) + nvl(m.DSC_COST_AMT, 0)),0) as  RVALUE from PTL_SEC_VALUTION m		
	inner join FIN_PRODUCT_TYPE fpt on m.FINPROD_ID=fpt.FINPROD_ID  and (fpt.TYPE_8 =''F06'' or  (fpt.TYPE_8 =''F01'' and fpt.TYPE_6 in (''B13'',''B18'')))	 
	where    m.CDATE =date''${valDate}''-1  AND 	
	m.PORTFOLIO_ID in (   select t1.PORTFOLIO_ID from RSK_PORTFOLIO_PACKAGE_DTL t1  inner join PTL_PORTFOLIO t2 on t1.PORTFOLIO_ID=t2.PORTFOLIO_ID and t2.MDATE>date''${valDate}'' where t1.PTL_BAG_ID=t.PTL_BAG_ID)	
   )		
   from RSK_PORTFOLIO_PACKAGE t', 'portfolioCode', 'N', 'whmcp', '2222222', sysdate, 'whmcp', sysdate);
INSERT INTO "RSK_ISUP_INDICATOR_PARA_DTL"("PARA_CODE", "PARA_GRANULARITY", "PARA_DISPLAY_TYPE", "CONTENT", "REDIS_FIELD", "IS_FRESH_CAN_TRD", "CREATE_USER", "CREATE_DEPT", "CREATE_TIME", "UPDATE_USER", "UPDATE_TIME") VALUES ('FBZCJE', '03', 'SQL', 'select m.PORTFOLIO_ID AS RKEY,nvl(sum(nvl(m.TDY_FLOAT_INGPL, 0) + nvl(m.DSC_COST_AMT, 0)),0) as  RVALUE from PTL_SEC_VALUTION m		
inner join FIN_PRODUCT_TYPE fpt on m.FINPROD_ID=fpt.FINPROD_ID 		
    and (fpt.TYPE_8 =''F06'' or  (fpt.TYPE_8 =''F01'' and fpt.TYPE_6 in (''B13'',''B18'')))	 	
where    m.CDATE =date''${valDate}''-1  group by m.PORTFOLIO_ID		
		
union all		
   select t.PTL_BAG_ID as RKEY,		
   ( select nvl(sum(nvl(m.TDY_FLOAT_INGPL, 0) + nvl(m.DSC_COST_AMT, 0)),0) as  RVALUE from PTL_SEC_VALUTION m		
	inner join FIN_PRODUCT_TYPE fpt on m.FINPROD_ID=fpt.FINPROD_ID  and (fpt.TYPE_8 =''F06'' or  (fpt.TYPE_8 =''F01'' and fpt.TYPE_6 in (''B13'',''B18'')))	 
	where    m.CDATE =date''${valDate}''-1  AND 	
	m.PORTFOLIO_ID in (   select t1.PORTFOLIO_ID from RSK_PORTFOLIO_PACKAGE_DTL t1  inner join PTL_PORTFOLIO t2 on t1.PORTFOLIO_ID=t2.PORTFOLIO_ID and t2.MDATE>date''${valDate}'' where t1.PTL_BAG_ID=t.PTL_BAG_ID)	
   )		
   from RSK_PORTFOLIO_PACKAGE t', 'portfolioCode', 'N', 'whmcp', '2222222', sysdate, 'whmcp', sysdate);
INSERT INTO "RSK_ISUP_INDICATOR_PARA_DTL"("PARA_CODE", "PARA_GRANULARITY", "PARA_DISPLAY_TYPE", "CONTENT", "REDIS_FIELD", "IS_FRESH_CAN_TRD", "CREATE_USER", "CREATE_DEPT", "CREATE_TIME", "UPDATE_USER", "UPDATE_TIME") VALUES ('FBZCJE', '01', 'SQL', 'select m.PORTFOLIO_ID AS RKEY,nvl(sum(nvl(m.TDY_FLOAT_INGPL, 0) + nvl(m.DSC_COST_AMT, 0)),0) as  RVALUE from PTL_SEC_VALUTION m		
inner join FIN_PRODUCT_TYPE fpt on m.FINPROD_ID=fpt.FINPROD_ID 		
    and (fpt.TYPE_8 =''F06'' or  (fpt.TYPE_8 =''F01'' and fpt.TYPE_6 in (''B13'',''B18'')))	 	
where    m.CDATE =date''${valDate}''-1  group by m.PORTFOLIO_ID		
		
union all		
   select t.PTL_BAG_ID as RKEY,		
   ( select nvl(sum(nvl(m.TDY_FLOAT_INGPL, 0) + nvl(m.DSC_COST_AMT, 0)),0) as  RVALUE from PTL_SEC_VALUTION m		
	inner join FIN_PRODUCT_TYPE fpt on m.FINPROD_ID=fpt.FINPROD_ID  and (fpt.TYPE_8 =''F06'' or  (fpt.TYPE_8 =''F01'' and fpt.TYPE_6 in (''B13'',''B18'')))	 
	where    m.CDATE =date''${valDate}''-1  AND 	
	m.PORTFOLIO_ID in (   select t1.PORTFOLIO_ID from RSK_PORTFOLIO_PACKAGE_DTL t1  inner join PTL_PORTFOLIO t2 on t1.PORTFOLIO_ID=t2.PORTFOLIO_ID and t2.MDATE>date''${valDate}'' where t1.PTL_BAG_ID=t.PTL_BAG_ID)	
   )		
   from RSK_PORTFOLIO_PACKAGE t', 'portfolioCode', 'N', 'whmcp', '2222222', sysdate, 'whmcp', sysdate);
INSERT INTO "RSK_ISUP_INDICATOR_PARA_DTL"("PARA_CODE", "PARA_GRANULARITY", "PARA_DISPLAY_TYPE", "CONTENT", "REDIS_FIELD", "IS_FRESH_CAN_TRD", "CREATE_USER", "CREATE_DEPT", "CREATE_TIME", "UPDATE_USER", "UPDATE_TIME") VALUES ('FBZCJE', '05', 'SQL', 'select nvl(sum(nvl(m.TDY_FLOAT_INGPL, 0) + nvl(m.DSC_COST_AMT, 0)+ nvl(m.TDY_INTINCEXP, 0)+ nvl(m.DELAY_PAY_AMT, 0)),0) as  TRADE_AMT from PTL_SEC_VALUTION m	
inner join FIN_PRODUCT_TYPE fpt on m.FINPROD_ID=fpt.FINPROD_ID and (fpt.TYPE_6 =''06'' or  (fpt.TYPE_6 =''05'' and fpt.TYPE_7 in (''02'',''05''))) 	
where m.PORTFOLIO_ID in ${portfolioCode}  and  m.CDATE =date''${valDate}''', 'portfolioCode', 'N', 'whmcp', '2222222', sysdate, 'whmcp', sysdate);
INSERT INTO "RSK_ISUP_INDICATOR_PARA_DTL"("PARA_CODE", "PARA_GRANULARITY", "PARA_DISPLAY_TYPE", "CONTENT", "REDIS_FIELD", "IS_FRESH_CAN_TRD", "CREATE_USER", "CREATE_DEPT", "CREATE_TIME", "UPDATE_USER", "UPDATE_TIME") VALUES ('SSGSKLTGB', '02', 'SQL', 'SELECT (SELECT nvl(sum(s.C_SHARES),0) FROM MST_SHARE_PRICE s WHERE s.SHARES_ID=t2.FINPROD_MARKET_ID AND s.DEAL_DATE=(		
		SELECT max(DEAL_DATE) FROM MST_SHARE_PRICE m WHERE m.SHARES_ID=t2.FINPROD_MARKET_ID and m.DEAL_DATE<=date''${valDate}'')
	) AS RVALUE,	
    T2.FINPROD_ID RKEY		
	from FIN_PRODUCT t2 where T2.FINPROD_TYPE2 =''F10'' GROUP BY T2.FINPROD_ID,T2.FINPROD_MARKET_ID', 'assetCode', 'N', 'admin', '2222222', sysdate, 'admin', sysdate);
INSERT INTO "RSK_ISUP_INDICATOR_PARA_DTL"("PARA_CODE", "PARA_GRANULARITY", "PARA_DISPLAY_TYPE", "CONTENT", "REDIS_FIELD", "IS_FRESH_CAN_TRD", "CREATE_USER", "CREATE_DEPT", "CREATE_TIME", "UPDATE_USER", "UPDATE_TIME") VALUES ('TZDYSSGSFXGP', '05', 'SQL', 'select nvl(sum(nvl(t1.TDY_FLOAT_INGPL, 0) + nvl(t1.DSC_COST_AMT, 0)),0) as RVALUE, t1.FINPROD_ID as RKEY,t2.FINPROD_NAME AS RKEYCN from PTL_SEC_VALUTION t1	
inner join FIN_PRODUCT t2 on t1.FINPROD_ID=t2.FINPROD_ID and t2.FINPROD_TYPE2 in (''F10'')	
where t1.PORTFOLIO_ID in ${portfolioCode} and  t1.CDATE=date''${valDate}'' group by t1.FINPROD_ID,t2.FINPROD_NAME', 'portfolioCode,assetCode', 'N', 'admin', '2222222', sysdate, 'admin', sysdate);
INSERT INTO "RSK_ISUP_INDICATOR_PARA_DTL"("PARA_CODE", "PARA_GRANULARITY", "PARA_DISPLAY_TYPE", "CONTENT", "REDIS_FIELD", "IS_FRESH_CAN_TRD", "CREATE_USER", "CREATE_DEPT", "CREATE_TIME", "UPDATE_USER", "UPDATE_TIME") VALUES ('TZDYSSGSFXGP', '04', 'SQL', 'select nvl(sum(nvl(t1.TDY_FLOAT_INGPL, 0) + nvl(t1.DSC_COST_AMT, 0)),0) as RVALUE, t1.FINPROD_ID as RKEY,t2.FINPROD_NAME AS RKEYCN from PTL_SEC_VALUTION t1	
inner join FIN_PRODUCT t2 on t1.FINPROD_ID=t2.FINPROD_ID and t2.FINPROD_TYPE2 in (''F10'')	
where t1.PORTFOLIO_ID in ${portfolioCode} and  t1.CDATE=date''${valDate}'' group by t1.FINPROD_ID,t2.FINPROD_NAME', 'portfolioCode,assetCode', 'N', 'admin', '2222222', sysdate, 'admin', sysdate);
INSERT INTO "RSK_ISUP_INDICATOR_PARA_DTL"("PARA_CODE", "PARA_GRANULARITY", "PARA_DISPLAY_TYPE", "CONTENT", "REDIS_FIELD", "IS_FRESH_CAN_TRD", "CREATE_USER", "CREATE_DEPT", "CREATE_TIME", "UPDATE_USER", "UPDATE_TIME") VALUES ('TZDYSSGSFXGP', '03', 'SQL', 'SELECT nvl(sum(nvl(RVALUE, 0)),0) as RVALUE,s1.RKEY  FROM (	
select	
 sum(nvl(t1.TDY_FLOAT_INGPL, 0) + nvl(t1.DSC_COST_AMT, 0)) as RVALUE, t1.PORTFOLIO_ID||'',''||t1.FINPROD_ID as RKEY	
from PTL_SEC_VALUTION t1	
inner join FIN_PRODUCT t2 on t1.FINPROD_ID = t2.FINPROD_ID and t2.FINPROD_TYPE =''F10''	
where  t1.CDATE = date''${valDate}''-1 	
group by t1.PORTFOLIO_ID,t1.FINPROD_ID,t2.FINPROD_NAME	
	
UNION ALL	
  select sum(nvl(s1.TDY_FLOAT_INGPL, 0) + nvl(s1.DSC_COST_AMT, 0)) as RVALUE, s2.PTL_BAG_ID||'',''||s1.FINPROD_ID as RKEY	
 from (select t1.*	
from PTL_SEC_VALUTION t1	
inner join FIN_PRODUCT t2 on t1.FINPROD_ID = t2.FINPROD_ID and t2.FINPROD_TYPE =''F10''	
where  t1.CDATE = date''${valDate}''-1 	
) s1,( select t1.PORTFOLIO_ID,t1.PTL_BAG_ID from RSK_PORTFOLIO_PACKAGE_DTL t1  inner join PTL_PORTFOLIO t2 on t1.PORTFOLIO_ID=t2.PORTFOLIO_ID and t2.MDATE>date''${valDate}''-1 )	
s2 where s1.PORTFOLIO_ID=s2.PORTFOLIO_ID  group by s2.PTL_BAG_ID,s1.FINPROD_ID	
	
 ) s1 group by s1.RKEY', 'portfolioCode,assetCode', 'N', 'admin', '2222222', sysdate, 'admin', sysdate);
INSERT INTO "RSK_ISUP_INDICATOR_PARA_DTL"("PARA_CODE", "PARA_GRANULARITY", "PARA_DISPLAY_TYPE", "CONTENT", "REDIS_FIELD", "IS_FRESH_CAN_TRD", "CREATE_USER", "CREATE_DEPT", "CREATE_TIME", "UPDATE_USER", "UPDATE_TIME") VALUES ('TZDYSSGSFXGP', '01', 'SQL', 'SELECT nvl(sum(nvl(RVALUE, 0)),0) as RVALUE,s1.RKEY  FROM (	
select	
 sum(nvl(t1.TDY_FLOAT_INGPL, 0) + nvl(t1.DSC_COST_AMT, 0)) as RVALUE, t1.PORTFOLIO_ID||'',''||t1.FINPROD_ID as RKEY	
from PTL_SEC_VALUTION t1	
inner join FIN_PRODUCT t2 on t1.FINPROD_ID = t2.FINPROD_ID and t2.FINPROD_TYPE =''F10''	
where  t1.CDATE = date''${valDate}''-1 	
group by t1.PORTFOLIO_ID,t1.FINPROD_ID,t2.FINPROD_NAME	
	
UNION ALL	
  select sum(nvl(s1.TDY_FLOAT_INGPL, 0) + nvl(s1.DSC_COST_AMT, 0)) as RVALUE, s2.PTL_BAG_ID||'',''||s1.FINPROD_ID as RKEY	
 from (select t1.*	
from PTL_SEC_VALUTION t1	
inner join FIN_PRODUCT t2 on t1.FINPROD_ID = t2.FINPROD_ID and t2.FINPROD_TYPE =''F10''	
where  t1.CDATE = date''${valDate}''-1 	
) s1,( select t1.PORTFOLIO_ID,t1.PTL_BAG_ID from RSK_PORTFOLIO_PACKAGE_DTL t1  inner join PTL_PORTFOLIO t2 on t1.PORTFOLIO_ID=t2.PORTFOLIO_ID and t2.MDATE>date''${valDate}''-1 )	
s2 where s1.PORTFOLIO_ID=s2.PORTFOLIO_ID  group by s2.PTL_BAG_ID,s1.FINPROD_ID	
	
 ) s1 group by s1.RKEY', 'portfolioCode,assetCode', 'N', 'admin', '2222222', sysdate, 'admin', sysdate);
INSERT INTO "RSK_ISUP_INDICATOR_PARA_DTL"("PARA_CODE", "PARA_GRANULARITY", "PARA_DISPLAY_TYPE", "CONTENT", "REDIS_FIELD", "IS_FRESH_CAN_TRD", "CREATE_USER", "CREATE_DEPT", "CREATE_TIME", "UPDATE_USER", "UPDATE_TIME") VALUES ('DQRZSGJYRYNDZCJZ', '01', 'SQL', 'SELECT 1 from dual', 'portfolioCode', 'N', 'jjpei', 'jsadjflsajfsdkl', sysdate, 'jjpei', sysdate);
INSERT INTO "RSK_ISUP_INDICATOR_PARA_DTL"("PARA_CODE", "PARA_GRANULARITY", "PARA_DISPLAY_TYPE", "CONTENT", "REDIS_FIELD", "IS_FRESH_CAN_TRD", "CREATE_USER", "CREATE_DEPT", "CREATE_TIME", "UPDATE_USER", "UPDATE_TIME") VALUES ('SSGSKLTGB', '05', 'SQL', 'SELECT RVALUE,RKEY,RKEYCN FROM (		
	SELECT (SELECT nvl(sum(s.C_SHARES),0) FROM MST_SHARE_PRICE s WHERE s.SHARES_ID=t2.FINPROD_MARKET_ID AND s.DEAL_DATE=(	
		SELECT max(DEAL_DATE) FROM MST_SHARE_PRICE m WHERE m.SHARES_ID=t2.FINPROD_MARKET_ID and m.DEAL_DATE<=date''${valDate}'')
	) AS RVALUE,	
    T2.FINPROD_ID RKEY,		
	t2.FINPROD_NAME RKEYCN FROM PTL_SEC_VALUTION T1 	
	INNER JOIN FIN_PRODUCT t2 ON t1.FINPROD_ID=t2.FINPROD_ID AND T2.FINPROD_TYPE2 =''F10''	
	WHERE t1.PORTFOLIO_ID IN ${portfolioCode} AND t1.CDATE=date''${valDate}''	
	)', 'assetCode', 'N', 'admin', '2222222', sysdate, 'admin', sysdate);
INSERT INTO "RSK_ISUP_INDICATOR_PARA_DTL"("PARA_CODE", "PARA_GRANULARITY", "PARA_DISPLAY_TYPE", "CONTENT", "REDIS_FIELD", "IS_FRESH_CAN_TRD", "CREATE_USER", "CREATE_DEPT", "CREATE_TIME", "UPDATE_USER", "UPDATE_TIME") VALUES ('SSGSKLTGB', '01', 'SQL', 'SELECT (SELECT nvl(sum(s.C_SHARES),0) FROM MST_SHARE_PRICE s WHERE s.SHARES_ID=t2.FINPROD_MARKET_ID AND s.DEAL_DATE=(		
		SELECT max(DEAL_DATE) FROM MST_SHARE_PRICE m WHERE m.SHARES_ID=t2.FINPROD_MARKET_ID and m.DEAL_DATE<=date''${valDate}'')
	) AS RVALUE,	
    T2.FINPROD_ID RKEY		
	from FIN_PRODUCT t2 where T2.FINPROD_TYPE2 =''F10'' GROUP BY T2.FINPROD_ID,T2.FINPROD_MARKET_ID', 'assetCode', 'N', 'admin', '2222222', sysdate, 'admin', sysdate);
INSERT INTO "RSK_ISUP_INDICATOR_PARA_DTL"("PARA_CODE", "PARA_GRANULARITY", "PARA_DISPLAY_TYPE", "CONTENT", "REDIS_FIELD", "IS_FRESH_CAN_TRD", "CREATE_USER", "CREATE_DEPT", "CREATE_TIME", "UPDATE_USER", "UPDATE_TIME") VALUES ('ZCSYQX', '03', 'SQL', 'select 1 from dual', 'assetCode', 'N', 'admin', '2222222', sysdate, 'admin', sysdate);
INSERT INTO "RSK_ISUP_INDICATOR_PARA_DTL"("PARA_CODE", "PARA_GRANULARITY", "PARA_DISPLAY_TYPE", "CONTENT", "REDIS_FIELD", "IS_FRESH_CAN_TRD", "CREATE_USER", "CREATE_DEPT", "CREATE_TIME", "UPDATE_USER", "UPDATE_TIME") VALUES ('ZCSYQX', '01', 'SQL', 'select 1 from dual', 'assetCode', 'N', 'admin', '2222222', sysdate, 'admin', sysdate);
INSERT INTO "RSK_ISUP_INDICATOR_PARA_DTL"("PARA_CODE", "PARA_GRANULARITY", "PARA_DISPLAY_TYPE", "CONTENT", "REDIS_FIELD", "IS_FRESH_CAN_TRD", "CREATE_USER", "CREATE_DEPT", "CREATE_TIME", "UPDATE_USER", "UPDATE_TIME") VALUES ('ZCSYQX', '04', 'SQL', 'SELECT (nvl(sum((TRADE_AMT)*(LAST_PERIOD)),0)) AS lastPeriod FROM (			
  select 			
	DISTINCT A1.FINPROD_ID,A1.TRADE_AMT ,		
	CASE WHEN A1.FINPROD_TYPE =''F01'' THEN 		
	(		
	 	select CASE WHEN nvl(sum(B1.LAST_PERIOD),0)=0 THEN (((A1.mdate)-(date''${valDate}''))) ELSE (nvl(sum(B1.LAST_PERIOD),0))*365 END LAST_PERIOD from  MST_BOND_VALUATION_INFO B1	
	    inner join		
	    (select to_char(max(VALUE_DATE),''yyyy-MM-dd'') as VALUE_DATE,SEC_ID from MST_BOND_VALUATION_INFO where VALUE_DATE<=date''${valDate}'' group by sec_id) B2		
	    on B1.SEC_ID=B2.SEC_ID and B1.VALUE_DATE=B2.VALUE_DATE WHERE B1.SEC_ID=A1.FINPROD_ID		
	)		
	WHEN (A1.FINPROD_TYPE =''F06'' OR A1.FINPROD_TYPE =''XJ'') THEN (1)		
	WHEN a1.FINPROD_ID =a1.PORTFOLIO_ID		
	THEN (1)		
    ELSE (((A1.mdate)-(date''${valDate}''))) END LAST_PERIOD			
	from		
	(		
select NULL AS FINPROD_ID,NULL AS PORTFOLIO_ID,nvl(sum(AMOUNT),0) as  TRADE_AMT,''XJ'' AS FINPROD_TYPE,NULL AS MDATE   from PTL_CASH_POSITION			
 	 where  PORTFOLIO_ID in ${portfolioCode} and HODING_TYPE=''03'' and CDATE =date''${valDate}''		
    UNION ALL			
		select	
		t1.FINPROD_ID,t1.PORTFOLIO_ID,( nvl(t1.TDY_FLOAT_INGPL, 0) + nvl(t1.DSC_COST_AMT, 0)+ nvl(t1.TDY_INTINCEXP, 0)+ nvl(t1.DELAY_PAY_AMT, 0)) as TRADE_AMT,t2.FINPROD_TYPE,t2.MDATE	
		from PTL_SEC_VALUTION t1	
		inner join FIN_PRODUCT t2	on t1.FINPROD_ID = t2.FINPROD_ID
		where t1.PORTFOLIO_ID in ${portfolioCode} and  t1.CDATE = date''${valDate}''-1 	
		UNION ALL	
		select	
		t1.FINPROD_ID,t1.PORTFOLIO_ID,( nvl(t1.TDY_FLOAT_INGPL, 0) + nvl(t1.DSC_COST_AMT, 0)+ nvl(t1.TDY_INTINCEXP, 0)+ nvl(t1.DELAY_PAY_AMT, 0)) as TRADE_AMT,t3.FINPROD_TYPE,t3.MDATE	
		from PTL_SEC_VALUTION t1	
		inner join FIN_TRADE_PRODUCT t3	 on t1.FINPROD_ID = t3.FINPROD_ID 
		where t1.PORTFOLIO_ID in ${portfolioCode} and  t1.CDATE = date''${valDate}''-1 	
		and  t3.FINPROD_TYPE not in (''F02'', ''F08'', ''F25'')	
			
		UNION ALL	
			
		select n.FINPROD_ID ,n1.PORTFOLIO_ID,	
		 nvl(sum(decode(n.PS,''T01'',n.TRADE_AMT)),0)	
	  	 +nvl(sum(decode(n.PS,''T07'',n.TRADE_AMT)),0)	
   		 +nvl(sum(decode(n.PS,''T17'',n.TRADE_AMT)),0)	
		  +nvl(sum(decode(n.PS,''T04'',n.TRADE_AMT)),0)	
	  	  +nvl(sum(decode(n.PS,''T36'',n.TRADE_AMT)),0)	
		  -nvl(sum(decode(n.PS,''T03'',n.TRADE_AMT)),0)	
		  -nvl(sum(decode(n.PS,''T12'',n.TRADE_AMT)),0)	
	  	  -nvl(sum(decode(n.PS,''T09'',n.TRADE_AMT)),0)	
  		  -nvl(sum(decode(n.PS,''T19'',n.TRADE_AMT)),0)	
		  -nvl(sum(decode(n.PS,''T02'',n.TRADE_AMT)),0)	
		  -nvl(sum(decode(n.PS,''T13'',n.TRADE_AMT)),0)	
	  	  -nvl(sum(decode(n.PS,''T14'',n.TRADE_AMT)),0)	
  		  -nvl(sum(decode(n.PS,''T20'',n.TRADE_AMT)),0)	
		  -nvl(sum(decode(n.PS,''T05'',n.TRADE_AMT)),0) as  TRADE_AMT,n.FINPROD_TYPE,t2.MDATE	
		  from TRD_PRODUCT_DEAL n
		  LEFT JOIN TRD_PRODUCT_DEAL_ADD n1 ON n1.TRADE_ID=n.TRADE_ID
		  left join FIN_PRODUCT t2  on n.FINPROD_ID = t2.FINPROD_ID	
		  left join FIN_TRADE_PRODUCT t3 on n.FINPROD_ID = t3.FINPROD_ID	
		  where n1.PORTFOLIO_ID in ${portfolioCode} and  n.TRADE_DATE = date''${valDate}''	
		  and ((t3.FINPROD_TYPE is null and t2.FINPROD_TYPE is not null) or t3.FINPROD_TYPE not in (''F02'', ''F08'', ''F25''))	
		  and n.PS in (''T01'',''T07'',''T17'',''T02'',''T03'',''T12'',''T04'',''T05'',''T13'',''T09'',''T19'',''T36'',''T14'',''T20'') group by n1.PORTFOLIO_ID,n.FINPROD_ID,t2.MDATE,n.FINPROD_TYPE	
	) A1 		
)', 'assetCode', 'N', 'admin', '2222222', sysdate, 'admin', sysdate);
INSERT INTO "RSK_ISUP_INDICATOR_PARA_DTL"("PARA_CODE", "PARA_GRANULARITY", "PARA_DISPLAY_TYPE", "CONTENT", "REDIS_FIELD", "IS_FRESH_CAN_TRD", "CREATE_USER", "CREATE_DEPT", "CREATE_TIME", "UPDATE_USER", "UPDATE_TIME") VALUES ('ZCSYQX', '02', 'SQL', 'select 1 from dual', 'assetCode', 'N', 'admin', '2222222', sysdate, 'admin', sysdate);
INSERT INTO "RSK_ISUP_INDICATOR_PARA_DTL"("PARA_CODE", "PARA_GRANULARITY", "PARA_DISPLAY_TYPE", "CONTENT", "REDIS_FIELD", "IS_FRESH_CAN_TRD", "CREATE_USER", "CREATE_DEPT", "CREATE_TIME", "UPDATE_USER", "UPDATE_TIME") VALUES ('FBZCJE', '04', 'SQL', 'select sum(TRADE_AMT) as tradeAmt from			
(			
select nvl(sum(nvl(m.TDY_FLOAT_INGPL, 0) + nvl(m.DSC_COST_AMT, 0)+ nvl(m.TDY_INTINCEXP, 0)+ nvl(m.DELAY_PAY_AMT, 0)),0) as  TRADE_AMT from PTL_SEC_VALUTION m			
   inner join FIN_PRODUCT_TYPE fpt on m.FINPROD_ID=fpt.FINPROD_ID and (fpt.TYPE_6 =''''06'''' or  (fpt.TYPE_6 =''''05'''' and fpt.TYPE_7 in (''''02'''',''''05'''')))			
  where m.PORTFOLIO_ID in ${portfolioCode}  and  m.CDATE =date''''${valDate}''''-1 			
union ALL			
  select			
  nvl(sum(decode(n.PS,''''T01'''',n.TRADE_AMT)),0)			
  -nvl(sum(decode(n.PS,''''T02'''',n.TRADE_AMT)),0)			
  -nvl(sum(decode(n.PS,''''T12'''',n.TRADE_AMT)),0)			
  -nvl(sum(decode(n.PS,''''T14'''',n.TRADE_AMT)),0)			
  -nvl(sum(decode(n.PS,''''T20'''',n.TRADE_AMT)),0)			
  -nvl(sum(decode(n.PS,''''T13'''',n.TRADE_AMT)),0) as  TRADE_AMT  from TRD_PRODUCT_DEAL n 			
  inner join FIN_PRODUCT_TYPE fpt on n.FINPROD_ID=fpt.FINPROD_ID and (fpt.TYPE_6 =''''06'''' or  (fpt.TYPE_6 =''''05'''' and fpt.TYPE_7 in (''''02'''',''''05'''')))	
    LEFT JOIN TRD_PRODUCT_DEAL_ADD n1 ON n.TRADE_ID =n1.TRADE_ID 
  where n1.PORTFOLIO_ID in ${portfolioCode} and n.TRADE_DATE=date''''${valDate}'''' and n.PS in (''''T01'''',''''T02'''',''''T12'''',''''T13'''',''''T14'''',''''T20'''')			
)', 'portfolioCode', 'N', 'whmcp', '2222222', sysdate, 'whmcp', sysdate);
INSERT INTO "RSK_ISUP_INDICATOR_PARA_DTL"("PARA_CODE", "PARA_GRANULARITY", "PARA_DISPLAY_TYPE", "CONTENT", "REDIS_FIELD", "IS_FRESH_CAN_TRD", "CREATE_USER", "CREATE_DEPT", "CREATE_TIME", "UPDATE_USER", "UPDATE_TIME") VALUES ('GZQSZHZZQTZJJSZ', '03', 'SQL', 'SELECT S1.RVALUE,S1.RKEY FROM (					
	SELECT RVALUE*RVALUE2/100 AS RVALUE,RKEY FROM (				
		SELECT nvl(sum(t2.ISSUE_AMT),0) AS RVALUE,			
		(SELECT nvl(sum(s.PRICE),100) FROM MST_BOND_VALUATION_INFO s WHERE s.SEC_ID=t2.FINPROD_ID AND s.VALUE_DATE=(			
					SELECT max(VALUE_DATE) FROM MST_BOND_VALUATION_INFO m WHERE m.SEC_ID=t2.FINPROD_ID and m.VALUE_DATE<=date''${valDate}'')
			) AS RVALUE2,		
		T2.FINPROD_ID RKEY FROM  FIN_PRODUCT t2  			
		WHERE T2.FINPROD_TYPE =''F01''  GROUP BY T2.FINPROD_ID 			
	)				
					
UNION ALL					
	SELECT RVALUE,RKEY FROM (				
		SELECT			
		(SELECT nvl(sum(s.CLOSE_PRICE),0) FROM MST_FUND_MARKET_INFO s WHERE s.FUND_CODE=t2.FINPROD_MARKET_ID AND s.VALUE_DATE=(SELECT max(VALUE_DATE) 			
		FROM MST_FUND_MARKET_INFO m WHERE m.FUND_CODE=t2.FINPROD_MARKET_ID and m.VALUE_DATE<=date''${valDate}'')			
		) AS RVALUE,			
		T2.FINPROD_ID RKEY FROM FIN_PRODUCT t2  			
		WHERE  T2.FINPROD_TYPE =''F06'' GROUP BY T2.FINPROD_ID,T2.FINPROD_MARKET_ID			
	)				
) S1', 'assetCode', 'N', 'jjpei', '2222222', sysdate, 'jjpei', sysdate);
INSERT INTO "RSK_ISUP_INDICATOR_PARA_DTL"("PARA_CODE", "PARA_GRANULARITY", "PARA_DISPLAY_TYPE", "CONTENT", "REDIS_FIELD", "IS_FRESH_CAN_TRD", "CREATE_USER", "CREATE_DEPT", "CREATE_TIME", "UPDATE_USER", "UPDATE_TIME") VALUES ('TZSYQXSNYNDZQZC', '02', 'SQL', 'SELECT B1.PORTFOLIO_ID AS RKEY,sum(B1.TRADE_AMT) AS RVALUE FROM (				

	  select 			

	    A1.PORTFOLIO_ID,			

		SUM(A1.TRADE_AMT) TRADE_AMT,		

		CASE WHEN A1.FINPROD_TYPE =''F01'' THEN 		

		(		

		 	select B1.LAST_PERIOD from  MST_BOND_VALUATION_INFO B1	

		    inner join		

		    (select to_char(max(VALUE_DATE),''yyyy-MM-dd'') as VALUE_DATE,SEC_ID from MST_BOND_VALUATION_INFO where VALUE_DATE<=date''${valDate}'' group by sec_id) B2		

		    on B1.SEC_ID=B2.SEC_ID and B1.VALUE_DATE=B2.VALUE_DATE WHERE B1.SEC_ID=A1.FINPROD_ID		

		)		

	    ELSE (((A1.mdate)-(date''${valDate}''))) END LAST_PERIOD			

		from		

		(		

			select	

			t1.PORTFOLIO_ID,t1.FINPROD_ID,( nvl(t1.TDY_FLOAT_INGPL, 0) + nvl(t1.DSC_COST_AMT, 0)+ nvl(t1.TDY_INTINCEXP, 0)+ nvl(t1.DELAY_PAY_AMT, 0)) as TRADE_AMT,t2.FINPROD_TYPE,t2.MDATE	

			from PTL_SEC_VALUTION t1	

			 INNER  join FIN_PRODUCT t2 on t1.FINPROD_ID = t2.FINPROD_ID AND t2.FINPROD_TYPE =''F01''	

			where   t1.CDATE = date''${valDate}''-1  	

				

		) A1 GROUP BY A1.PORTFOLIO_ID,A1.FINPROD_ID,A1.FINPROD_TYPE,A1.MDATE		

	) B1 WHERE B1.LAST_PERIOD<=3	 GROUP BY B1.PORTFOLIO_ID', 'portfolioCode', 'N', 'jjpei', 'jsadjflsajfsdkl', sysdate, 'jjpei', sysdate);





