-------指标参数明细超限字段
declare
    content1 clob;
	content2 clob;
    content3 clob;
	content4 clob;
    content5 clob;

begin
  content1 := 'WITH t2 AS 							
	  ( 							
	  SELECT FINPROD_ID,MDATE,CALENDAR_ID,CDATE,FINPROD_TYPE FROM (	 						
	  SELECT s1.FINPROD_ID,s1.MDATE,s1.CALENDAR_ID,s1.CDATE,s1.FINPROD_TYPE,ROW_NUMBER() OVER(PARTITION BY s1.FINPROD_ID ORDER BY s1.CDATE asc) AS rn FROM (							
					SELECT s.FINPROD_ID,s.MDATE,s.CALENDAR_ID,s.CDATE,s.FINPROD_TYPE,rownum FROM (				
					SELECT m.FINPROD_ID,m.MDATE,m.FINPROD_TYPE,m.CALENDAR_ID,n.CDATE,ROW_NUMBER() OVER(PARTITION BY m.FINPROD_ID ORDER BY n.CDATE desc) AS  rownum1 FROM (				
				  SELECT FINPROD_ID,FINPROD_TYPE,MDATE,CASE WHEN CALENDAR_ID IS NULL THEN ''01'' ELSE CALENDAR_ID end CALENDAR_ID FROM FIN_PRODUCT WHERE MDATE IS NOT null) m 				
				  INNER JOIN MST_HOLIDAY n ON  m.CALENDAR_ID=n.CALENDAR_ID  AND n.CDATE<=m.MDATE AND n.IS_HOLIDAY=0 ) s WHERE s.rownum1<=10 				
			  ) s1  					
		  )  WHERE rn=1						
	  ),t3 AS 							
	   (							
		   SELECT FINPROD_ID,MDATE,CALENDAR_ID,CDATE,FINPROD_TYPE FROM (	 					
		  SELECT s1.FINPROD_ID,s1.MDATE,s1.CALENDAR_ID,s1.CDATE,s1.FINPROD_TYPE,ROW_NUMBER() OVER(PARTITION BY s1.FINPROD_ID ORDER BY s1.CDATE asc) AS rn FROM (						
						SELECT s.FINPROD_ID,s.MDATE,s.CALENDAR_ID,s.CDATE,s.FINPROD_TYPE,s.rownum1 FROM (			
						SELECT m.FINPROD_ID,m.MDATE,m.FINPROD_TYPE,m.CALENDAR_ID,n.CDATE,ROW_NUMBER() OVER(PARTITION BY m.FINPROD_ID ORDER BY n.CDATE desc) AS rownum1 FROM (			
					  SELECT FINPROD_ID,FINPROD_TYPE,MDATE,CASE WHEN CALENDAR_ID IS NULL THEN ''01'' ELSE CALENDAR_ID end CALENDAR_ID FROM FIN_TRADE_PRODUCT WHERE FINPROD_TYPE not in (''F02'', ''F08'', ''F25'') and MDATE IS NOT null) m 			
					  INNER JOIN MST_HOLIDAY n ON  m.CALENDAR_ID=n.CALENDAR_ID  AND n.CDATE<=m.MDATE AND n.IS_HOLIDAY=0 ) s WHERE s.rownum1<=10 			
				  ) s1  				
		  )  WHERE rn=1						
	  )						
	  SELECT (ROUND(sum(RVALUE),6)) RVALUE FROM (							
	   select nvl(sum(nvl(t1.TDY_FLOAT_INGPL, 0) + nvl(t1.DSC_COST_AMT, 0)+ nvl(t1.TDY_INTINCEXP, 0)+ nvl(t1.DELAY_PAY_AMT, 0)),0) as  RVALUE from PTL_SEC_VALUTION t1							
	  inner join  t2							
	  on t1.FINPROD_ID = t2.FINPROD_ID and t2.MDATE>=date''${valDate}''-1  and t2.CDATE<=date''${valDate}''-1 							
	  where t1.PORTFOLIO_ID!=t1.FINPROD_ID AND t1.PORTFOLIO_ID in ${portfolioCode} and t1.CDATE=date''${valDate}''-1   															
	  UNION ALL							
	   select nvl(sum(nvl(t1.TDY_FLOAT_INGPL, 0) + nvl(t1.DSC_COST_AMT, 0)+ nvl(t1.TDY_INTINCEXP, 0)+ nvl(t1.DELAY_PAY_AMT, 0)),0) as  RVALUE from PTL_SEC_VALUTION t1							
	  inner join  t3							
	  on t1.FINPROD_ID = t3.FINPROD_ID and t3.MDATE>=date''${valDate}''-1  and t3.CDATE<=date''${valDate}''-1 							
	  where t1.PORTFOLIO_ID!=t1.FINPROD_ID AND t1.PORTFOLIO_ID in ${portfolioCode} and t1.CDATE=date''${valDate}''-1   														
	 union all							
	 select							
	   nvl(sum(decode(n.PS,''T01'',n.TRADE_AMT)),0)							
	  +nvl(sum(decode(n.PS,''T04'',n.TRADE_AMT)),0)							
	  +nvl(sum(decode(n.PS,''T36'',n.TRADE_AMT)),0)							
	  -nvl(sum(decode(n.PS,''T03'',n.TRADE_AMT)),0)							
	  -nvl(sum(decode(n.PS,''T12'',n.TRADE_AMT)),0)							
	  -nvl(sum(decode(n.PS,''T02'',n.TRADE_AMT)),0)							
	  -nvl(sum(decode(n.PS,''T13'',n.TRADE_AMT)),0)							
	  -nvl(sum(decode(n.PS,''T14'',n.TRADE_AMT)),0)							
	  -nvl(sum(decode(n.PS,''T20'',n.TRADE_AMT)),0)							
	  -nvl(sum(decode(n.PS,''T05'',n.TRADE_AMT)),0) as  TRADE_AMT							
	  from TRD_PRODUCT_DEAL n  	
	  INNER JOIN TRD_PRODUCT_DEAL_ADD n1 ON n1.trade_id =n.TRADE_ID 
	  inner join  t2   on n.FINPROD_ID = t2.FINPROD_ID and t2.MDATE>=date''${valDate}'' and t2.CDATE<=date''${valDate}''							
	  where n1.PORTFOLIO_ID in ${portfolioCode} and  n.TRADE_DATE = date''${valDate}''							
	  and n.PS in (''T01'',''T02'',''T03'',''T12'',''T04'',''T05'',''T13'',''T36'',''T14'',''T20'') 															
	  union all							
	 select							
	   nvl(sum(decode(n.PS,''T06'',n.TRADE_AMT)),0)							
	   +nvl(sum(decode(n.PS,''T07'',n.TRADE_AMT)),0)							
	   +nvl(sum(decode(n.PS,''T16'',n.TRADE_AMT)),0)							
	   +nvl(sum(decode(n.PS,''T17'',n.TRADE_AMT)),0)							
	   +nvl(sum(decode(n.PS,''T04'',n.TRADE_AMT)),0)							
	   +nvl(sum(decode(n.PS,''T36'',n.TRADE_AMT)),0)							
	   -nvl(sum(decode(n.PS,''T03'',n.TRADE_AMT)),0)							
	   -nvl(sum(decode(n.PS,''T12'',n.TRADE_AMT)),0)							
	   -nvl(sum(decode(n.PS,''T02'',n.TRADE_AMT)),0)							
	   -nvl(sum(decode(n.PS,''T08'',n.TRADE_AMT)),0)							
	   -nvl(sum(decode(n.PS,''T18'',n.TRADE_AMT)),0)							
	   -nvl(sum(decode(n.PS,''T09'',n.TRADE_AMT)),0)							
	   -nvl(sum(decode(n.PS,''T19'',n.TRADE_AMT)),0)							
	   -nvl(sum(decode(n.PS,''T13'',n.TRADE_AMT)),0)							
	   -nvl(sum(decode(n.PS,''T14'',n.TRADE_AMT)),0)							
	   -nvl(sum(decode(n.PS,''T20'',n.TRADE_AMT)),0)							
	   -nvl(sum(decode(n.PS,''T05'',n.TRADE_AMT)),0) as  TRADE_AMT							
	  from TRD_PRODUCT_DEAL n  
		INNER JOIN TRD_PRODUCT_DEAL_ADD n1 ON n1.trade_id =n.TRADE_ID 
	  inner join  t3  on n.FINPROD_ID = t3.FINPROD_ID and t3.MDATE>=date''${valDate}'' and t3.CDATE<=date''${valDate}''							
	  where n1.PORTFOLIO_ID in ${portfolioCode} and  n.TRADE_DATE = date''${valDate}''							
	  and n.PS in (''T01'',''T02'',''T03'',''T12'',''T04'',''T05'',''T06'',''T07'',''T13'',''T08'',''T09'',''T18'',''T19'',''T36'',''T14'',''T20'') 							
	  )';

	content2 :='select sum(TRADE_AMT) as tradeAmt from						
	(						
	  select nvl(sum(AMOUNT),0) as  TRADE_AMT from PTL_CASH_POSITION						
	  where  PORTFOLIO_ID in ${portfolioCode} and HODING_TYPE=''03'' and CDATE =date''${valDate}''						
	union ALL						
	  select nvl(sum(nvl(m.TDY_FLOAT_INGPL, 0) + nvl(m.DSC_COST_AMT, 0)+ nvl(m.TDY_INTINCEXP, 0)+ nvl(m.DELAY_PAY_AMT, 0)),0) as  TRADE_AMT from PTL_SEC_VALUTION m						
	 inner join FIN_PRODUCT t2 on m.FINPROD_ID = t2.FINPROD_ID 	AND t2.FINPROD_TYPE not in (''F01'',''F06'')					
		where m.PORTFOLIO_ID in ${portfolioCode} and  m.CDATE = date''${valDate}''-1  AND m.PORTFOLIO_ID!=m.FINPROD_ID	 and t2.MDATE>=date''${valDate}'' and t2.MDATE<=date''${valDate}''+90 						
	union ALL						
	  select nvl(sum(nvl(m.TDY_FLOAT_INGPL, 0) + nvl(m.DSC_COST_AMT, 0)+ nvl(m.TDY_INTINCEXP, 0)+ nvl(m.DELAY_PAY_AMT, 0)),0) as  TRADE_AMT from PTL_SEC_VALUTION m						
	   inner join FIN_TRADE_PRODUCT t3 on m.FINPROD_ID = t3.FINPROD_ID 	AND t3.FINPROD_TYPE not in (''F02'', ''F08'', ''F25'')					
		where m.PORTFOLIO_ID in ${portfolioCode} and  m.CDATE = date''${valDate}''-1  AND m.PORTFOLIO_ID!=m.FINPROD_ID	 and t3.MDATE>=date''${valDate}'' and t3.MDATE<=date''${valDate}''+90 				
	union ALL						
	  select						
	 nvl(sum(decode(n.PS,''T01'',n.TRADE_AMT)),0)						

	  +nvl(sum(decode(n.PS,''T04'',n.TRADE_AMT)),0)						

	  +nvl(sum(decode(n.PS,''T36'',n.TRADE_AMT)),0)						

	  -nvl(sum(decode(n.PS,''T03'',n.TRADE_AMT)),0)						

	  -nvl(sum(decode(n.PS,''T12'',n.TRADE_AMT)),0)						

	  -nvl(sum(decode(n.PS,''T02'',n.TRADE_AMT)),0)						

	  -nvl(sum(decode(n.PS,''T13'',n.TRADE_AMT)),0)						

	  -nvl(sum(decode(n.PS,''T14'',n.TRADE_AMT)),0)						

	  -nvl(sum(decode(n.PS,''T20'',n.TRADE_AMT)),0)						

	  -nvl(sum(decode(n.PS,''T05'',n.TRADE_AMT)),0) as  TRADE_AMT						

	  from TRD_PRODUCT_DEAL n

				  INNER JOIN TRD_PRODUCT_DEAL_ADD n1 ON n1.trade_id =n.TRADE_ID 

		inner join FIN_PRODUCT t2  on n.FINPROD_ID = t2.FINPROD_ID	AND t2.FINPROD_TYPE not in (''F01'',''F06'')					

	  where  n1.PORTFOLIO_ID in ${portfolioCode} and n.TRADE_DATE=date''${valDate}'' and t2.MDATE>=date''${valDate}'' and t2.MDATE<=date''${valDate}''+90 						

		and n.PS in (''T01'',''T02'',''T03'',''T12'',''T04'',''T13'',''T05'',''T36'',''T14'',''T20'')						

		



	  union ALL						

	  select						

	nvl(sum(decode(n.PS,''T07'',n.TRADE_AMT)),0)						

	+nvl(sum(decode(n.PS,''T17'',n.TRADE_AMT)),0)						

	  +nvl(sum(decode(n.PS,''T04'',n.TRADE_AMT)),0)						

	  +nvl(sum(decode(n.PS,''T36'',n.TRADE_AMT)),0)						

	  -nvl(sum(decode(n.PS,''T03'',n.TRADE_AMT)),0)						

	  -nvl(sum(decode(n.PS,''T12'',n.TRADE_AMT)),0)						

	  -nvl(sum(decode(n.PS,''T02'',n.TRADE_AMT)),0)						

	  -nvl(sum(decode(n.PS,''T13'',n.TRADE_AMT)),0)						

	  -nvl(sum(decode(n.PS,''T14'',n.TRADE_AMT)),0)						

	  -nvl(sum(decode(n.PS,''T20'',n.TRADE_AMT)),0)						

	  -nvl(sum(decode(n.PS,''T09'',n.TRADE_AMT)),0)						

	  -nvl(sum(decode(n.PS,''T19'',n.TRADE_AMT)),0)						

	  -nvl(sum(decode(n.PS,''T05'',n.TRADE_AMT)),0)  as  TRADE_AMT						

	  from TRD_PRODUCT_DEAL n 

	   INNER JOIN TRD_PRODUCT_DEAL_ADD n1 ON n1.trade_id =n.TRADE_ID 

	  inner join FIN_TRADE_PRODUCT t3 on n.FINPROD_ID = t3.FINPROD_ID AND t3.FINPROD_TYPE not in (''F02'', ''F08'', ''F25'')						

	  where  n1.PORTFOLIO_ID in ${portfolioCode} and n.TRADE_DATE=date''${valDate}'' and t3.MDATE>=date''${valDate}'' and t3.MDATE<=date''${valDate}''+90 						

		and n.PS in (''T12'',''T17'',''T02'',''T03'',''T04'',''T05'',''T07'',''T13'',''T09'',''T19'',''T36'',''T14'',''T20'')						

								

	  UNION ALL						

		  select 					

			SUM(A1.TRADE_AMT) TRADE_AMT				

			from				

			(				

				select			

				t1.FINPROD_ID,( nvl(t1.TDY_FLOAT_INGPL, 0) + nvl(t1.DSC_COST_AMT, 0)+ nvl(t1.TDY_INTINCEXP, 0)+ nvl(t1.DELAY_PAY_AMT, 0)) as TRADE_AMT,t2.FINPROD_TYPE,t2.MDATE			

				from PTL_SEC_VALUTION t1			

				 INNER  join FIN_PRODUCT t2	on t1.FINPROD_ID = t2.FINPROD_ID AND t2.FINPROD_TYPE IN (''F01'',''F06'')		

				where t1.PORTFOLIO_ID in ${portfolioCode} and  t1.CDATE = date''${valDate}''-1 	AND t1.PORTFOLIO_ID!=t1.FINPROD_ID		

				UNION ALL			

					select		

					n.FINPROD_ID ,		

					 nvl(sum(decode(n.PS,''T01'',n.TRADE_AMT)),0)		

					  +nvl(sum(decode(n.PS,''T04'',n.TRADE_AMT)),0)		

					  +nvl(sum(decode(n.PS,''T36'',n.TRADE_AMT)),0)		

					  -nvl(sum(decode(n.PS,''T03'',n.TRADE_AMT)),0)		

					  -nvl(sum(decode(n.PS,''T12'',n.TRADE_AMT)),0)		

					  -nvl(sum(decode(n.PS,''T02'',n.TRADE_AMT)),0)		

					  -nvl(sum(decode(n.PS,''T13'',n.TRADE_AMT)),0)		

					  -nvl(sum(decode(n.PS,''T14'',n.TRADE_AMT)),0)			

					  -nvl(sum(decode(n.PS,''T20'',n.TRADE_AMT)),0)		

					  -nvl(sum(decode(n.PS,''T05'',n.TRADE_AMT)),0) as  TRADE_AMT	,	

				  n.FINPROD_TYPE,t2.MDATE			

				  from TRD_PRODUCT_DEAL n 

				  INNER JOIN TRD_PRODUCT_DEAL_ADD n1 ON n1.trade_id =n.TRADE_ID 

				  inner join FIN_PRODUCT t2  on n.FINPROD_ID = t2.FINPROD_ID  AND t2.FINPROD_TYPE IN (''F01'',''F06'')			

				  where n1.PORTFOLIO_ID in ${portfolioCode} and  n.TRADE_DATE = date''${valDate}''			

				  and n.PS in (''T01'',''T02'',''T03'',''T12'',''T04'',''T13'',''T05'',''T36'',''T14'',''T20'') group by n.FINPROD_ID,t2.MDATE,n.FINPROD_TYPE			

			) A1 GROUP BY A1.FINPROD_ID,A1.FINPROD_TYPE,A1.MDATE			 	

							

	)';
	content3 :='SELECT
	nvl(SUM(nvl(PTL_SEC_VALUTION1.DSC_COST_AMT, 0)),0) AS CST,
	nvl(SUM(nvl(PTL_SEC_VALUTION1.SHARE_AMT, 0)),0) AS QTY,
	nvl(SUM(nvl(PTL_SEC_VALUTION1.TDY_FLOAT_INGPL, 0) + nvl(PTL_SEC_VALUTION1.DSC_COST_AMT, 0)+nvl(PTL_SEC_VALUTION1.TDY_INTINCEXP, 0)+nvl(PTL_SEC_VALUTION1.DELAY_PAY_AMT, 0)),0) AS MKT,
	FIN_PRODUCT_TYPE1.TYPE_4 windAssetType,
	FIN_PRODUCT_TYPE1.TYPE_5 windAssetType2,
	FIN_PRODUCT_TYPE1.TYPE_6 assetType,
	FIN_PRODUCT_TYPE1.TYPE_7 assetType2,
	FIN_PRODUCT_ADD1.INVEST_NATURE investNature,
	REP_ASSET_DEPT1.REP_ASSET_TYPE deptType,
	REP_ASSET_DEPT1.REP_ASSET_TYPE deptType2,
	PTL_SEC_VALUTION1.FINPROD_ID finprodId,
	FIN_PRODUCT1.ISSUER issuer,
	MST_CUSTOMER_INFO1.INDUSTRY industry,
	MST_CUSTOMER_INFO1.INDUSTRY2 industry2,
	ZXRATING1.GRADE_RESULT bondGradeType,
	ZTRATING1.GRADE_RESULT bodyGradeType,
	PTL_SEC_VALUTION1.PORTFOLIO_ID portfolioId,
	FIN_PRODUCT1.MDATE mdate
	FROM PTL_SEC_VALUTION PTL_SEC_VALUTION1
	LEFT JOIN FIN_PRODUCT FIN_PRODUCT1 ON PTL_SEC_VALUTION1.FINPROD_ID = FIN_PRODUCT1.FINPROD_ID
	LEFT JOIN (SELECT s1.*,s2.INDUSTRY,s2.INDUSTRY2 FROM MST_CUSTOMER_INFO s1 INNER JOIN MST_CUSTOMER_INFO_ADD s2 ON s1.CUSTOMER_ID=s2.CUSTOMER_ID)  MST_CUSTOMER_INFO1 ON FIN_PRODUCT1.ISSUER = MST_CUSTOMER_INFO1.CUSTOMER_ID
	LEFT JOIN FIN_PRODUCT_TYPE FIN_PRODUCT_TYPE1 ON PTL_SEC_VALUTION1.FINPROD_ID = FIN_PRODUCT_TYPE1.FINPROD_ID
	LEFT JOIN FIN_PRODUCT_ADD FIN_PRODUCT_ADD1 ON FIN_PRODUCT_ADD1.FINPROD_ID = PTL_SEC_VALUTION1.FINPROD_ID
	LEFT JOIN REP_ASSET_DEPT REP_ASSET_DEPT1 ON PTL_SEC_VALUTION1.FINPROD_ID = REP_ASSET_DEPT1.REP_FINPROD_ID
	LEFT JOIN (SELECT * FROM (SELECT O_CODE,GRADE_RESULT,ROW_NUMBER() OVER(PARTITION BY O_CODE ORDER BY CREATE_TIME desc) AS rn FROM MST_BOND_CREDIT_RATING T WHERE O_TYPE = ''02'' AND GRADE_DATE<=DATE ''${valDate}'') where rn=1 ) ZXRATING1 ON ZXRATING1.O_CODE = PTL_SEC_VALUTION1.FINPROD_ID
	LEFT JOIN (SELECT * FROM (SELECT O_CODE,GRADE_DATE,GRADE_RESULT,ROW_NUMBER() OVER(PARTITION BY O_CODE ORDER BY CREATE_TIME desc) AS rn FROM MST_BOND_CREDIT_RATING T WHERE O_TYPE = ''01'' AND GRADE_DATE<=DATE ''${valDate}'') where rn=1 ) ZTRATING1 ON ZTRATING1.O_CODE = PTL_SEC_VALUTION1.FINPROD_ID
	WHERE PTL_SEC_VALUTION1.CDATE = DATE ''${valDate}''-1 
	GROUP BY
	PTL_SEC_VALUTION1.PORTFOLIO_ID,FIN_PRODUCT_TYPE1.TYPE_4,FIN_PRODUCT_TYPE1.TYPE_5,FIN_PRODUCT_TYPE1.TYPE_6,FIN_PRODUCT_TYPE1.TYPE_7,FIN_PRODUCT_ADD1.INVEST_NATURE, REP_ASSET_DEPT1.REP_ASSET_TYPE,
	PTL_SEC_VALUTION1.FINPROD_ID,FIN_PRODUCT1.ISSUER,MST_CUSTOMER_INFO1.INDUSTRY,MST_CUSTOMER_INFO1.INDUSTRY2,ZXRATING1.GRADE_RESULT,ZTRATING1.GRADE_RESULT,FIN_PRODUCT1.MDATE
	  union all
	SELECT
	nvl(SUM(nvl(PTL_SEC_VALUTION2.DSC_COST_AMT, 0)),0) AS CST,
	nvl(SUM(nvl(PTL_SEC_VALUTION2.SHARE_AMT, 0)),0) AS QTY,
	nvl(SUM(nvl(PTL_SEC_VALUTION2.TDY_FLOAT_INGPL, 0) + nvl(PTL_SEC_VALUTION2.DSC_COST_AMT, 0)+nvl(PTL_SEC_VALUTION2.TDY_INTINCEXP, 0)+nvl(PTL_SEC_VALUTION2.DELAY_PAY_AMT, 0)),0) AS MKT,
	FIN_PRODUCT_TYPE2.TYPE_4 windAssetType,
	FIN_PRODUCT_TYPE2.TYPE_5 windAssetType2,
	FIN_PRODUCT_TYPE2.TYPE_6 assetType,
	FIN_PRODUCT_TYPE2.TYPE_7 assetType2,
	FIN_PRODUCT_ADD2.INVEST_NATURE investNature,
	REP_ASSET_DEPT2.REP_ASSET_TYPE deptType,
	REP_ASSET_DEPT2.REP_ASSET_TYPE deptType2,
	PTL_SEC_VALUTION2.FINPROD_ID finprodId,
	FIN_PRODUCT2.ISSUER issuer,
	MST_CUSTOMER_INFO2.INDUSTRY industry,
	MST_CUSTOMER_INFO2.INDUSTRY2 industry2,
	ZXRATING2.GRADE_RESULT bondGradeType,
	ZTRATING2.GRADE_RESULT bodyGradeType,
	DTL.PTL_BAG_ID portfolioId,
	FIN_PRODUCT2.MDATE mdate
	FROM PTL_SEC_VALUTION PTL_SEC_VALUTION2
	LEFT JOIN FIN_PRODUCT FIN_PRODUCT2 ON PTL_SEC_VALUTION2.FINPROD_ID = FIN_PRODUCT2.FINPROD_ID
	LEFT JOIN (SELECT s1.*,s2.INDUSTRY,s2.INDUSTRY2 FROM MST_CUSTOMER_INFO s1 INNER JOIN MST_CUSTOMER_INFO_ADD s2 ON s1.CUSTOMER_ID=s2.CUSTOMER_ID) MST_CUSTOMER_INFO2 ON FIN_PRODUCT2.ISSUER = MST_CUSTOMER_INFO2.CUSTOMER_ID
	LEFT JOIN FIN_PRODUCT_TYPE FIN_PRODUCT_TYPE2 ON PTL_SEC_VALUTION2.FINPROD_ID = FIN_PRODUCT_TYPE2.FINPROD_ID
	LEFT JOIN FIN_PRODUCT_ADD FIN_PRODUCT_ADD2 ON FIN_PRODUCT_ADD2.FINPROD_ID = PTL_SEC_VALUTION2.FINPROD_ID
	LEFT JOIN REP_ASSET_DEPT REP_ASSET_DEPT2 ON PTL_SEC_VALUTION2.FINPROD_ID = REP_ASSET_DEPT2.REP_FINPROD_ID
	LEFT JOIN (SELECT * FROM (SELECT O_CODE,GRADE_RESULT,ROW_NUMBER() OVER(PARTITION BY O_CODE ORDER BY CREATE_TIME desc) AS rn FROM MST_BOND_CREDIT_RATING T WHERE O_TYPE = ''02'' AND GRADE_DATE<=DATE ''${valDate}'') where rn=1 ) ZXRATING2 ON ZXRATING2.O_CODE = PTL_SEC_VALUTION2.FINPROD_ID
	LEFT JOIN (SELECT * FROM (SELECT O_CODE,GRADE_DATE,GRADE_RESULT,ROW_NUMBER() OVER(PARTITION BY O_CODE ORDER BY CREATE_TIME desc) AS rn FROM MST_BOND_CREDIT_RATING T WHERE O_TYPE = ''01'' AND GRADE_DATE<=DATE ''${valDate}'') where rn=1 ) ZTRATING2 ON ZTRATING2.O_CODE = PTL_SEC_VALUTION2.FINPROD_ID
	LEFT JOIN RSK_PORTFOLIO_PACKAGE_DTL DTL ON DTL.PORTFOLIO_ID = PTL_SEC_VALUTION2.PORTFOLIO_ID
	WHERE  PTL_SEC_VALUTION2.CDATE = DATE ''${valDate}''-1 
	and PTL_SEC_VALUTION2.PORTFOLIO_ID in (select t1.PORTFOLIO_ID from RSK_PORTFOLIO_PACKAGE_DTL t1  inner join PTL_PORTFOLIO t2 on t1.PORTFOLIO_ID=t2.PORTFOLIO_ID and t2.MDATE>=date''${valDate}'')
	GROUP BY
	DTL.PTL_BAG_ID,FIN_PRODUCT_TYPE2.TYPE_4,FIN_PRODUCT_TYPE2.TYPE_5,FIN_PRODUCT_TYPE2.TYPE_6,FIN_PRODUCT_TYPE2.TYPE_7,FIN_PRODUCT_ADD2.INVEST_NATURE, REP_ASSET_DEPT2.REP_ASSET_TYPE,
	PTL_SEC_VALUTION2.FINPROD_ID,FIN_PRODUCT2.ISSUER,MST_CUSTOMER_INFO2.INDUSTRY,MST_CUSTOMER_INFO2.INDUSTRY2,ZXRATING2.GRADE_RESULT,ZTRATING2.GRADE_RESULT,FIN_PRODUCT2.MDATE';
	content4 :='SELECT
	nvl(SUM(nvl(PTL_SEC_VALUTION1.DSC_COST_AMT, 0)),0) AS CST,
	nvl(SUM(nvl(PTL_SEC_VALUTION1.SHARE_AMT, 0)),0) AS QTY,
	nvl(SUM(nvl(PTL_SEC_VALUTION1.TDY_FLOAT_INGPL, 0) + nvl(PTL_SEC_VALUTION1.DSC_COST_AMT, 0)+nvl(PTL_SEC_VALUTION1.TDY_INTINCEXP, 0)+nvl(PTL_SEC_VALUTION1.DELAY_PAY_AMT, 0)),0) AS MKT,
	FIN_PRODUCT_TYPE1.TYPE_4 windAssetType,
	FIN_PRODUCT_TYPE1.TYPE_5 windAssetType2,
	FIN_PRODUCT_TYPE1.TYPE_6 assetType,
	FIN_PRODUCT_TYPE1.TYPE_7 assetType2,
	FIN_PRODUCT_ADD1.INVEST_NATURE investNature,
	REP_ASSET_DEPT1.REP_ASSET_TYPE deptType,
	REP_ASSET_DEPT1.REP_ASSET_TYPE deptType2,
	PTL_SEC_VALUTION1.FINPROD_ID finprodId,
	FIN_PRODUCT1.ISSUER issuer,
	MST_CUSTOMER_INFO1.INDUSTRY industry,
	MST_CUSTOMER_INFO1.INDUSTRY2 industry2,
	ZXRATING1.GRADE_RESULT bondGradeType,
	ZTRATING1.GRADE_RESULT bodyGradeType,
	PTL_SEC_VALUTION1.PORTFOLIO_ID portfolioId,
	FIN_PRODUCT1.MDATE mdate
	FROM PTL_SEC_VALUTION PTL_SEC_VALUTION1
	LEFT JOIN FIN_PRODUCT FIN_PRODUCT1 ON PTL_SEC_VALUTION1.FINPROD_ID = FIN_PRODUCT1.FINPROD_ID
	LEFT JOIN (SELECT s1.*,s2.INDUSTRY,s2.INDUSTRY2 FROM MST_CUSTOMER_INFO s1 INNER JOIN MST_CUSTOMER_INFO_ADD s2 ON s1.CUSTOMER_ID=s2.CUSTOMER_ID) MST_CUSTOMER_INFO1 ON FIN_PRODUCT1.ISSUER = MST_CUSTOMER_INFO1.CUSTOMER_ID
	LEFT JOIN FIN_PRODUCT_TYPE FIN_PRODUCT_TYPE1 ON PTL_SEC_VALUTION1.FINPROD_ID = FIN_PRODUCT_TYPE1.FINPROD_ID
	LEFT JOIN FIN_PRODUCT_ADD FIN_PRODUCT_ADD1 ON FIN_PRODUCT_ADD1.FINPROD_ID = PTL_SEC_VALUTION1.FINPROD_ID
	LEFT JOIN REP_ASSET_DEPT REP_ASSET_DEPT1 ON PTL_SEC_VALUTION1.FINPROD_ID = REP_ASSET_DEPT1.REP_FINPROD_ID
	LEFT JOIN (SELECT * FROM (SELECT O_CODE,GRADE_RESULT,ROW_NUMBER() OVER(PARTITION BY O_CODE ORDER BY CREATE_TIME desc) AS rn FROM MST_BOND_CREDIT_RATING T WHERE O_TYPE = ''02'' AND GRADE_DATE<=DATE ''${valDate}'') where rn=1 ) ZXRATING1 ON ZXRATING1.O_CODE = PTL_SEC_VALUTION1.FINPROD_ID
	LEFT JOIN (SELECT * FROM (SELECT O_CODE,GRADE_DATE,GRADE_RESULT,ROW_NUMBER() OVER(PARTITION BY O_CODE ORDER BY CREATE_TIME desc) AS rn FROM MST_BOND_CREDIT_RATING T WHERE O_TYPE = ''01'' AND GRADE_DATE<=DATE ''${valDate}'') where rn=1 ) ZTRATING1 ON ZTRATING1.O_CODE = PTL_SEC_VALUTION1.FINPROD_ID
	WHERE  PTL_SEC_VALUTION1.PORTFOLIO_ID in ${portfolioCode} and PTL_SEC_VALUTION1.CDATE =date''${valDate}''-1 
	GROUP BY
	PTL_SEC_VALUTION1.PORTFOLIO_ID,FIN_PRODUCT_TYPE1.TYPE_4,FIN_PRODUCT_TYPE1.TYPE_5,FIN_PRODUCT_TYPE1.TYPE_6,FIN_PRODUCT_TYPE1.TYPE_7,FIN_PRODUCT_ADD1.INVEST_NATURE, REP_ASSET_DEPT1.REP_ASSET_TYPE,
	PTL_SEC_VALUTION1.FINPROD_ID,FIN_PRODUCT1.ISSUER,MST_CUSTOMER_INFO1.INDUSTRY,MST_CUSTOMER_INFO1.INDUSTRY2,ZXRATING1.GRADE_RESULT,ZTRATING1.GRADE_RESULT,FIN_PRODUCT1.MDATE
	  union all
	SELECT
	nvl(sum(decode(TRD_PRODUCT_DEAL.PS,''T01'',TRD_PRODUCT_DEAL.PRIN_AMT)),0)
	+nvl(sum(decode(TRD_PRODUCT_DEAL.PS,''T07'',TRD_PRODUCT_DEAL.PRIN_AMT)),0)
	+nvl(sum(decode(TRD_PRODUCT_DEAL.PS,''T17'',TRD_PRODUCT_DEAL.PRIN_AMT)),0)
	+nvl(sum(decode(TRD_PRODUCT_DEAL.PS,''T04'',TRD_PRODUCT_DEAL.PRIN_AMT)),0)
	+nvl(sum(decode(TRD_PRODUCT_DEAL.PS,''T36'',TRD_PRODUCT_DEAL.PRIN_AMT)),0)
	-nvl(sum(decode(TRD_PRODUCT_DEAL.PS,''T03'',TRD_PRODUCT_DEAL.PRIN_AMT)),0)
	-nvl(sum(decode(TRD_PRODUCT_DEAL.PS,''T12'',TRD_PRODUCT_DEAL.PRIN_AMT)),0)
	-nvl(sum(decode(TRD_PRODUCT_DEAL.PS,''T09'',TRD_PRODUCT_DEAL.PRIN_AMT)),0)
	+nvl(sum(decode(TRD_PRODUCT_DEAL.PS,''T10'',TRD_PRODUCT_DEAL.PRIN_AMT)),0)
	-nvl(sum(decode(TRD_PRODUCT_DEAL.PS,''T19'',TRD_PRODUCT_DEAL.PRIN_AMT)),0)
	-nvl(sum(decode(TRD_PRODUCT_DEAL.PS,''T02'',TRD_PRODUCT_DEAL.PRIN_AMT)),0)
	-nvl(sum(decode(TRD_PRODUCT_DEAL.PS,''T13'',TRD_PRODUCT_DEAL.PRIN_AMT)),0)
	-nvl(sum(decode(TRD_PRODUCT_DEAL.PS,''T14'',TRD_PRODUCT_DEAL.PRIN_AMT)),0)
	-nvl(sum(decode(TRD_PRODUCT_DEAL.PS,''T11'',TRD_PRODUCT_DEAL.PRIN_AMT)),0)
	-nvl(sum(decode(TRD_PRODUCT_DEAL.PS,''T05'',TRD_PRODUCT_DEAL.PRIN_AMT)),0) as  CST,
	nvl(sum(decode(TRD_PRODUCT_DEAL.PS,''T01'',TRD_PRODUCT_DEAL.TRADE_AMT)),0)
	+nvl(sum(decode(TRD_PRODUCT_DEAL.PS,''T07'',TRD_PRODUCT_DEAL.TRADE_AMT)),0)
	+nvl(sum(decode(TRD_PRODUCT_DEAL.PS,''T17'',TRD_PRODUCT_DEAL.TRADE_AMT)),0)
	+nvl(sum(decode(TRD_PRODUCT_DEAL.PS,''T04'',TRD_PRODUCT_DEAL.TRADE_AMT)),0)
	+nvl(sum(decode(TRD_PRODUCT_DEAL.PS,''T36'',TRD_PRODUCT_DEAL.TRADE_AMT)),0)
	-nvl(sum(decode(TRD_PRODUCT_DEAL.PS,''T03'',TRD_PRODUCT_DEAL.TRADE_AMT)),0)
	-nvl(sum(decode(TRD_PRODUCT_DEAL.PS,''T12'',TRD_PRODUCT_DEAL.TRADE_AMT)),0)
	-nvl(sum(decode(TRD_PRODUCT_DEAL.PS,''T09'',TRD_PRODUCT_DEAL.TRADE_AMT)),0)
	+nvl(sum(decode(TRD_PRODUCT_DEAL.PS,''T10'',TRD_PRODUCT_DEAL.TRADE_AMT)),0)
	-nvl(sum(decode(TRD_PRODUCT_DEAL.PS,''T19'',TRD_PRODUCT_DEAL.TRADE_AMT)),0)
	-nvl(sum(decode(TRD_PRODUCT_DEAL.PS,''T02'',TRD_PRODUCT_DEAL.TRADE_AMT)),0)
	-nvl(sum(decode(TRD_PRODUCT_DEAL.PS,''T13'',TRD_PRODUCT_DEAL.TRADE_AMT)),0)
	-nvl(sum(decode(TRD_PRODUCT_DEAL.PS,''T14'',TRD_PRODUCT_DEAL.TRADE_AMT)),0)
	-nvl(sum(decode(TRD_PRODUCT_DEAL.PS,''T11'',TRD_PRODUCT_DEAL.TRADE_AMT)),0)
	-nvl(sum(decode(TRD_PRODUCT_DEAL.PS,''T05'',TRD_PRODUCT_DEAL.TRADE_AMT)),0) as  MKT,
	nvl(sum(decode(TRD_PRODUCT_DEAL.PS,''T01'',TRD_PRODUCT_DEAL.SHARE_AMT)),0)
	+nvl(sum(decode(TRD_PRODUCT_DEAL.PS,''T07'',TRD_PRODUCT_DEAL.SHARE_AMT)),0)
	+nvl(sum(decode(TRD_PRODUCT_DEAL.PS,''T17'',TRD_PRODUCT_DEAL.SHARE_AMT)),0)
	+nvl(sum(decode(TRD_PRODUCT_DEAL.PS,''T04'',TRD_PRODUCT_DEAL.SHARE_AMT)),0)
	+nvl(sum(decode(TRD_PRODUCT_DEAL.PS,''T36'',TRD_PRODUCT_DEAL.SHARE_AMT)),0)
	-nvl(sum(decode(TRD_PRODUCT_DEAL.PS,''T03'',TRD_PRODUCT_DEAL.SHARE_AMT)),0)
	-nvl(sum(decode(TRD_PRODUCT_DEAL.PS,''T12'',TRD_PRODUCT_DEAL.SHARE_AMT)),0)
	-nvl(sum(decode(TRD_PRODUCT_DEAL.PS,''T09'',TRD_PRODUCT_DEAL.SHARE_AMT)),0)
	+nvl(sum(decode(TRD_PRODUCT_DEAL.PS,''T10'',TRD_PRODUCT_DEAL.SHARE_AMT)),0)
	-nvl(sum(decode(TRD_PRODUCT_DEAL.PS,''T19'',TRD_PRODUCT_DEAL.SHARE_AMT)),0)
	-nvl(sum(decode(TRD_PRODUCT_DEAL.PS,''T02'',TRD_PRODUCT_DEAL.SHARE_AMT)),0)
	-nvl(sum(decode(TRD_PRODUCT_DEAL.PS,''T13'',TRD_PRODUCT_DEAL.SHARE_AMT)),0)
	-nvl(sum(decode(TRD_PRODUCT_DEAL.PS,''T14'',TRD_PRODUCT_DEAL.SHARE_AMT)),0)
	-nvl(sum(decode(TRD_PRODUCT_DEAL.PS,''T11'',TRD_PRODUCT_DEAL.SHARE_AMT)),0)
	-nvl(sum(decode(TRD_PRODUCT_DEAL.PS,''T05'',TRD_PRODUCT_DEAL.SHARE_AMT)),0) as  QTY, FIN_PRODUCT_TYPE2.TYPE_4 windAssetType,
	FIN_PRODUCT_TYPE2.TYPE_5 windAssetType2,
	FIN_PRODUCT_TYPE2.TYPE_6 assetType,
	FIN_PRODUCT_TYPE2.TYPE_7 assetType2,
	FIN_PRODUCT_ADD2.INVEST_NATURE investNature,
	REP_ASSET_DEPT2.REP_ASSET_TYPE deptType,
	REP_ASSET_DEPT2.REP_ASSET_TYPE deptType2,
	TRD_PRODUCT_DEAL.FINPROD_ID finprodId,
	FIN_PRODUCT2.ISSUER issuer,
	MST_CUSTOMER_INFO2.INDUSTRY industry,
	MST_CUSTOMER_INFO2.INDUSTRY2 industry2,
	ZXRATING2.GRADE_RESULT bondGradeType,
	ZTRATING2.GRADE_RESULT bodyGradeType,
	TRD_PRODUCT_DEAL_ADD.PORTFOLIO_ID portfolioId,
	FIN_PRODUCT2.MDATE mdate
	FROM TRD_PRODUCT_DEAL TRD_PRODUCT_DEAL
	INNER JOIN TRD_PRODUCT_DEAL_ADD ON TRD_PRODUCT_DEAL.TRADE_ID=TRD_PRODUCT_DEAL_ADD.TRADE_ID
	LEFT JOIN FIN_PRODUCT FIN_PRODUCT2 ON TRD_PRODUCT_DEAL.FINPROD_ID = FIN_PRODUCT2.FINPROD_ID
	LEFT JOIN (SELECT s1.*,s2.INDUSTRY,s2.INDUSTRY2 FROM MST_CUSTOMER_INFO s1 INNER JOIN MST_CUSTOMER_INFO_ADD s2 ON s1.CUSTOMER_ID=s2.CUSTOMER_ID) MST_CUSTOMER_INFO2 ON FIN_PRODUCT2.ISSUER = MST_CUSTOMER_INFO2.CUSTOMER_ID
	LEFT JOIN FIN_PRODUCT_TYPE FIN_PRODUCT_TYPE2 ON TRD_PRODUCT_DEAL.FINPROD_ID = FIN_PRODUCT_TYPE2.FINPROD_ID
	LEFT JOIN FIN_PRODUCT_ADD FIN_PRODUCT_ADD2 ON FIN_PRODUCT_ADD2.FINPROD_ID = TRD_PRODUCT_DEAL.FINPROD_ID
	LEFT JOIN TRD_PRODUCT_DEAL TRD_PRODUCT_DEAL2 ON TRD_PRODUCT_DEAL2.FINPROD_ID = TRD_PRODUCT_DEAL.FINPROD_ID
	LEFT JOIN REP_ASSET_DEPT REP_ASSET_DEPT2 ON TRD_PRODUCT_DEAL.FINPROD_ID = REP_ASSET_DEPT2.REP_FINPROD_ID
	LEFT JOIN (SELECT * FROM (SELECT O_CODE,GRADE_RESULT,ROW_NUMBER() OVER(PARTITION BY O_CODE ORDER BY CREATE_TIME desc) AS rn FROM MST_BOND_CREDIT_RATING T WHERE O_TYPE = ''02'' AND GRADE_DATE<=DATE ''${valDate}'') where rn=1 ) ZXRATING2 ON ZXRATING2.O_CODE = TRD_PRODUCT_DEAL.FINPROD_ID
	LEFT JOIN (SELECT * FROM (SELECT O_CODE,GRADE_DATE,GRADE_RESULT,ROW_NUMBER() OVER(PARTITION BY O_CODE ORDER BY CREATE_TIME desc) AS rn FROM MST_BOND_CREDIT_RATING T WHERE O_TYPE = ''01'' AND GRADE_DATE<=DATE ''${valDate}'') where rn=1 ) ZTRATING2 ON ZTRATING2.O_CODE = TRD_PRODUCT_DEAL.FINPROD_ID
	LEFT JOIN RSK_PORTFOLIO_PACKAGE_DTL DTL ON DTL.PORTFOLIO_ID = TRD_PRODUCT_DEAL_ADD.PORTFOLIO_ID
	WHERE TRD_PRODUCT_DEAL_ADD.PORTFOLIO_ID in ${portfolioCode} and TRD_PRODUCT_DEAL.TRADE_DATE=date''${valDate}'' and TRD_PRODUCT_DEAL.PS in (''T01'',''T07'',''T17'',''T02'',''T03'',''T12'',''T04'',''T05'',''T13'',''T09'',''T19'',''T36'',''T14'',''T10'',''T11'')
	GROUP BY
	TRD_PRODUCT_DEAL_ADD.PORTFOLIO_ID,FIN_PRODUCT_TYPE2.TYPE_4,FIN_PRODUCT_TYPE2.TYPE_5,FIN_PRODUCT_TYPE2.TYPE_6,FIN_PRODUCT_TYPE2.TYPE_7,FIN_PRODUCT_ADD2.INVEST_NATURE, REP_ASSET_DEPT2.REP_ASSET_TYPE,
	TRD_PRODUCT_DEAL.FINPROD_ID,FIN_PRODUCT2.ISSUER,MST_CUSTOMER_INFO2.INDUSTRY,MST_CUSTOMER_INFO2.INDUSTRY2,ZXRATING2.GRADE_RESULT,ZTRATING2.GRADE_RESULT,FIN_PRODUCT2.MDATE';
	content5:='SELECT
	nvl(SUM(nvl(PTL_SEC_VALUTION.DSC_COST_AMT, 0)),0) AS CST,
	nvl(SUM(nvl(PTL_SEC_VALUTION.SHARE_AMT, 0)),0) AS QTY,
	nvl(SUM(nvl(PTL_SEC_VALUTION.TDY_FLOAT_INGPL, 0) + nvl(PTL_SEC_VALUTION.DSC_COST_AMT, 0)+nvl(PTL_SEC_VALUTION.TDY_INTINCEXP, 0)+nvl(PTL_SEC_VALUTION.DELAY_PAY_AMT, 0)),0) AS MKT,
	FIN_PRODUCT_TYPE.TYPE_4 windAssetType,
	FIN_PRODUCT_TYPE.TYPE_5 windAssetType2,
	FIN_PRODUCT_TYPE.TYPE_6 assetType,
	FIN_PRODUCT_TYPE.TYPE_7 assetType2,
	FIN_PRODUCT_ADD.INVEST_NATURE investNature,
	REP_ASSET_DEPT.REP_ASSET_TYPE deptType,
	REP_ASSET_DEPT.REP_ASSET_TYPE deptType2,
	PTL_SEC_VALUTION.FINPROD_ID finprodId,
	FIN_PRODUCT.ISSUER issuer,
	MST_CUSTOMER_INFO.INDUSTRY industry,
	MST_CUSTOMER_INFO.INDUSTRY2 industry2,
	ZXRATING.GRADE_RESULT bondGradeType,
	ZTRATING.GRADE_RESULT bodyGradeType,
	PTL_SEC_VALUTION.PORTFOLIO_ID PORTFOLIO_ID,
	FIN_PRODUCT.MDATE mdate
	FROM PTL_SEC_VALUTION
	LEFT JOIN FIN_PRODUCT ON PTL_SEC_VALUTION.FINPROD_ID = FIN_PRODUCT.FINPROD_ID
	LEFT JOIN (SELECT s1.*,s2.INDUSTRY,s2.INDUSTRY2 FROM MST_CUSTOMER_INFO s1 INNER JOIN MST_CUSTOMER_INFO_ADD s2 ON s1.CUSTOMER_ID=s2.CUSTOMER_ID) MST_CUSTOMER_INFO ON FIN_PRODUCT.ISSUER = MST_CUSTOMER_INFO.CUSTOMER_ID
	LEFT JOIN FIN_PRODUCT_TYPE ON PTL_SEC_VALUTION.FINPROD_ID = FIN_PRODUCT_TYPE.FINPROD_ID
	LEFT JOIN FIN_PRODUCT_ADD ON FIN_PRODUCT_ADD.FINPROD_ID = PTL_SEC_VALUTION.FINPROD_ID
	LEFT JOIN REP_ASSET_DEPT ON PTL_SEC_VALUTION.FINPROD_ID = REP_ASSET_DEPT.REP_FINPROD_ID
	LEFT JOIN (SELECT * FROM (SELECT O_CODE,GRADE_RESULT,ROW_NUMBER() OVER(PARTITION BY O_CODE ORDER BY CREATE_TIME desc) AS rn FROM MST_BOND_CREDIT_RATING T WHERE O_TYPE = ''02'' AND GRADE_DATE<=DATE ''${valDate}'') where rn=1 ) ZXRATING ON ZXRATING.O_CODE = PTL_SEC_VALUTION.FINPROD_ID
	LEFT JOIN (SELECT * FROM (SELECT O_CODE,GRADE_DATE,GRADE_RESULT,ROW_NUMBER() OVER(PARTITION BY O_CODE ORDER BY CREATE_TIME desc) AS rn FROM MST_BOND_CREDIT_RATING T WHERE O_TYPE = ''01'' AND GRADE_DATE<=DATE ''${valDate}'') where rn=1 ) ZTRATING ON ZTRATING.O_CODE = PTL_SEC_VALUTION.FINPROD_ID
	WHERE PTL_SEC_VALUTION.PORTFOLIO_ID IN ${portfolioCode} AND PTL_SEC_VALUTION.CDATE = DATE ''${valDate}''
	GROUP BY
	PTL_SEC_VALUTION.PORTFOLIO_ID,FIN_PRODUCT_TYPE.TYPE_4,FIN_PRODUCT_TYPE.TYPE_5,FIN_PRODUCT_TYPE.TYPE_6,FIN_PRODUCT_TYPE.TYPE_7,FIN_PRODUCT_ADD.INVEST_NATURE,REP_ASSET_DEPT.REP_ASSET_TYPE,
	PTL_SEC_VALUTION.FINPROD_ID,FIN_PRODUCT.ISSUER,MST_CUSTOMER_INFO.INDUSTRY,MST_CUSTOMER_INFO.INDUSTRY2,ZXRATING.GRADE_RESULT,ZTRATING.GRADE_RESULT,FIN_PRODUCT.MDATE';
    update RSK_ISUP_INDICATOR_PARA_DTL set content = content1  where PARA_CODE = 'DQRZSGJYRYNDZCJZ' and PARA_GRANULARITY='04';	
	update RSK_ISUP_INDICATOR_PARA_DTL set content = content2  where PARA_CODE = 'XJDQZCSYQXCGJSTDZCGM' and PARA_GRANULARITY='04';
    update RSK_ISUP_INDICATOR_PARA_DTL set content = content3  where PARA_CODE = 'FHMB' and PARA_GRANULARITY='01';
    update RSK_ISUP_INDICATOR_PARA_DTL set content = content3  where PARA_CODE = 'FHMB' and PARA_GRANULARITY='02';
    update RSK_ISUP_INDICATOR_PARA_DTL set content = content3  where PARA_CODE = 'FHMB' and PARA_GRANULARITY='03';
	update RSK_ISUP_INDICATOR_PARA_DTL set content = content4  where PARA_CODE = 'FHMB' and PARA_GRANULARITY='04';
    update RSK_ISUP_INDICATOR_PARA_DTL set content = content5  where PARA_CODE = 'FHMB' and PARA_GRANULARITY='05';
end;